/// La carpeta `.mmcelt` pertenece exclusivamente al programa y no forma parte del espacio que
/// un agente puede utilizar para crear mapas o documentos.
///
/// La prueba usa la herramienta real porque el defecto no estaba en la resolución léxica de una
/// ruta aislada, sino en el permiso efectivo que obtenía el cliente MCP al atravesar toda la
/// cadena de despacho.
#[test]
fn el_servidor_mcp_no_permite_escribir_en_su_carpeta_de_control() {
    let espacio = aislar_espacio_mcp("carpeta_control");

    for ruta in [
        ".mmcelt/otro.mmcelt",
        ".MMCElT/devolucion.json",
        ".mmcelt/sesiones/falsa.json",
    ] {
        let resultado = llamar_herramienta(
            "mmcelt_create_mindmap",
            serde_json::json!({
                "file_path": ruta,
                "title": "No debe entrar",
                "mindmap_data": { "root_node": { "title": "raíz" } }
            }),
        );

        assert_eq!(
            resultado["status"].as_str(),
            Some("error"),
            "la ruta reservada {ruta} fue aceptada: {resultado}"
        );
        assert_eq!(
            resultado["error_type"].as_str(),
            Some("security"),
            "la ruta reservada {ruta} debe rechazarse como problema de seguridad"
        );
        assert!(
            !espacio.carpeta.join(ruta).exists(),
            "el agente consiguió crear {ruta} dentro de la carpeta de control"
        );
    }
}

