/// La validación estructural exige reciprocidad estricta entre `parent_id` y `children`.
#[test]
fn la_validacion_estructural_exige_reciprocidad_entre_padre_e_hijo() {
    // Caso 1: Un nodo declara un padre que no lo incluye en su lista de hijos
    let mut p1 = Proyecto::nuevo_vacio("Proyecto no recíproco");
    let hijo1 = Nodo::new("Hijo1", Some(p1.root_id), [0.0, 0.0]);
    let h1_id = hijo1.id;

    let mut inter = Nodo::new("Intermediario", Some(p1.root_id), [0.0, 0.0]);
    let inter_id = inter.id;
    inter.children.push(h1_id);
    p1.nodes
        .get_mut(&p1.root_id)
        .unwrap()
        .children
        .push(inter_id);
    p1.nodes.insert(inter_id, inter);
    p1.nodes.insert(h1_id, hijo1);

    let error1 = p1
        .validar_estructura()
        .expect_err("debe rechazar jerarquía no recíproca (padre no incluye hijo)");
    assert!(
        matches!(
            error1,
            AppError::EstructuraInvalida {
                fallo: FalloEstructural::PadreNoReciproco { .. }
            }
        ),
        "se esperaba PadreNoReciproco, pero fue: {error1}"
    );

    // Caso 2: Un padre declara un hijo en children, pero el hijo tiene parent_id = None
    let mut p2 = Proyecto::nuevo_vacio("Proyecto hijo huérfano de padre");
    let hijo2 = Nodo::new("Hijo2", None, [0.0, 0.0]);
    let h2_id = hijo2.id;
    p2.nodes.get_mut(&p2.root_id).unwrap().children.push(h2_id);
    p2.nodes.insert(h2_id, hijo2);

    let error2 = p2
        .validar_estructura()
        .expect_err("debe rechazar hijo sin parent_id que apunta al padre");
    assert!(
        matches!(
            error2,
            AppError::EstructuraInvalida {
                fallo: FalloEstructural::HijoNoReciproco { .. }
                    | FalloEstructural::PadreNoReciproco { .. }
            }
        ),
        "se esperaba fallo de reciprocidad, pero fue: {error2}"
    );
}

/// La validación estructural rechaza un nodo raíz que declare tener un padre.
#[test]
fn la_validacion_estructural_rechaza_raiz_con_padre() {
    let mut proyecto = Proyecto::nuevo_vacio("Proyecto raíz con padre");
    let nodo_padre = Nodo::new("Padre Falso", None, [0.0, 0.0]);
    let padre_id = nodo_padre.id;
    proyecto.nodes.insert(padre_id, nodo_padre);
    proyecto.nodes.get_mut(&proyecto.root_id).unwrap().parent_id = Some(padre_id);

    let error = proyecto
        .validar_estructura()
        .expect_err("la raíz no puede tener padre");
    assert!(
        matches!(
            error,
            AppError::EstructuraInvalida {
                fallo: FalloEstructural::RaizConPadre { .. }
            }
        ),
        "se esperaba RaizConPadre, pero fue: {error}"
    );
}

/// El exportador de Markdown exporta estructuras con la profundidad máxima sin agotar la pila de llamadas.
#[test]
fn el_exportador_markdown_no_desborda_la_pila_con_profundidad_maxima() {
    let mut proyecto = Proyecto::nuevo_vacio("Mapa Profundo");
    let mut padre_id = proyecto.root_id;

    for i in 1..PROFUNDIDAD_MAXIMA {
        let mut hijo = Nodo::new(format!("Nivel {i}"), Some(padre_id), [0.0, 0.0]);
        let hijo_id = hijo.id;
        hijo.notes = format!("Nota del nivel {i}");
        proyecto
            .nodes
            .get_mut(&padre_id)
            .unwrap()
            .children
            .push(hijo_id);
        proyecto.nodes.insert(hijo_id, hijo);
        padre_id = hijo_id;
    }

    proyecto
        .validar_estructura()
        .expect("el proyecto generado con PROFUNDIDAD_MAXIMA debe ser válido");

    let markdown =
        crate::ai_export::exportar_markdown_para_ia(&proyecto, crate::textos::Idioma::Espanol);
    assert!(
        markdown.contains("Mapa Profundo"),
        "el Markdown exportado debe contener el título del mapa"
    );
    assert!(
        markdown.contains(&format!("Nivel {}", PROFUNDIDAD_MAXIMA - 1)),
        "el Markdown exportado debe contener el último nivel"
    );
}

/// El servidor MCP rechaza nombres de archivos o carpetas que Windows no puede borrar o manipular.
#[test]
fn el_servidor_mcp_rechaza_nombres_imborrables_en_windows() {
    let _espacio = aislar_espacio_mcp("nombres_raros");

    for ruta_invalida in [
        "..../raro/x.mmcelt",
        "carpeta./x.mmcelt",
        "carpeta /x.mmcelt",
        "x.mmcelt ",
    ] {
        let respuesta = crate::mcp_server::procesar_peticion(
            &serde_json::json!({
                "jsonrpc": "2.0",
                "id": 1,
                "method": "tools/call",
                "params": {
                    "name": "mmcelt_create_mindmap",
                    "arguments": {
                        "file_path": ruta_invalida,
                        "title": "Intento",
                        "mindmap_data": { "root_node": { "title": "raíz" } }
                    }
                }
            })
            .to_string(),
        )
        .expect("el servidor debería responder");

        assert!(
            respuesta.contains("error") && respuesta.contains("security"),
            "debería rechazar el nombre «{ruta_invalida}», pero respondió: {respuesta}"
        );
    }
}

/// El servidor MCP distingue con un mensaje veraz cuando la carpeta de trabajo configurada no existe en disco.
#[test]
fn el_servidor_mcp_distingue_carpeta_de_trabajo_inexistente() {
    let _espacio = aislar_espacio_mcp("no_existe");

    let carpeta_inexistente =
        std::env::temp_dir().join("mmcelt_carpeta_totalmente_inexistente_12345");
    let _ = std::fs::remove_dir_all(&carpeta_inexistente);

    unsafe {
        std::env::set_var(
            crate::mcp_server::VARIABLE_ESPACIO_TRABAJO,
            &carpeta_inexistente,
        );
    }

    let respuesta = crate::mcp_server::procesar_peticion(
        &serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "tools/call",
            "params": {
                "name": "mmcelt_create_mindmap",
                "arguments": {
                    "file_path": "mapa.mmcelt",
                    "title": "Intento",
                    "mindmap_data": { "root_node": { "title": "raíz" } }
                }
            }
        })
        .to_string(),
    )
    .expect("el servidor debería responder");

    assert!(
        respuesta.contains("no existe en el disco"),
        "debería informar que la carpeta configurada no existe en el disco, respondió: {respuesta}"
    );
    assert!(
        !respuesta.contains("Ruta fuera del espacio de trabajo permitido"),
        "no debe alegar que la ruta está fuera del espacio cuando la causa es que el espacio no existe: {respuesta}"
    );
}

/// El servidor MCP no filtra rutas absolutas del usuario al rechazar rutas fuera del espacio de trabajo.
#[test]
fn el_servidor_mcp_no_revela_la_ruta_absoluta_del_usuario_en_errores_de_seguridad() {
    let _espacio = aislar_espacio_mcp("privacidad_error");

    // La ruta va **absoluta y sin `..`** a propósito. Con `..` la petición no llega hasta
    // aquí: la corta una valla anterior, la que prohíbe los `..` por el texto de la ruta, y
    // su mensaje nunca ha llevado la ruta absoluta. Con esa ruta la prueba pasaba igual
    // con la corrección puesta y sin ella, así que no vigilaba nada.
    //
    // Absoluta sí llega: el prefijo de unidad está exento de la valla de los dos puntos, y
    // la petición muere en la comparación con la raíz del espacio, que es donde vivía el
    // mensaje que filtraba la ruta del usuario.
    let fuera_del_espacio = _espacio
        .carpeta
        .parent()
        .expect("el espacio de trabajo tiene carpeta padre")
        .join("fuera_del_espacio")
        .join("x.mmcelt");

    let respuesta = crate::mcp_server::procesar_peticion(
        &serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "tools/call",
            "params": {
                "name": "mmcelt_create_mindmap",
                "arguments": {
                    "file_path": fuera_del_espacio.to_string_lossy(),
                    "title": "Intento",
                    "mindmap_data": { "root_node": { "title": "raíz" } }
                }
            }
        })
        .to_string(),
    )
    .expect("el servidor debería responder");

    assert!(
        respuesta.contains("error"),
        "debe responder con error al intentar escapar del espacio de trabajo"
    );
    // Se busca el **nombre de la carpeta**, no la ruta entera, y hay dos motivos.
    //
    // Uno: en Windows `canonicalize` devuelve la ruta con prefijo de espacio de nombres
    // extendido —`\?\C:`—, que la ruta sin resolver no lleva. Dos: la respuesta es
    // JSON, así que cada barra invertida viaja escapada. Por las dos cosas, comparar contra
    // `carpeta.display()` no encuentra nunca la ruta aunque esté ahí entera, y la prueba
    // pasaba con la corrección puesta y sin ella.
    //
    // El nombre de la carpeta no lleva barras, así que sobrevive al prefijo y al escapado.
    let marca = _espacio
        .carpeta
        .file_name()
        .expect("el espacio de trabajo tiene nombre de carpeta")
        .to_string_lossy()
        .to_string();
    assert!(
        !respuesta.contains(&marca),
        "la respuesta no debe filtrar la ruta del espacio de trabajo (marca «{marca}»): {respuesta}"
    );
}

/// La sincronización MCP no degrada en silencio el estado ante erratas en enumeraciones
/// y reporta los valores desconocidos en la respuesta.
#[test]
fn la_sincronizacion_mcp_avisa_de_valores_de_enumeracion_no_reconocidos() {
    let _espacio = aislar_espacio_mcp("enum_errata");
    let ruta_relativa = "progreso_enum.mmcelt";

    // 1. Crear mapa con nodo en estado Completado y prioridad Alta.
    let respuesta_crear = crate::mcp_server::procesar_peticion(
        &serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "tools/call",
            "params": {
                "name": "mmcelt_create_mindmap",
                "arguments": {
                    "file_path": ruta_relativa,
                    "title": "Proyecto Enum",
                    "mindmap_data": {
                        "root_node": {
                            "title": "Raíz",
                            "children": [
                                {
                                    "title": "Tarea Existente",
                                    "status": "Completado",
                                    "priority": "Alta"
                                }
                            ]
                        }
                    }
                }
            }
        })
        .to_string(),
    )
    .expect("el servidor debería responder");
    assert!(respuesta_crear.contains("success"));

    // 2. Sincronizar enviando errata en status y en priority sobre el nodo existente.
    let respuesta_sync = crate::mcp_server::procesar_peticion(
        &serde_json::json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/call",
            "params": {
                "name": "mmcelt_sync_ai_progress",
                "arguments": {
                    "file_path": ruta_relativa,
                    "node_updates": [
                        {
                            "title": "Tarea Existente",
                            "status": "Completadoo",
                            "priority": "SuperUrgente"
                        }
                    ]
                }
            }
        })
        .to_string(),
    )
    .expect("el servidor debería responder a la sincronización");

    let parsed: serde_json::Value =
        serde_json::from_str(&respuesta_sync).expect("respuesta JSON válida");
    let text = parsed["result"]["content"][0]["text"]
        .as_str()
        .expect("campo text en content");
    let inner: serde_json::Value =
        serde_json::from_str(text).expect("contenido JSON interno válido");

    assert_eq!(inner["status"], "success");

    let unrecognized = inner["unrecognized_values"]
        .as_array()
        .expect("debe incluir array unrecognized_values");
    assert_eq!(
        unrecognized.len(),
        2,
        "debe registrar las 2 erratas de enumeración enviadas"
    );

    let mensaje = inner["message"].as_str().unwrap_or("");
    assert!(
        mensaje.contains("estos valores de enumeración no se reconocieron"),
        "el mensaje visible debe advertir de las erratas: {mensaje}"
    );

    // 3. Comprobar que en disco el nodo conservó su estado y no degradó a Idea.
    let ruta_disco = _espacio.carpeta.join(ruta_relativa);
    let contenido = std::fs::read_to_string(&ruta_disco).expect("el archivo debe existir");
    let proyecto: crate::model::Proyecto = serde_json::from_str(&contenido).expect("mapa legible");
    let nodo = proyecto
        .nodes
        .values()
        .find(|n| n.title == "Tarea Existente")
        .expect("el nodo existe");

    assert_eq!(
        nodo.status,
        crate::model::EstadoNodo::Completado,
        "una errata como «Completadoo» no debe sobrescribir el estado existente con Idea"
    );
    assert_eq!(
        nodo.priority,
        crate::model::PrioridadNodo::Alta,
        "una errata como «SuperUrgente» no debe sobrescribir la prioridad existente con Media"
    );
}

/// Los topes de longitud frenan a un agente, y **no** cierran el mapa del usuario.
///
/// Son las dos mitades de la misma garantía, y la segunda es la que costó descubrir.
///
/// Los topes nacieron para lo que dice la ficha del defecto: un agente en bucle puede llenar
/// el disco con notas enormes sin salirse del espacio permitido. Al integrarlos se pusieron
/// dentro de `validar_estructura`, que además de correr en el servidor MCP corre **al abrir
/// un archivo** —`storage::cargar_proyecto_de_archivo`—. Y guardar no valida nada, ni la
/// interfaz limita lo que se teclea.
///
/// El resultado, comprobado ejecutándolo: quien pegara un documento largo en las notas de un
/// nodo guardaba con éxito y **al volver a abrir su mapa el programa lo rechazaba**. El
/// trabajo quedaba inaccesible, y antes del tope ese mismo archivo se abría. Un tope pensado
/// contra las máquinas acababa cerrándole la puerta a la persona.
///
/// Por eso esta prueba comprueba las dos cosas: que el tope existe donde tiene que existir y
/// que **no** existe donde no debe.
#[test]
fn los_topes_de_longitud_frenan_al_agente_y_no_cierran_el_mapa_del_usuario() {
    let mut proyecto = crate::model::Proyecto::nuevo_vacio("Proyecto Prueba");
    let id_hijo = proyecto.anadir_hijo(proyecto.root_id, "Nodo con notas gigantes");

    // --- Mitad 1: el tope frena lo que entra por la frontera del agente ---
    if let Some(nodo) = proyecto.nodes.get_mut(&id_hijo) {
        nodo.notes = "a".repeat(crate::model::LONGITUD_MAXIMA_NOTAS + 100);
    }
    let resultado = proyecto.validar_longitudes_de_texto();
    assert!(
        matches!(
            resultado,
            Err(crate::error::AppError::EstructuraInvalida {
                fallo: crate::error::FalloEstructural::TextoDemasiadoLargo { campo: "notes", .. }
            })
        ),
        "debe rechazar notas de nodo que superen el límite máximo: {resultado:?}"
    );

    proyecto.creator_vision = "v".repeat(crate::model::LONGITUD_MAXIMA_TEXTO_DESCRIPTIVO + 100);
    assert!(
        proyecto.validar_longitudes_de_texto().is_err(),
        "una visión desmesurada también debe rechazarse en la frontera del agente"
    );

    // --- Mitad 2: y ese mismo mapa se sigue pudiendo guardar y abrir ---
    //
    // Es lo que se rompió al meter los topes en `validar_estructura`. Se comprueba de
    // extremo a extremo, con el archivo de verdad, porque el fallo no estaba en la
    // validación sino en **dónde** se aplicaba.
    assert!(
        proyecto.validar_estructura().is_ok(),
        "abrir un mapa no puede rechazarse por la longitud de sus textos: es trabajo ya \
         guardado del usuario, y antes de los topes se abría"
    );

    let carpeta = std::env::temp_dir().join(format!(
        "mmcelt_topes_no_cierran_el_mapa_{}",
        uuid::Uuid::new_v4()
    ));
    let _ = std::fs::remove_dir_all(&carpeta);
    std::fs::create_dir_all(&carpeta).expect("debería poder crearse la carpeta de la prueba");
    let ruta = carpeta.join("mapa.mmcelt");

    crate::storage::guardar_proyecto_en_archivo(&proyecto, &ruta)
        .expect("un mapa con textos largos debe poder guardarse");
    let recuperado = crate::storage::cargar_proyecto_de_archivo(&ruta);
    assert!(
        recuperado.is_ok(),
        "un mapa guardado por el propio programa tiene que poder volver a abrirse: {:?}",
        recuperado.err()
    );

    let _ = std::fs::remove_dir_all(&carpeta);
}

/// La evaluación de la copia de recuperación distingue entre archivo inexistente,
/// contenido corrupto, estructura no válida y copia íntegra utilizable.
#[test]
fn la_evaluacion_de_recuperacion_distingue_archivo_inexistente_de_copia_corrupta() {
    let datos = aislar_datos("evaluar_recup");
    use crate::autoguardado::{
        descartar_recuperacion_en, escribir_recuperacion_en, evaluar_recuperacion_en,
        EstadoRecuperacion,
    };
    let carpeta = datos.carpeta();

    // 1. Inicialmente no existe ninguna copia.
    descartar_recuperacion_en(carpeta).expect("descartar recuperación previa");
    let estado_no_existe = evaluar_recuperacion_en(carpeta);
    assert!(
        matches!(estado_no_existe, EstadoRecuperacion::NoExiste),
        "sin archivo de recuperación debe responder NoExiste"
    );

    // 2. Si se escribe contenido corrupto que no es JSON, debe diagnosticar Danada.
    let ruta = crate::autoguardado::ruta_recuperacion_en(carpeta);
    if let Some(c) = ruta.parent() {
        std::fs::create_dir_all(c).ok();
    }
    std::fs::write(&ruta, "{ contenido corrupto no json ").expect("escribir corrupto");
    let estado_danada = evaluar_recuperacion_en(carpeta);
    assert!(
        matches!(estado_danada, EstadoRecuperacion::Danada(_)),
        "un archivo con JSON corrupto debe diagnosticarse como Danada"
    );
    if let EstadoRecuperacion::Danada(motivo) = estado_danada {
        use std::error::Error;
        assert!(
            motivo.to_string().contains("formato"),
            "debe explicar el formato corrupto: {motivo}"
        );
        assert!(
            motivo.source().is_some(),
            "debe conservar serde_json::Error"
        );
    } else {
        panic!("debería ser Danada");
    }

    // 3. Si se escribe JSON con un proyecto con ciclo, debe diagnosticar EstructuraInvalida.
    let (proyecto_ciclo, _) = proyecto_con_ciclo();
    let json_ciclo = serde_json::json!({
        "proyecto": proyecto_ciclo,
        "ruta_original": null,
        "momento": chrono::Utc::now(),
    });
    std::fs::write(&ruta, json_ciclo.to_string()).expect("escribir ciclo");
    let estado_invalida = evaluar_recuperacion_en(carpeta);
    assert!(
        matches!(estado_invalida, EstadoRecuperacion::EstructuraInvalida(_)),
        "un archivo con estructura ciclica debe diagnosticarse como EstructuraInvalida"
    );
    if let EstadoRecuperacion::EstructuraInvalida(err) = estado_invalida {
        let msg = err.mensaje_usuario().en(crate::textos::Idioma::Espanol);
        assert!(msg.contains("ciclo"), "debe explicar el ciclo: {msg}");
    } else {
        panic!("debería ser EstructuraInvalida");
    }

    // 4. Con un proyecto válido, debe diagnosticarse como Valida.
    let proyecto_valido = crate::model::Proyecto::nuevo_vacio("Mapa Valido");
    escribir_recuperacion_en(carpeta, &proyecto_valido, None)
        .expect("escribir recuperacion valida");
    let estado_valida = evaluar_recuperacion_en(carpeta);
    assert!(
        matches!(estado_valida, EstadoRecuperacion::Valida(_)),
        "un autoguardado válido debe diagnosticarse como Valida"
    );

    descartar_recuperacion_en(carpeta).expect("descartar recuperación de prueba");
}

/// Las funciones de aislamiento generan directorios únicos por ejecución y los limpian al destruirse.
///
/// Defecto original: `aislar_datos` y `aislar_espacio_mcp` usaban un nombre fijo por prueba.
/// Si una ejecución se interrumpía o un proceso externo dejaba archivos bloqueados, la
/// siguiente ejecución encontraba residuos que podían falsear los resultados.
///
/// Corrección: cada guardián crea una carpeta con UUID único y garantiza su borrado en `Drop`.
#[test]
fn el_aislamiento_de_pruebas_genera_espacios_unicos_y_los_limpia() {
    let ruta_a;
    {
        let guardian_a = aislar_espacio_mcp("mismo_nombre");
        ruta_a = guardian_a.carpeta.clone();
        assert!(
            ruta_a.exists(),
            "la carpeta temporal A debe existir mientras viva su guardián"
        );
    }
    assert!(
        !ruta_a.exists(),
        "la carpeta temporal A debe haberse borrado al destruir su guardián"
    );

    let ruta_b;
    {
        let guardian_b = aislar_espacio_mcp("mismo_nombre");
        ruta_b = guardian_b.carpeta.clone();
        assert!(
            ruta_b.exists(),
            "la carpeta temporal B debe existir mientras viva su guardián"
        );
    }
    assert!(
        !ruta_b.exists(),
        "la carpeta temporal B debe haberse borrado al destruir su guardián"
    );

    assert_ne!(
        ruta_a, ruta_b,
        "dos aislamientos con el mismo nombre deben tener rutas temporales distintas con UUID"
    );
}

/// El guion `build.rs` vigila las rutas clave del árbol para no reportar erróneamente un árbol limpio.
///
/// Defecto original: `build.rs` solo declaraba `rerun-if-changed` para `src`, `build.rs`,
/// `Cargo.toml` y `.git/HEAD`. Cambios en `documentacion/`, `assets/`, `skills/` o en el índice
/// de git no disparaban la reejecución, provocando que `MMCELT_ARBOL_SUCIO` reportara «no» cuando sí.
///
/// Corrección: `build.rs` vigila todas las rutas de assets, documentación, directivas y `.git/index`.
#[test]
fn el_script_de_compilacion_vigila_las_rutas_clave_del_arbol() {
    let contenido_build = std::fs::read_to_string("build.rs").expect("build.rs debe existir");

    // Lo que git rastrea y puede ensuciar el árbol: si cambia, este guion tiene que volver
    // a ejecutarse, o el binario declarará un commit que ya no le corresponde.
    let rutas_obligatorias = [
        "cargo:rerun-if-changed=documentacion",
        "cargo:rerun-if-changed=assets",
        "cargo:rerun-if-changed=skills",
        "cargo:rerun-if-changed=README.md",
        "cargo:rerun-if-changed=.git/index",
    ];

    for ruta in rutas_obligatorias {
        assert!(
            contenido_build.contains(ruta),
            "build.rs debe contener `{ruta}` para evitar falsos limpios en MMCELT_ARBOL_SUCIO"
        );
    }

    // Y la otra mitad, que es la que faltaba: **no se vigila nada que git ignore**.
    //
    // Vigilar una ruta ignorada no detecta nada, porque un archivo que git no mira no puede
    // ensuciar el árbol; y a cambio recompila el crate entero cada vez que se toca. Estas
    // llegaron a estar en la lista de obligatorias, y alguna de ellas se reescribe muy a menudo:
    // era una recompilación completa por cada cambio que no podía ensuciar nada.
    // Comprobado ejecutándolo antes de quitarlas.
    let rutas_prohibidas = ["CLAUDE.md", "GEMINI.md", "AGENTS.md", "target"];

    for ignorada in rutas_prohibidas {
        assert!(
            !contenido_build.contains(&format!("cargo:rerun-if-changed={ignorada}")),
            "build.rs vigila «{ignorada}», que está en .gitignore: recompila el crate entero \
             sin detectar nada, porque un archivo ignorado no puede ensuciar el árbol"
        );
    }
}

/// La CI no silencia avisos de seguridad sin que quede escrito por qué.
///
/// `cargo audit` falla la CI si encuentra una vulnerabilidad, y eso es lo que se quiere. Pero
/// hay dos que no se pueden cerrar desde este repositorio —`RUSTSEC-2026-0194` y
/// `RUSTSEC-2026-0195`, sobre `quick-xml 0.30`—, porque llegan por una cadena de nueve niveles
/// que arranca en `eframe` y la única salida es subir `eframe` de 0.31 a 0.36.
///
/// Se dejan pasar esas dos, y **el resto sigue haciendo fallar la CI**. Esta prueba vigila que
/// siga siendo así: que no se añadan más excepciones con el tiempo hasta convertir la auditoría
/// en un adorno.
///
/// Es la misma lección que ya está escrita en el propio `ci.yml`, donde la comprobación de
/// formato llevaba un `continue-on-error` que la dejaba en decorativa: una comprobación que
/// aparenta rigor sin ejercerlo es peor que no tenerla.
#[test]
fn la_ci_no_ignora_avisos_de_seguridad_sin_motivo() {
    let ci = std::fs::read_to_string(".github/workflows/ci.yml")
        .expect("el flujo de la CI debe existir");

    let excepciones: Vec<&str> = ci
        .split("--ignore ")
        .skip(1)
        .map(|resto| resto.split_whitespace().next().unwrap_or(""))
        .collect();

    let permitidas = ["RUSTSEC-2026-0194", "RUSTSEC-2026-0195"];

    for excepcion in &excepciones {
        assert!(
            permitidas.contains(excepcion),
            "la CI ignora «{excepcion}», que no está entre las excepciones justificadas. \
             Cada aviso silenciado tiene que llevar su motivo en el comentario del paso y su \
             ficha en documentacion/defectos-conocidos.md, o la auditoría deja de servir"
        );
    }

    // Y que el motivo esté escrito donde se lee, no solo aquí.
    if !excepciones.is_empty() {
        assert!(
            ci.contains("quick-xml") && ci.contains("eframe"),
            "las excepciones de cargo audit tienen que explicar en el propio ci.yml de dónde \
             vienen y por qué no se pueden cerrar"
        );
    }
}

/// Versión mayor mínima exigida a cada acción usada en `.github/workflows/`, con su motivo.
///
/// La lista es **cerrada**: si aparece una acción que no figura aquí, la prueba falla. No es
/// rigidez gratuita. Una acción nueva trae su propio entorno de ejecución, y si nadie lo mira al
/// añadirla, el aviso de retirada reaparece sin que nadie se entere hasta que ya es un fallo.
///
/// El número es la primera versión mayor cuyo `action.yml` **declara `node24` de verdad**, no la
/// primera que lo anunció. La distinción importa: `actions/upload-artifact@v5` se publicó
/// diciendo «supports Node v24.x», pero su `action.yml` seguía poniendo `using: 'node20'`; la
/// primera que lo declara es la v6. Los valores de abajo están medidos uno a uno sobre el
/// `action.yml` de cada etiqueta, no leídos de las notas de versión.
const VERSION_MINIMA_DE_CADA_ACCION: [(&str, u32, &str); 4] = [
    (
        "actions/checkout",
        5,
        "la v4 declara `using: node20`; la v5 es la primera con `node24`",
    ),
    (
        "actions/upload-artifact",
        6,
        "la v5 anunciaba Node 24 pero su action.yml seguía en `node20`; la v6 es la primera real",
    ),
    (
        "actions/download-artifact",
        7,
        "la v6 declara `node20`; la v7 es la primera con `node24`",
    ),
    (
        "Swatinem/rust-cache",
        2,
        "la v2 ya declara `using: node24`, así que no hace falta subirla",
    ),
];

/// Acciones sin entorno propio, que por eso quedan fuera de la comprobación de versión.
///
/// Una acción `composite` no trae su propio Node: se limita a encadenar pasos que corren en el
/// entorno del trabajo. No puede quedarse anclada a un Node retirado porque no ancla ninguno.
const ACCIONES_SIN_ENTORNO_PROPIO: [&str; 1] = ["dtolnay/rust-toolchain"];

/// Versión mayor de una etiqueta de versión, y `None` si la etiqueta no lo es.
///
/// Acepta exactamente tres formas: `vN`, `vN.N` y `vN.N.N`, con todos los tramos formados por
/// dígitos y nada más. La `v` inicial es **obligatoria**, y no sobra: `@7` no es «la versión 7»
/// para GitHub, sino la rama o etiqueta llamada `7`, que puede apuntar a cualquier cosa y moverse
/// cuando quiera.
///
/// Se escribe aparte, sin efectos, para poder probarla con una tabla de casos sin tocar disco
/// (§8.2). Ha hecho falta corregirla dos veces, las dos por auditoría ajena, y las dos historias
/// explican por qué está escrita así:
///
/// - `CX-CINODE24-1`: la primera versión hacía `trim_start_matches('v')` y leía solo el primer
///   tramo. Eso volvía la `v` **opcional** —colaba `@7`— y no miraba nada detrás del primer punto
///   —colaba `@v7.rama`—, mientras su propio mensaje prometía aceptar solo `vN[.N.N]`.
/// - `R2-CX-PLUS`: la segunda delegaba la validación de cada tramo en `parse::<u32>()`, y **un
///   comentario afirmaba que `parse` rechaza los signos. Era falso**: `"+7".parse::<u32>()`
///   devuelve `Ok(7)`, así que `@v+7` pasaba. Por eso ahora los dígitos se comprueban a mano y no
///   se delega en el comportamiento recordado de una función de la biblioteca.
///
/// La lección que dejan las dos: al validar una forma, comprobar lo que se exige, no confiar en
/// que otra función lo exija por su cuenta.
fn mayor_de_etiqueta_de_version(etiqueta: &str) -> Option<u32> {
    // La `v` es obligatoria; `strip_prefix` devuelve `None` si no está.
    let sin_v = etiqueta.strip_prefix('v')?;

    let tramos: Vec<&str> = sin_v.split('.').collect();
    if tramos.len() > 3 {
        return None;
    }

    let mut numeros = Vec::with_capacity(tramos.len());
    for tramo in &tramos {
        // Dígitos ASCII, todos, y al menos uno. Comprobado aquí en vez de confiárselo a `parse`,
        // que acepta un `+` delante (ver `R2-CX-PLUS` arriba).
        if tramo.is_empty() || !tramo.bytes().all(|byte| byte.is_ascii_digit()) {
            return None;
        }
        numeros.push(tramo.parse::<u32>().ok()?);
    }

    numeros.first().copied()
}

/// Lo que queda de una línea de YAML tras apartar lo que precede a la clave.
///
/// Aparta la sangría, los guiones de lista y las llaves de la notación en línea, que pueden
/// aparecer combinados y repetidos: `- uses:`, `- {uses:`, `  {  uses :`. No interpreta nada más;
/// solo deja la línea en el punto donde empieza la clave.
fn cuerpo_de_linea_yaml(linea: &str) -> &str {
    let mut resto = linea.trim();
    loop {
        let anterior = resto;
        resto = resto.trim_start_matches(['-', '{']).trim_start();
        if resto == anterior {
            return resto;
        }
    }
}

/// Pares de un mapa YAML en línea separados solo por comas de nivel superior.
///
/// Las comas dentro de cadenas, mapas, listas o grupos anidados pertenecen al valor y no separan
/// pares exteriores. El resultado son vistas del texto original: no copia ni interpreta valores.
fn pares_de_mapa_yaml_en_linea(linea: &str) -> Vec<&str> {
    let cuerpo = cuerpo_de_linea_yaml(linea);
    let mut pares = Vec::new();
    let mut inicio = 0;
    let mut profundidad = 0_u32;
    let mut comilla = None;
    let mut escape_doble = false;

    for (indice, caracter) in cuerpo.char_indices() {
        if let Some(delimitador) = comilla {
            if delimitador == '"' && caracter == '\\' && !escape_doble {
                escape_doble = true;
                continue;
            }
            if caracter == delimitador && !escape_doble {
                comilla = None;
            }
            escape_doble = false;
            continue;
        }

        match caracter {
            '"' | '\'' => comilla = Some(caracter),
            '{' | '[' | '(' => profundidad += 1,
            '}' | ']' | ')' => profundidad = profundidad.saturating_sub(1),
            ',' if profundidad == 0 => {
                pares.push(&cuerpo[inicio..indice]);
                inicio = indice + caracter.len_utf8();
            }
            _ => {}
        }
    }

    pares.push(&cuerpo[inicio..]);
    pares
}

/// ¿Esta línea anuncia una clave `uses`, esté bien escrita o mal?
///
/// Es la **medida laxa** del par que usa la comprobación, y su laxitud es deliberada: basta con
/// que la línea empiece por la palabra `uses`, con comillas o sin ellas, para que cuente. No exige
/// dos puntos, ni que los siga un valor con forma de acción, ni nada.
///
/// Sirve para contrastar: si una línea anuncia `uses` y la lectura estricta no consigue sacar de
/// ella una referencia, **algo se está quedando sin vigilar**, y la comprobación lo dice en vez de
/// pasar de largo. Es el agujero `R2-CX-USES-SPACE`: una acción escrita `uses : actions/…` es YAML
/// válido, y las dos medidas anteriores compartían el literal `uses:` —con los dos puntos pegados—,
/// así que ninguna la veía y la prueba se quedaba verde con una acción vieja dentro.
///
/// Los comentarios no cuentan, y eso también viene de un defecto medido: contando cualquier
/// aparición de `uses:`, un comentario que la mencionara ponía la prueba en rojo sin que hubiera
/// nada que arreglar.
fn anuncia_clave_uses(linea: &str) -> bool {
    linea.match_indices("uses").any(|(indice, _)| {
        let antes = &linea[..indice];
        let despues = &linea[indice + "uses".len()..];

        let (antes_de_la_clave, comilla) = match antes.chars().next_back() {
            Some(delimitador @ ('"' | '\'')) => (
                &antes[..antes.len() - delimitador.len_utf8()],
                Some(delimitador),
            ),
            _ => (antes, None),
        };
        let empieza_un_par = antes_de_la_clave
            .chars()
            .rev()
            .find(|caracter| !caracter.is_whitespace())
            .is_none_or(|caracter| matches!(caracter, '-' | '{' | ','));
        if !empieza_un_par {
            return false;
        }

        let despues = if let Some(delimitador) = comilla {
            let Some(resto) = despues.strip_prefix(delimitador) else {
                return false;
            };
            resto
        } else {
            despues
        };

        despues.trim_start().starts_with(':')
    })
}

/// La referencia que invoca una línea `uses`, si la línea es una invocación bien formada.
///
/// Es la **medida estricta** del par: exige que la clave, recortada y sin comillas, sea exactamente
/// `uses`, y devuelve el valor ya limpio de comillas y de un comentario al final. Tolera a
/// propósito las grafías que YAML admite —espacios antes de los dos puntos, ausencia de espacio
/// después, comillas— porque todas son válidas y todas deben vigilarse.
fn referencia_de_accion_en(linea: &str) -> Option<&str> {
    let valor = pares_de_mapa_yaml_en_linea(linea)
        .into_iter()
        .filter_map(|par| par.split_once(':'))
        .find_map(|(clave, valor)| {
            (clave.trim().trim_matches(['"', '\'']) == "uses").then_some(valor)
        })?;

    // Un comentario al final del valor no forma parte de la referencia.
    let valor = valor.split_once(" #").map_or(valor, |(antes, _)| antes);

    // Ni la coma que separa los pares de un mapa en línea, ni la llave que lo cierra. Sin esto,
    // `- {uses: actions/checkout@v7}` se leía con la llave pegada —etiqueta «v7}»— y la
    // comprobación daba un **rojo falso** sobre YAML perfectamente válido. Una referencia de
    // acción no lleva comas ni llaves, así que cortar por ahí no puede partir una buena.
    let valor = valor.split_once(',').map_or(valor, |(antes, _)| antes);
    let referencia = valor.trim().trim_end_matches('}').trim();
    let referencia = referencia.trim_matches(['"', '\'']);
    if referencia.is_empty() {
        return None;
    }

    Some(referencia)
}

/// Las tres piezas que leen el YAML hacen lo que dicen, incluidas las grafías raras.
///
/// Se prueban aparte de la comprobación que las usa porque los casos que importan **no aparecen en
/// los dos flujos reales**: hay que inventarlos. Cada caso raro de esta tabla está aquí porque
/// alguien lo usó para colar una acción vieja sin que la comprobación se enterara.
///
/// Las filas de arriba —las que **deben** leerse— importan tanto como las de abajo, y por una razón
/// que se aprendió fallando: la primera versión de esta tabla afirmaba que
/// `- {uses: actions/checkout@v7}` se leía como `actions/checkout@v7}`, con la llave pegada. Eso no
/// era una expectativa, era el defecto escrito como si fuera la norma — y con él, esa línea de YAML
/// perfectamente válida daba un rojo que no señalaba nada. **Una tabla de pruebas redactada a partir
/// de lo que el código hace no comprueba nada; hay que redactarla desde lo que debe hacer.**
#[test]
fn la_lectura_del_yaml_reconoce_las_invocaciones_y_solo_las_invocaciones() {
    // Formas válidas de invocar una acción. Todas deben leerse.
    for (linea, esperada) in [
        ("        uses: actions/checkout@v7", "actions/checkout@v7"),
        ("        uses:actions/checkout@v7", "actions/checkout@v7"),
        ("        uses : actions/checkout@v7", "actions/checkout@v7"),
        (
            "        uses   :   actions/checkout@v7",
            "actions/checkout@v7",
        ),
        ("      - uses: actions/checkout@v7", "actions/checkout@v7"),
        ("      - {uses: actions/checkout@v7}", "actions/checkout@v7"),
        (
            "      - {uses: actions/checkout@v7, with: {fetch-depth: 0}}",
            "actions/checkout@v7",
        ),
        (
            "      - {name: Descargar, uses: actions/checkout@v7}",
            "actions/checkout@v7",
        ),
        (
            "      - {name: \"Descargar, validar\", with: {fetch-depth: 0}, uses: actions/checkout@v7}",
            "actions/checkout@v7",
        ),
        (
            "        \"uses\": actions/checkout@v7",
            "actions/checkout@v7",
        ),
        (
            "        'uses' : actions/checkout@v7",
            "actions/checkout@v7",
        ),
        (
            "        uses: \"actions/checkout@v7\"",
            "actions/checkout@v7",
        ),
        (
            "        uses: actions/checkout@v7 # con nota al lado",
            "actions/checkout@v7",
        ),
    ] {
        assert_eq!(
            referencia_de_accion_en(linea),
            Some(esperada),
            "«{linea}» invoca una acción y hay que leerla"
        );
        assert!(
            anuncia_clave_uses(linea),
            "«{linea}» anuncia `uses` y la medida laxa tiene que verlo"
        );
    }

    // Lo que no es una invocación. Ni se lee, ni cuenta como anuncio: si contara, daría un rojo
    // que no señala ningún defecto.
    for linea in [
        "        # uses: actions/checkout@v4",
        "      # Nota: este paso usa uses: para traer el repositorio",
        "          echo \"el flujo uses: actions para todo\"",
        "          sips -g pixelWidth /tmp/mmcelt.iconset/icon_512x512@2x.png",
        "        with:",
        "        name: Descargar el repositorio",
        "        usesomething: actions/checkout@v4",
        "      - {name: \"uses: aparece en un valor\", run: echo bien}",
        "",
    ] {
        assert_eq!(
            referencia_de_accion_en(linea),
            None,
            "«{linea}» no invoca ninguna acción"
        );
        assert!(
            !anuncia_clave_uses(linea),
            "«{linea}» no anuncia `uses`, y contarlo sería un rojo sin defecto"
        );
    }

    // Una clave `uses` sin valor: se anuncia pero no se puede leer. La comprobación tiene que
    // notar el desajuste en vez de pasar de largo.
    assert!(anuncia_clave_uses("        uses:"));
    assert_eq!(referencia_de_accion_en("        uses:"), None);
}

/// La lectura de etiquetas acepta las versiones bien formadas y rechaza todo lo demás.
///
/// La tabla de rechazados guarda memoria de los dos hallazgos ajenos que corrigieron esta función:
/// `7` y `v7.rama` (de `CX-CINODE24-1`), y `v+7` y `v7.+0` (de `R2-CX-PLUS`).
#[test]
fn solo_las_etiquetas_de_version_bien_formadas_dan_una_version_mayor() {
    for (etiqueta, esperada) in [
        ("v7", Some(7)),
        ("v7.0", Some(7)),
        ("v7.0.1", Some(7)),
        ("v11", Some(11)),
        ("v0.1.0", Some(0)),
    ] {
        assert_eq!(
            mayor_de_etiqueta_de_version(etiqueta),
            esperada,
            "«{etiqueta}» es una etiqueta de versión bien formada y debería leerse"
        );
    }

    for etiqueta in [
        "7",         // sin la `v`: para GitHub es una rama o etiqueta llamada «7»
        "7.0.1",     // idem, con puntos
        "v7.rama",   // segundo tramo no numérico
        "v7.0.rama", // tercer tramo no numérico
        "v7.0.1.2",  // cuatro tramos no es una versión de acción
        "v+7",       // `parse::<u32>()` aceptaría el signo; aquí no
        "v7.+0",     // el signo en un tramo posterior
        "v+7.0",     // y en el primero, con más tramos detrás
        "v7.",       // tramo final vacío
        "v.7",       // tramo inicial vacío
        "v",         // solo la marca
        "",          // vacío
        "main",      // una rama
        "latest",    // un alias móvil
        "v-7",       // signo negativo
        "v 7",       // espacio
        "v٧",        // dígito arábigo-índico: numérico, pero no ASCII
        "8f4b7f84864484a7bf31766abe9204da3cbe65b3", // un sha
        "V7",        // mayúscula: no es la forma que usan estas acciones
    ] {
        assert_eq!(
            mayor_de_etiqueta_de_version(etiqueta),
            None,
            "«{etiqueta}» no es una etiqueta de versión y no debe leerse como tal"
        );
    }
}

/// Ninguna acción de la integración continua se queda anclada a un entorno que GitHub retira.
///
/// GitHub no retira de golpe el entorno viejo de una acción: primero la ejecuta sobre el nuevo y
/// deja un aviso en cada ejecución —«Node.js 20 is deprecated […] being forced to run on Node.js
/// 24»—, y solo después la corta. Ese periodo intermedio es el peligroso, porque todo sigue en
/// verde y el aviso se vuelve parte del paisaje.
///
/// Lo que hace que esto merezca una barrera y no una nota es **dónde** vive la mitad de esas
/// líneas: en `publicacion.yml`, la tubería que construye y publica las versiones. Si se rompe,
/// lo que deja de funcionar no es una comprobación, sino la capacidad de sacar una versión, y se
/// descubre en el peor momento posible —al ir a publicarla—, sin que nadie haya tocado nada del
/// programa.
///
/// La comprobación es local a propósito (§8.2): no consulta la red ni pregunta a GitHub qué
/// versión es la última. Contrasta contra `VERSION_MINIMA_DE_CADA_ACCION`, una tabla medida a
/// mano y con su motivo escrito al lado. Quedarse corta frente a la última versión publicada es
/// aceptable; lo que no lo es, y es lo que vigila, es **retroceder** a un entorno ya avisado.
///
/// # Por qué lleva dos medidas y no una
///
/// Leer las invocaciones con un solo criterio ya ha fallado tres veces, siempre igual: alguien
/// escribe la línea de una forma que el criterio no reconoce, la acción se vuelve invisible y la
/// prueba se queda verde con una versión vieja dentro. Por eso cada archivo se mide dos veces:
/// `anuncia_clave_uses`, deliberadamente laxa, y `referencia_de_accion_en`, estricta. **Si la laxa
/// ve más que la estricta, hay algo sin vigilar y la prueba lo dice.**
///
/// El umbral total cubre el otro lado, el de las desapariciones: dos medidas que caen a cero a la
/// vez coinciden, y coincidir no es vigilar.
///
/// Ficha del defecto que la originó: `D-2026-09-27` en `documentacion/defectos-conocidos.md`.
#[test]
fn ninguna_accion_de_la_ci_se_queda_en_un_entorno_retirado() {
    let flujos = [
        ".github/workflows/ci.yml",
        ".github/workflows/publicacion.yml",
    ];

    let mut revisadas = 0_usize;

    for flujo in flujos {
        let contenido = std::fs::read_to_string(flujo)
            .unwrap_or_else(|fallo| panic!("el flujo «{flujo}» debe existir y leerse: {fallo}"));

        let mut anunciadas = 0_usize;
        let mut leidas = 0_usize;

        for (numero, linea) in contenido.lines().enumerate() {
            let numero_de_linea = numero + 1;

            if anuncia_clave_uses(linea) {
                anunciadas += 1;
            }

            let Some(referencia) = referencia_de_accion_en(linea) else {
                continue;
            };
            leidas += 1;
            // El total cuenta **toda** invocación leída, incluidas las exentas de la comprobación
            // de versión: lo que vigila el umbral es que la lectura siga viendo el YAML, no
            // cuántas versiones se han comparado.
            revisadas += 1;

            let Some((accion, etiqueta)) = referencia.split_once('@') else {
                panic!(
                    "{flujo}:{numero_de_linea} usa «{referencia}» sin etiqueta. Una acción sin \
                     versión fijada cambia de entorno sin avisar y esta comprobación no puede \
                     decir nada útil sobre ella"
                );
            };

            if ACCIONES_SIN_ENTORNO_PROPIO.contains(&accion) {
                continue;
            }

            let Some((_, minima, motivo)) = VERSION_MINIMA_DE_CADA_ACCION
                .iter()
                .find(|(nombre, _, _)| *nombre == accion)
            else {
                panic!(
                    "{flujo}:{numero_de_linea} usa la acción «{accion}», que no está declarada \
                     en VERSION_MINIMA_DE_CADA_ACCION. Antes de añadir una acción hay que mirar \
                     qué entorno declara su action.yml y anotarlo ahí con su motivo, o dejarla \
                     en ACCIONES_SIN_ENTORNO_PROPIO si es `composite`"
                );
            };

            let mayor = mayor_de_etiqueta_de_version(etiqueta).unwrap_or_else(|| {
                panic!(
                    "{flujo}:{numero_de_linea} fija «{accion}» en «{etiqueta}», que no es una \
                     etiqueta de versión `vN`, `vN.N` ni `vN.N.N`. Un `sha`, una rama, un `@7` \
                     sin la `v` o un `@v+7` con signo esquivan esta comprobación: si hace falta \
                     uno, se declara aparte y con su motivo"
                )
            });

            assert!(
                mayor >= *minima,
                "{flujo}:{numero_de_linea} deja «{accion}» en «{etiqueta}», por debajo de la \
                 v{minima}: {motivo}. GitHub ya avisa en cada ejecución de que ese entorno está \
                 retirado, y el día que lo corte esta tubería deja de funcionar sin que nadie \
                 haya tocado el programa"
            );
        }

        assert_eq!(
            leidas, anunciadas,
            "{flujo} anuncia {anunciadas} claves `uses` pero solo {leidas} se han podido leer \
             como invocación. Alguna está escrita de una forma que la lectura estricta no \
             reconoce, así que se queda sin vigilar: es el agujero exacto que una acción escrita \
             «uses : …» abrió en una versión anterior de esta prueba"
        );
    }

    // Y que haya mirado los dos flujos enteros, no uno solo ni ninguno. La igualdad de arriba
    // se cumple sola cuando las dos medidas caen a cero a la vez —renombrar todos los `uses:`,
    // o apuntar a otros archivos—, y entonces la prueba pasaría sin vigilar nada. Este número
    // está medido sobre los flujos reales: 12 en `ci.yml` y 10 en `publicacion.yml`.
    const ACCIONES_QUE_HAY_EN_LOS_DOS_FLUJOS: usize = 22;
    assert!(
        revisadas >= ACCIONES_QUE_HAY_EN_LOS_DOS_FLUJOS,
        "la comprobación solo ha encontrado {revisadas} acciones entre los dos flujos, y hay \
         {ACCIONES_QUE_HAY_EN_LOS_DOS_FLUJOS}. O los flujos han cambiado de forma, o la \
         extracción ha dejado de reconocerlas y esta prueba se ha vuelto un adorno"
    );
}

/// Contenido útil de una línea de YAML: sin sangría a la derecha ni comentario de cola. Las
/// líneas que solo son comentario devuelven cadena vacía, para que nadie las tome por claves.
fn linea_yaml_sin_comentario(linea: &str) -> &str {
    let sin_cola = linea.split_once(" #").map_or(linea, |(antes, _)| antes);
    if sin_cola.trim_start().starts_with('#') {
        return "";
    }
    sin_cola.trim_end()
}

/// Entradas del bloque `permissions:` declarado **a nivel de flujo** (columna cero), ya
/// recortadas; o `None` si el flujo no lo declara.
///
/// Admite la forma de bloque (`permissions:` y debajo `contents: read`, una por línea) y la forma
/// en línea (`permissions: read-all`), que devuelve su único valor. Las claves sangradas no
/// cuentan: un `permissions:` dentro de un trabajo no sustituye al del flujo.
fn permisos_de_nivel_de_flujo(contenido: &str) -> Option<Vec<String>> {
    let mut lineas = contenido.lines().map(linea_yaml_sin_comentario);
    let valor_en_linea = lineas.find_map(|linea| linea.strip_prefix("permissions:"))?;

    if !valor_en_linea.trim().is_empty() {
        return Some(vec![valor_en_linea.trim().to_owned()]);
    }

    let entradas = lineas
        .filter(|linea| !linea.is_empty())
        .take_while(|linea| linea.starts_with(char::is_whitespace))
        .map(|linea| linea.trim().to_owned())
        .collect();
    Some(entradas)
}

/// Calibra la lectura de `permisos_de_nivel_de_flujo` contra casos de resultado conocido antes de
/// creerla sobre los flujos reales: si esta lectura fallara, la barrera de abajo podría
/// pasar en verde mirando otra cosa.
#[test]
fn la_lectura_de_permisos_de_flujo_reconoce_los_casos_conocidos() {
    let bloque = "on:\r\n  push:\r\n\r\n# comentario\r\npermissions:\r\n  # dentro\r\n  contents: read\r\n\r\nenv:\r\n  A: b\r\n";
    assert_eq!(
        permisos_de_nivel_de_flujo(bloque),
        Some(vec!["contents: read".to_owned()])
    );

    let en_linea = "permissions: read-all  # todo\njobs:\n";
    assert_eq!(
        permisos_de_nivel_de_flujo(en_linea),
        Some(vec!["read-all".to_owned()])
    );

    let solo_en_trabajo = "jobs:\n  a:\n    permissions:\n      contents: write\n";
    assert_eq!(permisos_de_nivel_de_flujo(solo_en_trabajo), None);

    let solo_comentado = "# permissions:\n#   contents: read\njobs:\n";
    assert_eq!(permisos_de_nivel_de_flujo(solo_comentado), None);
}

/// Los flujos de CI no dejan el `GITHUB_TOKEN` con los permisos por defecto del repositorio.
///
/// Sin un bloque `permissions:`, el token de cada trabajo hereda lo que diga la configuración del
/// repositorio, que puede incluir escritura: una acción de terceros comprometida podría entonces
/// empujar código o tocar las Releases. CodeQL lo marcó (`actions/missing-workflow-permissions`)
/// en los cuatro trabajos de `ci.yml`.
///
/// - Todo flujo declara `permissions:` a nivel de flujo.
/// - `ci.yml` no escribe en ningún sitio, así que su único permiso es `contents: read` y ningún
///   trabajo declara otros propios. `publicacion.yml` sí necesita escribir para publicar la
///   Release y no se le exige lo mismo.
#[test]
fn los_flujos_de_ci_declaran_permisos_minimos() {
    let flujos = [
        ".github/workflows/ci.yml",
        ".github/workflows/publicacion.yml",
    ];

    for flujo in flujos {
        let contenido = std::fs::read_to_string(flujo)
            .unwrap_or_else(|fallo| panic!("el flujo «{flujo}» debe existir y leerse: {fallo}"));
        assert!(
            permisos_de_nivel_de_flujo(&contenido).is_some(),
            "{flujo} no declara `permissions:` a nivel de flujo, así que el `GITHUB_TOKEN` hereda \
             los permisos por defecto del repositorio, que pueden incluir escritura"
        );
    }

    let ci = std::fs::read_to_string(".github/workflows/ci.yml")
        .unwrap_or_else(|fallo| panic!("ci.yml debe existir y leerse: {fallo}"));

    assert_eq!(
        permisos_de_nivel_de_flujo(&ci),
        Some(vec!["contents: read".to_owned()]),
        "ci.yml solo descarga, compila y prueba: su único permiso debe ser `contents: read`"
    );

    let declaraciones_de_permisos = ci
        .lines()
        .map(linea_yaml_sin_comentario)
        .filter(|linea| linea.trim_start().starts_with("permissions:"))
        .count();
    assert_eq!(
        declaraciones_de_permisos, 1,
        "ci.yml declara `permissions:` {declaraciones_de_permisos} veces. Solo debe hacerlo una, a \
         nivel de flujo: un trabajo que declara los suyos puede ampliar lo que el flujo limita"
    );

    for (numero, linea) in ci.lines().enumerate() {
        let util = linea_yaml_sin_comentario(linea);
        assert!(
            !util.ends_with(": write") && !util.contains("write-all"),
            "ci.yml:{} concede escritura («{}»), y ningún trabajo de la CI la necesita",
            numero + 1,
            util.trim()
        );
    }
}

#[test]
fn ningun_texto_se_recorta_en_el_inspector_en_diferentes_resoluciones() {
    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    app.mapa.proyecto = crate::model::Proyecto::nuevo_ejemplo_juego_ahorcado(Idioma::Espanol);
    let id_nodo = app
        .mapa
        .proyecto
        .nodes
        .iter()
        .find(|(_, n)| n.title.contains("Procesar un intento"))
        .map(|(id, _)| *id)
        .unwrap_or(app.mapa.proyecto.root_id);

    app.mapa.nodo_seleccionado = Some(id_nodo);

    // Probamos diferentes resoluciones de pantalla comunes (720p, 1080p, 2K, 4K)
    let resoluciones = [
        (1024.0, 768.0),
        (1280.0, 720.0),
        (1920.0, 1080.0),
        (2560.0, 1440.0),
        (3840.0, 2160.0),
    ];

    for (w, h) in resoluciones {
        let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(w, h));

        // 1. Con panel de ayuda abierto
        app.presentacion.ventanas.panel_de_ayuda = true;
        app.presentacion.guia_de_ayuda_activa =
            Some(crate::ui::help_system::TemaDeAyuda::ControlHumanoCorrecciones);
        let salida1 = crate::arnes_interfaz::ejecutar_fotograma_completo(&mut app, &ctx, rect);
        crate::arnes_interfaz::comprobar_que_ningun_texto_de_paneles_se_recorta(&salida1);

        // 2. Con panel de ayuda cerrado
        app.presentacion.ventanas.panel_de_ayuda = false;
        let salida2 = crate::arnes_interfaz::ejecutar_fotograma_completo(&mut app, &ctx, rect);
        crate::arnes_interfaz::comprobar_que_ningun_texto_de_paneles_se_recorta(&salida2);
    }
}

