#[test]
fn ningun_tema_de_ayuda_desborda_el_ancho_del_panel_en_ningun_idioma() {
    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1920.0, 1080.0));

    let mut desbordamientos = Vec::new();

    for idioma in crate::textos::Idioma::TODOS {
        app.presentacion.preferencias.idioma = idioma;
        for topic in crate::ui::help_system::TemaDeAyuda::TODOS {
            app.presentacion.ventanas.panel_de_ayuda = true;
            app.presentacion.guia_de_ayuda_activa = Some(topic);

            let entrada = egui::RawInput {
                screen_rect: Some(rect),
                ..Default::default()
            };

            let mut ancho_asignado = 0.0;
            let mut ancho_ocupado = 0.0;

            let mut salida = ctx.run_ui(entrada, |ui| {
                egui::Panel::right("detailed_help_side_panel")
                    .min_size(360.0)
                    .default_size(420.0)
                    .max_size(550.0)
                    .show(ui, |ui| {
                        ancho_asignado = ui.available_width();
                        let min_x_panel = ui.min_rect().min.x;
                        crate::ui::sidebar::dibujar_guia_detallada(&mut app, ui);
                        let max_x_panel = ui.min_rect().max.x;
                        ancho_ocupado = max_x_panel - min_x_panel;
                    });
            });
            // Fotograma fuera del arnés: suelta sus texturas aquí, o una salida sin
            // consumir hace abortar el proceso al destruirse, y sin mensaje.
            salida.textures_delta.clear();

            if ancho_ocupado > ancho_asignado + 0.5 {
                desbordamientos.push((
                    idioma,
                    topic,
                    ancho_asignado,
                    ancho_ocupado,
                    ancho_ocupado - ancho_asignado,
                ));
            }
        }
    }

    for (idioma, topic, entrar, salir, exceso) in &desbordamientos {
        println!(
            "DESBORDAMIENTO: {:?} - {:?} | disponible: {:.1}px, ocupado: {:.1}px | exceso: +{:.1}px",
            idioma, topic, entrar, salir, exceso
        );
    }

    assert!(
        desbordamientos.is_empty(),
        "Se encontraron {} temas de ayuda que desbordan el ancho del panel",
        desbordamientos.len()
    );
}

/// Defecto COD-009: `aplicacion_de_prueba()` invocaba el constructor con acceso a disco
/// (`nueva_con_contexto`), por lo que si el usuario tenía una copia de autoguardado en su
/// perfil (`%APPDATA%\MMCelt\recuperacion\sesion.autoguardado.json`), la aplicación de prueba
/// arrancaba con el modal de recuperación abierto (`recuperacion_pendiente: Some(...)`).
/// Esto rompía `con_una_ventana_abierta_supr_no_borra_el_nodo_de_detras` y acoplaba la
/// suite de pruebas al estado del disco del host.
///
/// Esta prueba comprueba que `aplicacion_de_prueba()` nace con estado limpio y sin ventanas
/// abiertas incluso cuando existe una sesión de autoguardado válida en el directorio de datos.
#[test]
fn la_aplicacion_de_prueba_esta_aislada_del_perfil_en_disco() {
    let datos = aislar_datos("aislamiento_arnes");

    // Escribimos una sesión de autoguardado válida en el directorio de datos aislado.
    let mut proyecto = Proyecto::nuevo_vacio("Sesión previa");
    proyecto.title = "Trabajo anterior sin guardar".to_string();
    let copia_escrita =
        crate::autoguardado::escribir_recuperacion_en(datos.carpeta(), &proyecto, None);
    assert!(
        copia_escrita.is_ok(),
        "debería poder escribirse la copia de autoguardado para la prueba"
    );
    assert!(
        crate::autoguardado::buscar_recuperacion_en(datos.carpeta())
            .expect("evaluar copia")
            .is_some(),
        "debería existir una recuperación activa en disco"
    );

    // La aplicación de prueba debe nacer limpia y sin modal de recuperación abierto.
    let (app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    assert!(
        app.persistencia.recuperacion.is_none(),
        "la aplicación de prueba no debe cargar copias de recuperación de disco"
    );
    assert!(
        !app.hay_alguna_ventana_abierta(),
        "la aplicación de prueba debe arrancar sin ninguna ventana ni modal abierto"
    );
    assert_eq!(
        app.presentacion.preferencias.escala_interfaz,
        crate::preferencias::ESCALA_POR_DEFECTO,
        "la aplicación de prueba debe usar las preferencias por defecto"
    );
}

/// Extrae todos los caracteres Unicode cubiertos por las subtables `cmap` (formatos 4 y 12)
/// de una fuente OpenType/TrueType sin dependencias externas.
fn extraer_glifos_cmap_ttf(bytes: &[u8]) -> std::collections::HashSet<char> {
    use std::collections::HashSet;
    let mut caracteres = HashSet::new();
    if bytes.len() < 12 {
        return caracteres;
    }

    let num_tables = u16::from_be_bytes([bytes[4], bytes[5]]) as usize;
    let mut cmap_offset = None;

    for i in 0..num_tables {
        let offset = 12 + i * 16;
        if offset + 16 > bytes.len() {
            break;
        }
        let tag = &bytes[offset..offset + 4];
        if tag == b"cmap" {
            let tabla_offset = u32::from_be_bytes([
                bytes[offset + 8],
                bytes[offset + 9],
                bytes[offset + 10],
                bytes[offset + 11],
            ]) as usize;
            cmap_offset = Some(tabla_offset);
            break;
        }
    }

    let Some(cmap_base) = cmap_offset else {
        return caracteres;
    };

    if cmap_base + 4 > bytes.len() {
        return caracteres;
    }

    let num_subtables = u16::from_be_bytes([bytes[cmap_base + 2], bytes[cmap_base + 3]]) as usize;

    for s in 0..num_subtables {
        let sub_rec = cmap_base + 4 + s * 8;
        if sub_rec + 8 > bytes.len() {
            break;
        }
        let sub_offset = cmap_base
            + u32::from_be_bytes([
                bytes[sub_rec + 4],
                bytes[sub_rec + 5],
                bytes[sub_rec + 6],
                bytes[sub_rec + 7],
            ]) as usize;

        if sub_offset + 2 > bytes.len() {
            continue;
        }

        let format = u16::from_be_bytes([bytes[sub_offset], bytes[sub_offset + 1]]);
        if format == 4 {
            if sub_offset + 14 > bytes.len() {
                continue;
            }
            let seg_count =
                (u16::from_be_bytes([bytes[sub_offset + 6], bytes[sub_offset + 7]]) / 2) as usize;
            let end_code_offset = sub_offset + 14;
            let start_code_offset = end_code_offset + seg_count * 2 + 2;
            let id_delta_offset = start_code_offset + seg_count * 2;
            let id_range_offset = id_delta_offset + seg_count * 2;

            if id_range_offset + seg_count * 2 > bytes.len() {
                continue;
            }

            for i in 0..seg_count {
                let start = u16::from_be_bytes([
                    bytes[start_code_offset + i * 2],
                    bytes[start_code_offset + i * 2 + 1],
                ]);
                let end = u16::from_be_bytes([
                    bytes[end_code_offset + i * 2],
                    bytes[end_code_offset + i * 2 + 1],
                ]);
                let id_delta = i16::from_be_bytes([
                    bytes[id_delta_offset + i * 2],
                    bytes[id_delta_offset + i * 2 + 1],
                ]);
                let range_offset_loc = id_range_offset + i * 2;
                let range_offset =
                    u16::from_be_bytes([bytes[range_offset_loc], bytes[range_offset_loc + 1]]);

                if start == 0xFFFF || end == 0xFFFF {
                    continue;
                }

                for code in start..=end {
                    let glyph_id = if range_offset == 0 {
                        (code as i32 + id_delta as i32) as u16
                    } else {
                        let glyph_addr = range_offset_loc
                            + range_offset as usize
                            + ((code - start) * 2) as usize;
                        if glyph_addr + 2 <= bytes.len() {
                            let gid =
                                u16::from_be_bytes([bytes[glyph_addr], bytes[glyph_addr + 1]]);
                            if gid != 0 {
                                (gid as i32 + id_delta as i32) as u16
                            } else {
                                0
                            }
                        } else {
                            0
                        }
                    };
                    if glyph_id != 0 {
                        if let Some(ch) = char::from_u32(code as u32) {
                            caracteres.insert(ch);
                        }
                    }
                }
            }
        } else if format == 12 {
            if sub_offset + 16 > bytes.len() {
                continue;
            }
            let num_groups = u32::from_be_bytes([
                bytes[sub_offset + 12],
                bytes[sub_offset + 13],
                bytes[sub_offset + 14],
                bytes[sub_offset + 15],
            ]) as usize;

            let groups_base = sub_offset + 16;
            for g in 0..num_groups {
                let g_offset = groups_base + g * 12;
                if g_offset + 12 > bytes.len() {
                    break;
                }
                let start_char = u32::from_be_bytes([
                    bytes[g_offset],
                    bytes[g_offset + 1],
                    bytes[g_offset + 2],
                    bytes[g_offset + 3],
                ]);
                let end_char = u32::from_be_bytes([
                    bytes[g_offset + 4],
                    bytes[g_offset + 5],
                    bytes[g_offset + 6],
                    bytes[g_offset + 7],
                ]);
                for c in start_char..=end_char {
                    if let Some(ch) = char::from_u32(c) {
                        caracteres.insert(ch);
                    }
                }
            }
        }
    }

    caracteres
}

/// COD-010: Comprueba que la fuente china embebida en el ejecutable cubre todos los caracteres CJK
/// utilizados en el código, los menús, el inspector y las 24 guías de ayuda en chino,
/// además del estándar GB2312 nivel 1 para el texto que introduzca el usuario.
#[test]
fn todos_los_caracteres_cjk_del_programa_tienen_glifo_en_la_fuente_embebida() {
    let font_bytes = crate::aplicacion::FUENTE_CJK_BYTES;
    assert!(
        !font_bytes.is_empty(),
        "el archivo de la fuente CJK no debe estar vacío"
    );

    let glifos = extraer_glifos_cmap_ttf(font_bytes);
    assert!(
        glifos.len() >= 3500,
        "la fuente debe contener al menos 3.500 glifos (GB2312 nivel 1 + interfaz), tiene {}",
        glifos.len()
    );

    // Función auxiliar para detectar rangos CJK que la fuente por defecto de egui no cubre
    let es_cjk = |c: char| -> bool {
        let p = c as u32;
        (0x3000..=0x303F).contains(&p)
            || (0x3400..=0x4DBF).contains(&p)
            || (0x4E00..=0x9FFF).contains(&p)
            || (0xFF00..=0xFFEF).contains(&p)
    };

    // 1. Recoger todos los caracteres de textos.rs y ayuda_textos.rs
    let mut textos_fuente = String::new();
    textos_fuente.push_str(include_str!("textos.rs"));
    textos_fuente.push_str(include_str!("ui/ayuda_textos.rs"));

    // 2. Recoger los 24 archivos de ayuda en chino
    let carpeta_ayuda_zh = std::path::Path::new("assets/ayuda/zh");
    if let Ok(entradas) = std::fs::read_dir(carpeta_ayuda_zh) {
        for entrada in entradas.flatten() {
            if let Ok(contenido) = std::fs::read_to_string(entrada.path()) {
                textos_fuente.push_str(&contenido);
            }
        }
    }

    let mut caracteres_cjk_del_programa = std::collections::BTreeSet::new();
    for ch in textos_fuente.chars() {
        if es_cjk(ch) {
            caracteres_cjk_del_programa.insert(ch);
        }
    }

    assert!(
        caracteres_cjk_del_programa.len() >= 800,
        "el programa debería contener al menos 800 caracteres CJK únicos, se encontraron {}",
        caracteres_cjk_del_programa.len()
    );

    // 3. Comprobar que CADA carácter CJK utilizado en el programa está presente en el cmap de la fuente
    let mut faltantes = Vec::new();
    for &ch in &caracteres_cjk_del_programa {
        if !glifos.contains(&ch) {
            faltantes.push(format!("'{}' (U+{:04X})", ch, ch as u32));
        }
    }

    assert!(
        faltantes.is_empty(),
        "Hay caracteres CJK utilizados en el programa que faltan en la fuente embebida:\n{}",
        faltantes.join(", ")
    );

    // 4. Comprobación interactiva en egui: el texto en chino se compone y tiene dimensiones positivas
    let ctx = egui::Context::default();
    crate::aplicacion::configurar_fuentes(&ctx);
    let mut salida = ctx.run_ui(egui::RawInput::default(), |ui| {
        let respuesta = ui.label("🎯 简体中文 - 战略支柱与架构设计");
        assert!(
            respuesta.rect.width() > 0.0,
            "el texto en chino debe tener ancho positivo al dibujarse en la interfaz"
        );
        assert!(
            respuesta.rect.height() > 0.0,
            "el texto en chino debe tener altura positiva al dibujarse en la interfaz"
        );
    });
    // Fotograma fuera del arnés: mismas razones que arriba.
    salida.textures_delta.clear();
}

/// COD-011: Comprueba que el mapa inicial, las plantillas y los ejemplos se crean localizados
/// en cada uno de los seis idiomas soportados, sin literales en español hardcodeados cuando
/// el usuario está usando inglés, francés, alemán, ruso o chino.
#[test]
fn las_plantillas_ejemplos_y_mapa_inicial_estan_localizados_en_los_seis_idiomas() {
    for idioma in Idioma::TODOS {
        // 1. Mapa inicial de bienvenida
        let inicial = Proyecto::nuevo_ejemplo_inicial(idioma);
        let root_title = &inicial.nodes[&inicial.root_id].title;
        assert_eq!(
            root_title,
            Texto::MapaInicialIdeaCentral.en(idioma),
            "el título raíz inicial debe coincidir con la traducción de {idioma:?}"
        );
        assert_eq!(
            inicial.title,
            Texto::MapaInicialTitulo.en(idioma),
            "el título del proyecto inicial debe coincidir con la traducción de {idioma:?}"
        );
        let todas_las_etiquetas: Vec<_> = inicial
            .nodes
            .values()
            .flat_map(|n| n.tags.iter().map(String::as_str))
            .collect();
        assert!(
            todas_las_etiquetas.contains(&Texto::MapaInicialTagTech.en(idioma)),
            "el mapa inicial en {idioma:?} debe contener la etiqueta tech traducida"
        );
        assert!(
            todas_las_etiquetas.contains(&Texto::MapaInicialTagObjetivo.en(idioma)),
            "el mapa inicial en {idioma:?} debe contener la etiqueta objetivo traducida"
        );
        if idioma != Idioma::Espanol {
            assert!(
                !todas_las_etiquetas.contains(&"objetivo"),
                "el mapa inicial en {idioma:?} no debe conservar la etiqueta española «objetivo»"
            );
        }

        // 2. Plantilla Arquitectura Limpia
        let limpia = Proyecto::nueva_plantilla_arquitectura_limpia(idioma);
        let hijos_limpia: Vec<_> = limpia.nodes[&limpia.root_id]
            .children
            .iter()
            .map(|id| limpia.nodes[id].title.as_str())
            .collect();
        assert!(
            hijos_limpia.contains(&Texto::PlantillaLimpiaCapaDominio.en(idioma)),
            "la plantilla limpia debe contener la capa de dominio en {idioma:?}"
        );
        assert!(
            hijos_limpia.contains(&Texto::PlantillaLimpiaCapaAplicacion.en(idioma)),
            "la plantilla limpia debe contener la capa de aplicación en {idioma:?}"
        );
        assert!(
            hijos_limpia.contains(&Texto::PlantillaLimpiaCapaInfraestructura.en(idioma)),
            "la plantilla limpia debe contener la capa de infraestructura en {idioma:?}"
        );
        assert!(
            hijos_limpia.contains(&Texto::PlantillaLimpiaCapaPresentacion.en(idioma)),
            "la plantilla limpia debe contener la capa de presentación en {idioma:?}"
        );

        // 3. Plantilla Fullstack
        let fullstack = Proyecto::nueva_plantilla_fullstack(idioma);
        let hijos_fullstack: Vec<_> = fullstack.nodes[&fullstack.root_id]
            .children
            .iter()
            .map(|id| fullstack.nodes[id].title.as_str())
            .collect();
        assert!(
            hijos_fullstack.contains(&Texto::PlantillaFullstackFrontend.en(idioma)),
            "la plantilla fullstack debe contener frontend en {idioma:?}"
        );
        assert!(
            hijos_fullstack.contains(&Texto::PlantillaFullstackBackend.en(idioma)),
            "la plantilla fullstack debe contener backend en {idioma:?}"
        );

        // 4. Ejemplo Ahorcado
        let ahorcado = Proyecto::nuevo_ejemplo_juego_ahorcado(idioma);
        assert_eq!(
            ahorcado.nodes[&ahorcado.root_id].title,
            Texto::EjemploAhorcadoRaizTitulo.en(idioma),
            "el título de ahorcado debe estar traducido en {idioma:?}"
        );
        assert_eq!(
            ahorcado.creator_vision,
            Texto::EjemploAhorcadoVision.en(idioma),
            "la visión de ahorcado debe estar traducida en {idioma:?}"
        );

        // 5. Ejemplo Negocio de Comida
        let comida = Proyecto::nuevo_ejemplo_negocio_comida(idioma);
        assert_eq!(
            comida.nodes[&comida.root_id].title,
            Texto::EjemploNegocioRaizTitulo.en(idioma),
            "el título de comida debe estar traducido en {idioma:?}"
        );
        assert_eq!(
            comida.creator_vision,
            Texto::EjemploNegocioVision.en(idioma),
            "la visión de comida debe estar traducida en {idioma:?}"
        );

        // En idiomas no hispanos, verificar que los textos clave no se quedaron en español
        if idioma != Idioma::Espanol {
            assert_ne!(
                Texto::MapaInicialIdeaCentral.en(idioma),
                "🎯 Idea Central",
                "el mapa inicial en {idioma:?} no debe tener el texto en español"
            );
            assert_ne!(
                Texto::PlantillaLimpiaCapaDominio.en(idioma),
                "1. Dominio (Core)",
                "la capa de dominio en {idioma:?} no debe tener el texto en español"
            );
            assert_ne!(
                Texto::EjemploAhorcadoRaizTitulo.en(idioma),
                "🎮 Juego del Ahorcado",
                "el ejemplo del ahorcado en {idioma:?} no debe tener el título en español"
            );
            assert_ne!(
                Texto::EjemploNegocioRaizTitulo.en(idioma),
                "🍲 Comida casera a domicilio",
                "el ejemplo de comida en {idioma:?} no debe tener el título en español"
            );
        }
    }
}

/// COD-011 / COD-012: Comprueba que el cambio de idioma a través del menú real de la interfaz
/// actualiza los controles, menús y barras, pero NUNCA altera retroactivamente el mapa existente
/// ni los nodos que el usuario ya ha creado o modificado en el lienzo (soberanía de datos).
#[test]
fn el_cambio_de_idioma_en_la_interfaz_no_muta_el_mapa_existente_del_usuario() {
    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    assert_eq!(app.idioma(), Idioma::Espanol);

    // El usuario edita el nodo raíz con su propio contenido
    let root_id = app.mapa.proyecto.root_id;
    let nodo = app.mapa.proyecto.nodes.get_mut(&root_id).unwrap();
    nodo.title = "Mi Idea Revolucionaria".to_string();
    nodo.notes = "Notas exclusivas escritas por el creador".to_string();

    // El usuario abre el menú «Ver y Diseño» y pulsa en "🇨🇳 简体中文" a través del arnés real
    let pulsado = crate::arnes_interfaz::hacer_clic_en_texto(
        &mut app,
        crate::ui::toolbar::menu_ver_y_diseno,
        "简体中文",
    );
    assert!(
        pulsado,
        "debe encontrarse y pulsarse la opción de Chino Simplificado en el menú"
    );

    // El idioma de la aplicación ahora es Chino Simplificado
    assert_eq!(app.idioma(), Idioma::ChinoSimplificado);

    // Los controles de la barra de herramientas se dibujan en chino
    let pintados = crate::arnes_interfaz::textos_de_la_barra(&mut app);
    let menu_archivo_zh = Texto::MenuArchivo.en(Idioma::ChinoSimplificado);
    assert!(
        pintados.iter().any(|t| t == menu_archivo_zh),
        "la barra debe pintar el menú Archivo en chino («{menu_archivo_zh}»). Pintó: {pintados:?}"
    );

    // Pero el mapa del usuario se preserva intacto sin mutación retroactiva
    let nodo_despues = app.mapa.proyecto.nodes.get(&root_id).unwrap();
    assert_eq!(nodo_despues.title, "Mi Idea Revolucionaria");
    assert_eq!(
        nodo_despues.notes,
        "Notas exclusivas escritas por el creador"
    );
}

/// Atiende fotogramas hasta que el efecto observable de una carga asíncrona se cumple.
fn atender_vigilancia_hasta(
    app: &mut crate::aplicacion::AplicacionMapaMental,
    condicion: impl Fn(&crate::aplicacion::AplicacionMapaMental) -> bool,
) {
    let limite = std::time::Instant::now() + std::time::Duration::from_secs(2);
    while !condicion(app) {
        app.procesar_eventos_de_vigilancia();
        assert!(
            std::time::Instant::now() < limite,
            "la carga externa no termino dentro del plazo de la prueba"
        );
        std::thread::sleep(std::time::Duration::from_millis(2));
    }
}

/// Da varios fotogramas al vigilante y al trabajador aunque el resultado correcto sea
/// precisamente que el mapa no cambie.
fn atender_vigilancia_durante(
    app: &mut crate::aplicacion::AplicacionMapaMental,
    duracion: std::time::Duration,
) {
    let limite = std::time::Instant::now() + duracion;
    while std::time::Instant::now() < limite {
        app.procesar_eventos_de_vigilancia();
        std::thread::sleep(std::time::Duration::from_millis(2));
    }
}

/// AUTO-001: Cuando el mapa está vigilado y el usuario no tiene cambios locales sin guardar,
/// cualquier modificación externa realizada por una IA (por ejemplo a través del servidor MCP)
/// recarga automáticamente el mapa en pantalla sin intervención manual.
#[test]
fn el_mapa_se_recarga_solo_cuando_no_hay_cambios_locales_pendientes() {
    let datos = aislar_datos("vigilancia_recarga_automatica");
    let ruta_mapa = datos.carpeta.join("proyecto.mmcelt");

    // 1. Crear proyecto inicial y guardarlo en disco
    let p1 = Proyecto::nuevo_vacio("Mapa Inicial");
    crate::storage::guardar_proyecto_en_archivo(&p1, &ruta_mapa)
        .expect("debe guardarse el proyecto inicial");

    // 2. Instanciar aplicación y abrir el mapa con vigilancia
    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    app.sustituir_el_mapa_abierto(p1, Some(ruta_mapa.clone()), "Abierto");
    crate::vigilancia_mapa::iniciar_vigilancia(app.persistencia_mut(), &ctx)
        .expect("iniciar vigilancia del mapa");

    assert!(
        !app.hay_cambios_locales_sin_guardar(),
        "la aplicación recién abierta no debe tener cambios locales pendientes"
    );
    assert!(
        app.persistencia.vigilante.is_some(),
        "el vigilante de archivos debe estar activo"
    );

    // 3. Simular que un agente de IA escribe un nuevo mapa en el archivo
    let mut p2 = Proyecto::nuevo_vacio("Actualizado por Agente IA");
    p2.creator_vision = "Nueva visión generada automáticamente".to_string();
    crate::storage::guardar_proyecto_en_archivo(&p2, &ruta_mapa)
        .expect("la IA debe poder sobrescribir el archivo");

    // Damos un breve instante para que el hilo del sistema operativo entregue la notificación
    std::thread::sleep(std::time::Duration::from_millis(80));

    // 4. Procesar el ciclo de interfaz y verificar recarga
    atender_vigilancia_hasta(&mut app, |app| {
        app.mapa.proyecto.title == "Actualizado por Agente IA"
    });

    assert_eq!(
        app.mapa.proyecto.title, "Actualizado por Agente IA",
        "el mapa en pantalla debe haberse actualizado solo con los datos de la IA"
    );
    assert_eq!(
        app.mapa.proyecto.creator_vision, "Nueva visión generada automáticamente",
        "los campos del mapa deben coincidir con la versión escrita por la IA"
    );
    assert!(
        !app.persistencia.cambio_externo_pendiente,
        "no debe haber aviso de conflicto cuando no había cambios locales pendientes"
    );
}

/// Un fallo del backend de vigilancia conserva su tipo y su causa; no se aplana a texto.
#[test]
fn el_vigilante_propaga_un_error_tipado() {
    use std::error::Error;

    let raiz = carpeta_temporal_contexto("vigilante-error-tipado");
    let ruta = raiz.join("carpeta-que-no-existe").join("mapa.mmcelt");
    let error: crate::error::AppError =
        match crate::vigilante::VigilanteArchivo::iniciar(&ruta, egui::Context::default()) {
            Ok(_) => panic!("no debe vigilar una carpeta inexistente"),
            Err(error) => error,
        };

    assert!(matches!(error, crate::error::AppError::Vigilancia { .. }));
    assert!(error.source().is_some(), "debe conservar notify::Error");
    std::fs::remove_dir_all(raiz).expect("limpiar prueba del vigilante");
}

/// AUTO-001: Si el usuario tiene modificaciones locales sin guardar cuando el agente de IA
/// escribe en disco, el trabajo del usuario NO se sobrescribe bajo ningún concepto y se
/// activa la advertencia de cambios locales retenidos.
#[test]
fn el_mapa_no_se_sobrescribe_si_el_usuario_tiene_cambios_sin_guardar() {
    let datos = aislar_datos("vigilancia_preservar_usuario");
    let ruta_mapa = datos.carpeta.join("proyecto.mmcelt");

    // 1. Crear proyecto inicial y guardarlo en disco
    let p1 = Proyecto::nuevo_vacio("Mapa Base");
    crate::storage::guardar_proyecto_en_archivo(&p1, &ruta_mapa)
        .expect("debe guardarse el proyecto inicial");

    // 2. Instanciar aplicación y abrir el mapa con vigilancia
    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    app.sustituir_el_mapa_abierto(p1, Some(ruta_mapa.clone()), "Abierto");
    crate::vigilancia_mapa::iniciar_vigilancia(app.persistencia_mut(), &ctx)
        .expect("iniciar vigilancia del mapa");

    // 3. El usuario realiza una modificación local en la UI (cambia título / notas)
    app.mapa.proyecto.title = "Trabajo Crítico del Usuario en Curso".to_string();
    app.mapa.proyecto.marcar_modificado();
    assert!(
        app.hay_cambios_locales_sin_guardar(),
        "el mapa modificado localmente debe marcarse como pendiente de guardado"
    );

    // 4. El agente de IA escribe un nuevo mapa en el archivo en disco
    let mut p2 = Proyecto::nuevo_vacio("Sobrescritura por IA");
    p2.creator_vision = "Visión de la IA que no debe pisar al usuario".to_string();
    crate::storage::guardar_proyecto_en_archivo(&p2, &ruta_mapa).expect("la IA escribe en disco");

    std::thread::sleep(std::time::Duration::from_millis(80));

    // 5. Procesar vigilancia
    atender_vigilancia_hasta(&mut app, |app| app.persistencia.cambio_externo_pendiente);

    // 6. Demostrar que el cambio del usuario sigue intacto y se emitió el aviso
    assert_eq!(
        app.mapa.proyecto.title, "Trabajo Crítico del Usuario en Curso",
        "el trabajo local del usuario NO debe ser destruido por la IA"
    );
    assert_ne!(
        app.mapa.proyecto.title, "Sobrescritura por IA",
        "el título no debe haberse sustituido por el de la IA"
    );
    assert!(
        app.persistencia.cambio_externo_pendiente,
        "debe avisarse al usuario de que la IA modificó el archivo pero sus cambios se retuvieron"
    );
}

/// AUTO-001: El autoguardado propio y los guardados de MMCelt no disparan bucles de retroalimentación
/// (auto-disparos) al ser ignorados mediante comparación de huella de contenido.
#[test]
fn el_guardado_propio_no_dispara_recarga_por_vigilancia() {
    let datos = aislar_datos("vigilancia_inmunidad_autodisparo");
    let ruta_mapa = datos.carpeta.join("proyecto.mmcelt");

    let p1 = Proyecto::nuevo_vacio("Mapa Propio");
    crate::storage::guardar_proyecto_en_archivo(&p1, &ruta_mapa)
        .expect("debe guardarse el archivo");

    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    app.sustituir_el_mapa_abierto(p1, Some(ruta_mapa.clone()), "Abierto");
    crate::vigilancia_mapa::iniciar_vigilancia(app.persistencia_mut(), &ctx)
        .expect("iniciar vigilancia del mapa");

    // Guardado realizado por MMCelt
    app.solicitar_guardado(false);

    std::thread::sleep(std::time::Duration::from_millis(80));

    let mensaje_previo = app.presentacion.mensaje_de_estado.clone();
    atender_vigilancia_durante(&mut app, std::time::Duration::from_millis(100));

    assert_eq!(
        app.presentacion.mensaje_de_estado, mensaje_previo,
        "un guardado propio no debe alterar el estado ni disparar recargas innecesarias"
    );
    assert!(
        !app.persistencia.cambio_externo_pendiente,
        "no debe generarse aviso de conflicto ante escrituras propias"
    );
}

