/// **Hallazgo H2** — la ventana avisa de que el agente apunta a otra carpeta.
///
/// Y ofrece la reparación **explícita**: un botón que vuelve a registrar el agente con la
/// carpeta que se está mostrando. No se reescribe sola la configuración de otro programa.
#[test]
fn la_ventana_de_conexiones_avisa_del_agente_descolocado() {
    use crate::conectores::FormatoConfiguracion;
    use crate::textos::{Idioma, Texto};

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    let anterior = std::env::temp_dir().join("mmcelt_ventana_anterior");
    let actual = std::env::temp_dir().join("mmcelt_ventana_actual");

    let agente = agente_registrado_en("ventana_vieja.json", FormatoConfiguracion::Json, &anterior);
    let configuracion = agente.ruta_configuracion.clone();

    app.presentacion.preferencias.espacio_trabajo_ia = actual.display().to_string();
    app.agentes.espacio_de_trabajo = actual.clone();
    let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
        crate::ui::conexiones_modal::dibujar_agente_para_prueba(app, &agente, ui);
    });

    let _ = std::fs::remove_file(&configuracion);

    let aviso = Texto::ModalConectadoAOtraCarpeta.en(Idioma::Espanol);
    let boton = Texto::ModalActualizarLaCarpeta.en(Idioma::Espanol);

    assert!(
        textos.iter().any(|texto| texto.contains(aviso)),
        "la ventana debe avisar de que el agente apunta a otra carpeta; se pintó: {textos:?}"
    );
    assert!(
        textos.iter().any(|texto| texto.contains(boton)),
        "la ventana debe ofrecer volver a registrarlo con la carpeta actual; se pintó: {textos:?}"
    );
    assert!(
        !textos
            .iter()
            .any(|texto| texto == Texto::ModalConectado.en(Idioma::Espanol)),
        "no puede lucir «conectado» a secas mientras apunte a otra carpeta; se pintó: {textos:?}"
    );
}

/// **Decisión de producto del 2026-09-14** — La advertencia de Gemini CLI se dibuja en los 6 idiomas
/// únicamente bajo su ficha, detallando el requisito de cuenta y omitiendo la advertencia caducada
/// de falta de verificación (tras comprobarse con éxito de extremo a extremo), mientras que Claude Code
/// y Codex CLI no la muestran.
#[test]
fn la_ventana_de_conexiones_muestra_advertencia_exclusiva_de_gemini_cli_en_seis_idiomas() {
    use crate::conectores::{FormatoConfiguracion, IdAgente};
    use crate::textos::{Idioma, Texto};

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    // 1. En los seis idiomas, Gemini CLI debe mostrar exactamente su texto de advertencia
    for idioma in Idioma::TODOS {
        app.presentacion.preferencias.idioma = idioma;
        let mut agente_gemini = agente_de_prueba("settings.json", FormatoConfiguracion::Json);
        agente_gemini.id = IdAgente::GeminiCli;
        agente_gemini.nombre = "Gemini CLI";

        let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
            crate::ui::conexiones_modal::dibujar_agente_para_prueba(app, &agente_gemini, ui);
        });

        let advertencia_esperada = Texto::ModalAdvertenciaGeminiCli.en(idioma);
        assert!(
            advertencia_esperada.len() >= 25,
            "la advertencia en {idioma:?} debe tener contenido sustancial (longitud {})",
            advertencia_esperada.len()
        );
        assert!(
            advertencia_esperada.contains("Google"),
            "la advertencia en {idioma:?} debe nombrar a Google"
        );
        assert!(
            !advertencia_esperada.contains("no ha podido verificar"),
            "la advertencia en {idioma:?} no debe contener el aviso caducado de falta de verificación"
        );
        assert!(
            textos.iter().any(|t| t.contains(advertencia_esperada)),
            "Gemini CLI debe mostrar la advertencia en {idioma:?}; se obtuvo: {textos:?}"
        );

        // 2. Claude Code y Codex CLI no deben mostrar esta advertencia
        for (id_otro, nombre_otro) in [
            (IdAgente::ClaudeCode, "Claude Code"),
            (IdAgente::CodexCli, "Codex CLI"),
        ] {
            let mut agente_otro = agente_de_prueba("otro.json", FormatoConfiguracion::Json);
            agente_otro.id = id_otro;
            agente_otro.nombre = nombre_otro;

            let textos_otro = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
                crate::ui::conexiones_modal::dibujar_agente_para_prueba(app, &agente_otro, ui);
            });

            assert!(
                !textos_otro.iter().any(|t| t.contains(advertencia_esperada)),
                "{nombre_otro} no debe mostrar la advertencia de Gemini CLI en {idioma:?}"
            );
        }
    }

    // 3. Verificación de contenido exacto exigido en castellano
    let texto_es = Texto::ModalAdvertenciaGeminiCli.en(Idioma::Espanol);
    assert!(
        texto_es.contains("cuenta autorizada") || texto_es.contains("cuenta personal"),
        "el texto en español debe reflejar el requisito de cuenta de Google"
    );
    assert!(
        !texto_es.contains("no ha podido verificar"),
        "el texto en español ya no debe afirmar que no se ha podido verificar la conexión"
    );
}

// ============================================================================
// Hallazgo H3 — desarrollar por API un mapa hecho por una persona
// ============================================================================
//
// El bloqueo que cerró la prueba real con ChatIA. Las dos herramientas de escritura tenían
// huecos complementarios y entre las dos no cubrían el caso:
//
// - `mmcelt_create_mindmap` sabe expresar jerarquía con `role`, `tags` y `cross_connections`,
//   pero se niega —con razón— a escribir encima de un mapa con trabajo humano.
// - `mmcelt_sync_ai_progress` sí puede escribir sobre ese mapa, pero solo admitía título,
//   padre, estado, prioridad, notas y ruta de código. Ni rol, ni etiquetas, ni conexiones.
//
// El mapa de la prueba real describía un bucle, los bucles se expresan con conexiones
// cruzadas, y la única herramienta autorizada a tocar ese mapa no sabía crearlas. El agente
// acabó entregando un archivo nuevo en vez del mapa del usuario enriquecido.
//
// El diagnóstico de la crónica: **el problema no es la valla, es que no hay puerta**. Una
// protección sin vía legítima empuja al agente fuera de la API, que es justo lo que la valla
// quiere evitar. Estas pruebas abren la puerta y comprueban que la valla sigue en pie.

/// Escribe en el espacio del servidor un mapa como el que hace una persona.
///
/// Todos sus nodos quedan en `PendienteRevision`, que es el estado por omisión y lo que
/// significa «esto lo ha escrito alguien y nadie lo ha revisado todavía». Es la condición
/// que distingue un mapa humano de un borrador de la IA, y de la que dependen tanto la valla
/// de `mmcelt_create_mindmap` como la política de copia de seguridad.
///
/// # Parámetros
/// - `carpeta`: el espacio de trabajo aislado de la prueba.
/// - `nombre`: nombre del archivo `.mmcelt` que se escribe dentro.
///
/// # Devuelve
/// La ruta absoluta del mapa recién escrito.
fn escribir_mapa_humano(carpeta: &std::path::Path, nombre: &str) -> std::path::PathBuf {
    let mut proyecto = Proyecto::nuevo_vacio("Flujo de GhatIA");
    let raiz = proyecto.root_id;
    if let Some(nodo) = proyecto.nodes.get_mut(&raiz) {
        nodo.title = "GhatIA".to_string();
    }

    for titulo in [
        "Entrada del usuario",
        "Respuesta del modelo",
        "Revisión humana",
    ] {
        let id = proyecto.anadir_hijo(raiz, titulo);
        if let Some(nodo) = proyecto.nodes.get_mut(&id) {
            nodo.tags = vec!["humano".to_string()];
        }
    }

    let ruta = carpeta.join(nombre);
    crate::storage::guardar_proyecto_en_archivo(&proyecto, &ruta)
        .expect("el mapa humano de la prueba debería poder escribirse");
    ruta
}

/// Devuelve el nodo con ese título, o falla diciendo cuál falta.
fn nodo_titulado<'p>(proyecto: &'p Proyecto, titulo: &str) -> &'p Nodo {
    proyecto
        .nodes
        .values()
        .find(|n| n.title == titulo)
        .unwrap_or_else(|| panic!("debería existir el nodo «{titulo}»"))
}

/// **Hallazgo H3** — un agente puede desarrollar el mapa de una persona sin sustituirlo.
///
/// Es la reproducción del bloqueo. Un mapa humano que describe un flujo, y un agente que
/// quiere añadirle un paso con su rol y sus etiquetas y cerrar el bucle con dos conexiones
/// cruzadas. Antes de este hallazgo la llamada devolvía `success` y el mapa se quedaba igual:
/// el nodo entraba sin rol y sin etiquetas, y las conexiones no llegaban a existir porque el
/// argumento ni se leía.
///
/// La prueba comprueba a la vez las dos mitades del contrato: que el trabajo del agente entra,
/// y que el del usuario sigue exactamente donde estaba.
#[test]
fn un_agente_puede_desarrollar_un_mapa_humano_sin_sustituirlo() {
    use crate::model::{EstadoRevision, RolNodo};

    let espacio = aislar_espacio_mcp("h3_desarrollar");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "ghatia.mmcelt");

    let antes = cargar_proyecto_de_archivo(&ruta).expect("el mapa humano debería abrirse");
    let humanos: Vec<(uuid::Uuid, String, Option<uuid::Uuid>, EstadoRevision)> = antes
        .nodes
        .values()
        .map(|n| (n.id, n.title.clone(), n.parent_id, n.review_status))
        .collect();

    let resultado = llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "ghatia.mmcelt",
            "node_updates": [
                {
                    "title": "Bucle de refinamiento",
                    "parent_title": "GhatIA",
                    "role": "HipotesisDuda",
                    "tags": ["bucle", "flujo"],
                    "notes": "La revisión vuelve a la entrada mientras haya correcciones"
                }
            ],
            "cross_connections": [
                {
                    "from_title": "Revisión humana",
                    "to_title": "Bucle de refinamiento",
                    "label": "si hay correcciones",
                    "relation_type": "Dependencia"
                },
                {
                    "from_title": "Bucle de refinamiento",
                    "to_title": "Entrada del usuario",
                    "label": "vuelve a empezar",
                    "relation_type": "Sinergia"
                }
            ]
        }),
    );

    assert_eq!(
        resultado["status"], "success",
        "la sincronización debería aceptar el enriquecimiento: {resultado}"
    );

    let despues = cargar_proyecto_de_archivo(&ruta).expect("el mapa enriquecido debería abrirse");

    // Ni un nodo humano borrado, movido de padre ni atribuido al agente.
    for (id, titulo, padre, revision) in humanos {
        let nodo = despues
            .nodes
            .get(&id)
            .unwrap_or_else(|| panic!("el agente ha hecho desaparecer el nodo humano «{titulo}»"));
        assert_eq!(nodo.title, titulo, "el agente ha renombrado un nodo humano");
        assert_eq!(
            nodo.parent_id, padre,
            "el agente ha movido de sitio el nodo humano «{titulo}»"
        );
        assert_eq!(
            nodo.review_status, revision,
            "el nodo humano «{titulo}» ha pasado a figurar como {:?}",
            nodo.review_status
        );
    }

    // Y el trabajo del agente está, entero.
    let nuevo = nodo_titulado(&despues, "Bucle de refinamiento");
    assert_eq!(
        nuevo.role,
        RolNodo::HipotesisDuda,
        "el rol que declaró el agente no llegó al mapa"
    );
    assert!(
        nuevo.tags.iter().any(|t| t == "bucle") && nuevo.tags.iter().any(|t| t == "flujo"),
        "las etiquetas que declaró el agente no llegaron al mapa: {:?}",
        nuevo.tags
    );
    assert_eq!(
        nuevo.review_status,
        EstadoRevision::GeneradoPorIA,
        "todo lo que añade el agente nace marcado como generado por la IA"
    );

    assert_eq!(
        despues.connections.len(),
        2,
        "las conexiones cruzadas que cierran el bucle no llegaron al mapa"
    );
}

/// **Hallazgo H3** — `node_updates` admite el rol, en un nodo nuevo y en uno que ya existe.
///
/// Sin rol, todo lo que añadía un agente por esta puerta caía en el valor por omisión de
/// `anadir_hijo` —pilar o subtema según la profundidad—, así que una duda abierta o una tarea
/// concreta eran indistinguibles de un tema cualquiera.
#[test]
fn la_sincronizacion_admite_el_rol_que_declara_el_agente() {
    use crate::model::RolNodo;

    let espacio = aislar_espacio_mcp("h3_rol");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "rol.mmcelt");

    llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "rol.mmcelt",
            "node_updates": [
                { "title": "Medir la latencia", "parent_title": "GhatIA", "role": "AccionTarea" },
                { "title": "Respuesta del modelo", "role": "RecursoHerramienta" }
            ]
        }),
    );

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");

    assert_eq!(
        nodo_titulado(&proyecto, "Medir la latencia").role,
        RolNodo::AccionTarea,
        "el nodo nuevo no recibió el rol que declaró el agente"
    );
    assert_eq!(
        nodo_titulado(&proyecto, "Respuesta del modelo").role,
        RolNodo::RecursoHerramienta,
        "el nodo existente no recibió el rol que declaró el agente"
    );
}

/// **Hallazgo H3** — las etiquetas del agente se suman a las del usuario, no las sustituyen.
///
/// Es la diferencia entre enriquecer y pisar. Un nodo humano puede llevar etiquetas que el
/// usuario puso a mano y por las que filtra en el programa; que el agente escriba las suyas
/// encima sería borrar trabajo humano sin borrarlo del todo, que es la forma más difícil de
/// detectar. Se aplica el mismo criterio que ya rige para las notas: lo que el agente no
/// nombra, no se toca.
#[test]
fn las_etiquetas_del_agente_se_suman_a_las_del_usuario() {
    let espacio = aislar_espacio_mcp("h3_etiquetas");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "etiquetas.mmcelt");

    llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "etiquetas.mmcelt",
            "node_updates": [
                { "title": "Revisión humana", "tags": ["flujo"] }
            ]
        }),
    );

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");
    let nodo = nodo_titulado(&proyecto, "Revisión humana");

    assert!(
        nodo.tags.iter().any(|t| t == "humano"),
        "el agente ha borrado la etiqueta que puso el usuario: {:?}",
        nodo.tags
    );
    assert!(
        nodo.tags.iter().any(|t| t == "flujo"),
        "la etiqueta del agente no llegó al nodo: {:?}",
        nodo.tags
    );
    assert_eq!(
        nodo.tags.iter().filter(|t| *t == "humano").count(),
        1,
        "una etiqueta que ya estaba no puede acabar repetida: {:?}",
        nodo.tags
    );
}

/// **Hallazgo H3** — añadir una etiqueta también hace caducar la aprobación humana.
///
/// La regla ya existía para las notas, el estado, la prioridad y la ruta: si la IA cambia el
/// contenido de un nodo aprobado, el visto bueno deja de referirse a lo que hay escrito. Los
/// dos campos nuevos entran bajo la misma regla; si no, bastaría con etiquetar un nodo
/// aprobado para modificarlo conservando la firma del usuario.
#[test]
fn una_etiqueta_nueva_caduca_la_aprobacion_humana() {
    use crate::model::EstadoRevision;

    let espacio = aislar_espacio_mcp("h3_caduca");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "caduca.mmcelt");

    let mut proyecto = cargar_proyecto_de_archivo(&ruta).expect("debería abrirse");
    let id = nodo_titulado(&proyecto, "Revisión humana").id;
    if let Some(nodo) = proyecto.nodes.get_mut(&id) {
        nodo.review_status = EstadoRevision::AprobadoPorHumano;
    }
    crate::storage::guardar_proyecto_en_archivo(&proyecto, &ruta).expect("debería guardarse");

    llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "caduca.mmcelt",
            "node_updates": [ { "title": "Revisión humana", "tags": ["revisado_por_ia"] } ]
        }),
    );

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("debería abrirse");
    assert_eq!(
        proyecto.nodes[&id].review_status,
        EstadoRevision::PendienteRevision,
        "el nodo sigue firmado por el usuario después de que la IA lo etiquetara"
    );
}

/// **Hallazgo H3** — las conexiones cruzadas usan el mismo contrato que `create_mindmap`.
///
/// Mismos cuatro campos —`from_title`, `to_title`, `label` y `relation_type`— y mismos
/// valores admitidos. Un contrato distinto para lo mismo obligaría al agente a aprenderse dos
/// formatos según la puerta por la que entra, que es justo el problema que describe H5.
#[test]
fn las_conexiones_cruzadas_de_la_sincronizacion_usan_el_contrato_de_crear_mapa() {
    use crate::model::TipoRelacion;

    let espacio = aislar_espacio_mcp("h3_conexiones");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "conexiones.mmcelt");

    let resultado = llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "conexiones.mmcelt",
            "node_updates": [],
            "cross_connections": [
                {
                    "from_title": "Entrada del usuario",
                    "to_title": "Respuesta del modelo",
                    "label": "alimenta",
                    "relation_type": "Bloquea"
                }
            ]
        }),
    );

    assert_eq!(
        resultado["connections_added"], 1,
        "la respuesta debe decirle al agente cuántas conexiones se crearon: {resultado}"
    );

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");
    assert_eq!(
        proyecto.connections.len(),
        1,
        "la conexión no llegó al mapa"
    );

    let conexion = &proyecto.connections[0];
    assert_eq!(conexion.label, "alimenta", "se perdió la etiqueta");
    assert_eq!(
        conexion.relation_type,
        TipoRelacion::Bloquea,
        "el tipo de relación se degradó al valor por omisión"
    );
    assert_eq!(
        conexion.from,
        nodo_titulado(&proyecto, "Entrada del usuario").id,
        "el origen de la conexión no es el nodo que nombró el agente"
    );
    assert_eq!(
        conexion.to,
        nodo_titulado(&proyecto, "Respuesta del modelo").id,
        "el destino de la conexión no es el nodo que nombró el agente"
    );
}

/// **Hallazgo H3** — una conexión a un nodo que no existe no se crea, y se dice.
///
/// Los extremos se validan siempre: una conexión que apunta a un identificador ausente deja
/// el archivo corrupto y la aplicación no vuelve a abrirlo. Pero descartarla en silencio es
/// casi tan malo, y es lo que hace hoy el conversor de `create_mindmap`: el agente recibe
/// `success` y da por dibujado un flujo que no está. Aquí se rechaza **y** se informa.
#[test]
fn una_conexion_con_un_extremo_inexistente_no_se_crea_y_se_avisa() {
    let espacio = aislar_espacio_mcp("h3_extremo");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "extremo.mmcelt");

    let resultado = llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "extremo.mmcelt",
            "node_updates": [],
            "cross_connections": [
                {
                    "from_title": "Entrada del usuario",
                    "to_title": "Un nodo que nadie ha escrito",
                    "relation_type": "Dependencia"
                }
            ]
        }),
    );

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería seguir abriéndose");
    assert!(
        proyecto.connections.is_empty(),
        "se creó una conexión con un extremo inexistente"
    );
    assert!(
        proyecto.validar_estructura().is_ok(),
        "el mapa ha quedado corrupto después de una conexión inválida"
    );

    let avisos = resultado["connections_not_created"]
        .as_array()
        .unwrap_or_else(|| {
            panic!("la respuesta debe listar las conexiones rechazadas: {resultado}")
        });
    assert!(
        avisos
            .iter()
            .filter_map(|a| a.as_str())
            .any(|a| a.contains("Un nodo que nadie ha escrito")),
        "el aviso debe nombrar el extremo que no existe: {avisos:?}"
    );
}

/// **Hallazgo H3** — la misma conexión dos veces no duplica el mapa.
///
/// Un agente reintenta. Si cada reintento añadiera otra vez la misma relación, el mapa se
/// llenaría de aristas idénticas que el usuario tendría que borrar a mano una por una, y el
/// lienzo acabaría ilegible. Se comprueba dentro de una llamada y entre dos llamadas
/// seguidas, que es como ocurre de verdad.
#[test]
fn una_conexion_repetida_no_se_duplica() {
    let espacio = aislar_espacio_mcp("h3_repetida");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "repetida.mmcelt");

    let peticion = serde_json::json!({
        "file_path": "repetida.mmcelt",
        "node_updates": [],
        "cross_connections": [
            {
                "from_title": "Entrada del usuario",
                "to_title": "Respuesta del modelo",
                "label": "alimenta",
                "relation_type": "Dependencia"
            },
            {
                "from_title": "Entrada del usuario",
                "to_title": "Respuesta del modelo",
                "label": "alimenta",
                "relation_type": "Dependencia"
            }
        ]
    });

    llamar_herramienta("mmcelt_sync_ai_progress", peticion.clone());
    llamar_herramienta("mmcelt_sync_ai_progress", peticion);

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");
    assert_eq!(
        proyecto.connections.len(),
        1,
        "la misma conexión se ha añadido más de una vez: {:?}",
        proyecto.connections
    );
}

/// **Hallazgo H3** — un nodo no se conecta consigo mismo.
