/// **Hallazgo H3** — una conexión no reabre un camino que el usuario descartó.
///
/// Descartar es la forma más rotunda que tiene la persona de decir «no sigas por ahí», y el
/// servidor ya impide revivir un nodo descartado por la vía del `status`. Enlazar el flujo
/// con él lo devolvería al mapa por la puerta de al lado: el camino volvería a formar parte
/// del recorrido sin que su estado cambiara y sin que nadie lo aprobara. Es el mismo patrón
/// —una valla con una puerta contigua sin cerrar— que ya ha fallado dos veces en este
/// servidor.
#[test]
fn una_conexion_no_revive_un_camino_descartado() {
    use crate::model::EstadoNodo;

    let espacio = aislar_espacio_mcp("h3_descartado");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "descartado.mmcelt");

    let mut proyecto = cargar_proyecto_de_archivo(&ruta).expect("debería abrirse");
    let id = nodo_titulado(&proyecto, "Respuesta del modelo").id;
    if let Some(nodo) = proyecto.nodes.get_mut(&id) {
        nodo.status = EstadoNodo::Descartado;
    }
    crate::storage::guardar_proyecto_en_archivo(&proyecto, &ruta).expect("debería guardarse");

    let resultado = llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "descartado.mmcelt",
            "node_updates": [],
            "cross_connections": [
                { "from_title": "Entrada del usuario", "to_title": "Respuesta del modelo" }
            ]
        }),
    );

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");
    assert!(
        proyecto.connections.is_empty(),
        "el agente ha enlazado el flujo con un camino que el usuario descartó"
    );
    assert_eq!(
        proyecto.nodes[&id].status,
        EstadoNodo::Descartado,
        "el nodo descartado ha cambiado de estado"
    );

    let avisos = resultado["connections_not_created"]
        .as_array()
        .unwrap_or_else(|| panic!("la respuesta debe explicar el rechazo: {resultado}"));
    assert!(
        !avisos.is_empty(),
        "el agente tiene que saber por qué no se creó la conexión"
    );
}

/// **Hallazgo H3, sobre H6** — un rol que no se reconoce se avisa, no se degrada callando.
///
/// `RolNodo::desde_texto` cae en `Subtema` ante cualquier texto desconocido, que es lo
/// correcto al abrir un archivo antiguo y lo peor posible en la frontera con un agente:
/// adivinar mal no daría error y el mapa quedaría mal sin que nadie se entere. La
/// sincronización ya usa `reconocer_texto` para `status` y `priority` por este mismo motivo;
/// el rol entra por la misma puerta.
#[test]
fn un_rol_desconocido_se_avisa_en_lugar_de_degradarse_en_silencio() {
    let espacio = aislar_espacio_mcp("h3_rol_raro");
    let ruta = escribir_mapa_humano(&espacio.carpeta, "rol_raro.mmcelt");

    let resultado = llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "rol_raro.mmcelt",
            "node_updates": [
                { "title": "Nodo con rol raro", "parent_title": "GhatIA", "role": "Epica" }
            ]
        }),
    );

    let avisos = resultado["unrecognized_values"]
        .as_array()
        .expect("la respuesta ya listaba los valores no reconocidos");
    assert!(
        avisos
            .iter()
            .filter_map(|a| a.as_str())
            .any(|a| a.contains("role") && a.contains("Epica")),
        "un rol inventado tiene que aparecer entre los valores no reconocidos: {avisos:?}"
    );

    let proyecto = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");
    assert!(
        proyecto
            .nodes
            .values()
            .any(|n| n.title == "Nodo con rol raro"),
        "el nodo debe crearse igualmente: el aviso informa, no cancela el trabajo"
    );
}

/// **Hallazgo H3** — el catálogo publica el rol, las etiquetas y las conexiones cruzadas.
///
/// La lección de H2: para un agente, lo que no sale en `tools/list` no existe. Una ampliación
/// del contrato que no se anuncie en el esquema deja el bloqueo exactamente donde estaba,
/// porque el agente seguirá creyendo que la herramienta no sabe hacerlo.
#[test]
fn el_catalogo_publica_el_rol_las_etiquetas_y_las_conexiones_cruzadas() {
    let respuesta = pedir_al_servidor("tools/list", serde_json::json!({}));

    let sincronizar = respuesta["result"]["tools"]
        .as_array()
        .expect("debería devolver una lista")
        .iter()
        .find(|h| h["name"] == "mmcelt_sync_ai_progress")
        .expect("la herramienta de sincronización debería estar en el catálogo")
        .clone();

    let propiedades = &sincronizar["inputSchema"]["properties"];

    assert!(
        !propiedades["cross_connections"].is_null(),
        "el esquema no anuncia «cross_connections»: {sincronizar}"
    );

    let campos_del_nodo = &propiedades["node_updates"]["items"]["properties"];
    assert!(
        !campos_del_nodo["role"].is_null(),
        "el esquema no anuncia «role» en las actualizaciones de nodo: {sincronizar}"
    );
    assert!(
        !campos_del_nodo["tags"].is_null(),
        "el esquema no anuncia «tags» en las actualizaciones de nodo: {sincronizar}"
    );
}

