/// **Hallazgo H4** — las conexiones cruzadas admiten sus extremos por identificador.
///
/// Es lo que H3 dejó señalado a propósito: los extremos se resolvían con el mismo índice de
/// títulos que `node_updates`, así que heredaban su ambigüedad. Una arista mal puesta es peor
/// que una nota mal puesta: cambia lo que el diagrama afirma.
#[test]
fn las_conexiones_cruzadas_admiten_extremos_por_id() {
    let espacio = aislar_espacio_mcp("h4_conexion_por_id");
    let ruta = escribir_mapa_con_titulos_repetidos(&espacio.carpeta, "conexion.mmcelt");

    let antes = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");
    let no_de_correcciones = hijo_de(&antes, "¿Hay correcciones?", "No");
    let si_de_entradas = hijo_de(&antes, "¿Quedan entradas?", "Sí");

    let resultado = llamar_herramienta(
        "mmcelt_sync_ai_progress",
        serde_json::json!({
            "file_path": "conexion.mmcelt",
            "node_updates": [],
            "cross_connections": [
                {
                    "from_id": no_de_correcciones.to_string(),
                    "to_id": si_de_entradas.to_string(),
                    "label": "sigue el bucle",
                    "relation_type": "Dependencia"
                }
            ]
        }),
    );

    assert_eq!(
        resultado["connections_added"], 1,
        "la conexión por identificadores no se creó: {resultado}"
    );

    let despues = cargar_proyecto_de_archivo(&ruta).expect("el mapa debería abrirse");
    assert_eq!(
        despues.connections.len(),
        1,
        "el mapa debería tener exactamente la conexión pedida"
    );
    let conexion = &despues.connections[0];
    assert_eq!(
        conexion.from, no_de_correcciones,
        "el origen de la conexión no es el nodo que se señaló"
    );
    assert_eq!(
        conexion.to, si_de_entradas,
        "el destino de la conexión no es el nodo que se señaló"
    );
}

/// **Hallazgo H4** — un extremo ambiguo rechaza la operación entera, sin dibujar nada.
///
/// La alternativa sería crear la arista contra uno de los gemelos y devolver `success`. El
