/// Los archivos propios de cada producto se enseñan como fuentes, pero no se mezclan solos.
#[test]
fn los_archivos_nativos_se_muestran_pero_no_se_incorporan() {
    let raiz = carpeta_temporal_contexto("fuentes-nativas");
    std::fs::write(raiz.join("AGENTS.md"), "SOLO CODEX").expect("escribir AGENTS.md");
    std::fs::write(raiz.join("CLAUDE.md"), "SOLO CLAUDE").expect("escribir CLAUDE.md");
    let contexto = crate::proyecto_trabajo::ContextoProyecto::nuevo(
        crate::proyecto_trabajo::IdProyecto::nuevo(),
        "Fuentes nativas",
        &raiz,
    )
    .expect("contexto válido");

    let fuentes = crate::sesiones_agentes::detectar_fuentes_nativas(&contexto)
        .expect("las fuentes interiores deben detectarse");
    assert_eq!(fuentes.len(), 2);
    assert!(fuentes.iter().all(|fuente| !fuente.incorporada));
    assert!(fuentes
        .iter()
        .any(|fuente| fuente.contenido == "SOLO CODEX"));
    assert!(fuentes
        .iter()
        .any(|fuente| fuente.contenido == "SOLO CLAUDE"));

    let mut borrador = borrador_de_sesion("REGLAS", "MAPA", "ENCARGO");
    borrador.fuentes_nativas = fuentes;
    let prompt = prompt_de_sesion(&borrador);
    assert!(!prompt.texto().contains("SOLO CODEX"));
    assert!(!prompt.texto().contains("SOLO CLAUDE"));
    std::fs::remove_dir_all(raiz).expect("limpiar temporal");
}

/// Una aceptación solo sigue vigente mientras la fuente conserve exactamente los mismos bytes.
#[test]
fn el_consentimiento_de_una_fuente_nativa_caduca_al_modificarla() {
    use crate::configuracion_agente_proyecto::{aceptar_fuente, EstadoFuenteNativa};

    let raiz = carpeta_temporal_contexto("consentimiento-fuente");
    std::fs::write(raiz.join("AGENTS.md"), "CONTENIDO INICIAL").expect("crear fuente nativa");
    let contexto = crate::proyecto_trabajo::ContextoProyecto::nuevo(
        crate::proyecto_trabajo::IdProyecto::nuevo(),
        "Consentimiento",
        &raiz,
    )
    .expect("contexto válido");

    let nuevas = crate::sesiones_agentes::detectar_fuentes_nativas(&contexto)
        .expect("detectar fuente nueva");
    assert_eq!(nuevas[0].estado, EstadoFuenteNativa::Nueva);
    assert!(!nuevas[0].incorporada);
    assert!(nuevas[0].contenido_anterior.is_none());

    aceptar_fuente(&contexto, "AGENTS.md").expect("aceptar la versión observada");
    let aceptadas = crate::sesiones_agentes::detectar_fuentes_nativas(&contexto)
        .expect("recargar fuente aceptada");
    assert_eq!(aceptadas[0].estado, EstadoFuenteNativa::AceptadaSinCambios);
    assert!(aceptadas[0].incorporada);

    std::fs::write(raiz.join("AGENTS.md"), "CONTENIDO MODIFICADO")
        .expect("modificar fuente nativa");
    let modificadas = crate::sesiones_agentes::detectar_fuentes_nativas(&contexto)
        .expect("recargar fuente modificada");
    assert_eq!(modificadas[0].estado, EstadoFuenteNativa::Modificada);
    assert!(!modificadas[0].incorporada);
    assert_eq!(
        modificadas[0].contenido_anterior.as_deref(),
        Some("CONTENIDO INICIAL")
    );

    std::fs::remove_dir_all(raiz).expect("limpiar consentimiento");
}

/// Las cuatro pestañas se pueden recorrer y dibujar sin guardar ni alterar el mapa por observarlo.
#[test]
fn la_ventana_de_proyecto_e_instrucciones_es_completa_y_no_escribe_al_dibujarse() {
    use crate::ui::proyecto_ia_modal::{EstadoEditorProyectoIa, PestanaProyectoIa};

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("ventana-proyecto-ia");
    std::fs::create_dir_all(raiz.join(".mmcelt")).expect("crear carpeta portable");
    let ruta_reglas = raiz.join(".mmcelt/instrucciones-agente.md");
    std::fs::write(&ruta_reglas, "REGLAS SIN GUARDAR").expect("crear reglas de referencia");
    let reglas_antes = std::fs::read(&ruta_reglas).expect("leer reglas iniciales");
    let huella_mapa_antes = crate::autoguardado::calcular_huella(&app.mapa.proyecto);
    let mut editor = EstadoEditorProyectoIa {
        raiz_proyecto: std::fs::canonicalize(&raiz).expect("canonizar proyecto"),
        pestana: PestanaProyectoIa::Proyecto,
        reglas: "REGLAS EDITABLES".to_string(),
        encargo: "ENCARGO EDITABLE".to_string(),
        idioma_documento: Idioma::Espanol,
        fuentes: Vec::new(),
        indice_plantilla_seleccionada: 0,
        nombre_nueva_plantilla: String::new(),
    };

    for idioma in Idioma::TODOS {
        for pestana in PestanaProyectoIa::TODAS {
            editor.pestana = pestana;
            editor.idioma_documento = idioma;
            let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
                crate::ui::proyecto_ia_modal::dibujar_contenido_para_prueba(
                    app,
                    &mut editor,
                    idioma,
                    ui,
                );
            });
            assert!(
                textos
                    .iter()
                    .any(|texto| texto.contains(pestana.titulo(idioma))),
                "la pestaña {pestana:?} no se pintó en {idioma:?}: {textos:?}"
            );
            assert!(
                textos
                    .iter()
                    .any(|texto| texto.contains(Texto::ProyectoIaAyudaInicial.en(idioma))),
                "falta la ayuda de primer uso en {idioma:?}: {textos:?}"
            );
            let controles: Vec<&str> = match pestana {
                PestanaProyectoIa::Proyecto => vec![
                    Texto::ModalQueHasIntentadoPlasmar.en(idioma),
                    Texto::ModalQueObjetivosYResultados.en(idioma),
                    Texto::ModalPublicoObjetivoContextoDe.en(idioma),
                    Texto::ModalAutorCreador.en(idioma),
                ],
                PestanaProyectoIa::Instrucciones => vec![
                    Texto::ProyectoIaCarpetaTrabajo.en(idioma),
                    Texto::ProyectoIaExplicacionCarpetaTrabajo.en(idioma),
                    Texto::ProyectoIaIdiomaDocumento.en(idioma),
                    Texto::SesionAgenteReglas.en(idioma),
                    Texto::ProyectoIaRestaurarPlantilla.en(idioma),
                ],
                PestanaProyectoIa::Plantillas => vec![
                    Texto::ProyectoIaAplicarPlantilla.en(idioma),
                    Texto::SesionAgenteEncargo.en(idioma),
                    Texto::ProyectoIaGuardarComoPlantilla.en(idioma),
                    Texto::ProyectoIaNombrePlantillaHint.en(idioma),
                    crate::ai_export::PlantillaEncargo::TODAS[0].titulo_interfaz(idioma),
                ],
                PestanaProyectoIa::VistaCompleta => vec![
                    Texto::SesionAgenteContrato.en(idioma),
                    Texto::SesionAgenteReglas.en(idioma),
                    Texto::SesionAgenteContexto.en(idioma),
                    Texto::SesionAgenteEncargo.en(idioma),
                ],
            };
            for control in controles {
                assert!(
                    textos.iter().any(|texto| texto.contains(control)),
                    "falta el control «{control}» en {pestana:?}/{idioma:?}: {textos:?}"
                );
            }
        }
    }

    assert_eq!(
        crate::autoguardado::calcular_huella(&app.mapa.proyecto),
        huella_mapa_antes,
        "observar las pestañas no debe modificar el mapa"
    );
    assert_eq!(
        std::fs::read(&ruta_reglas).expect("releer reglas"),
        reglas_antes,
        "dibujar no debe guardar las reglas editables"
    );
    assert!(!raiz.join(".mmcelt/configuracion-agente.json").exists());
    std::fs::remove_dir_all(raiz).expect("limpiar ventana de prueba");
}

/// Una fuente con nombre permitido tampoco puede escapar mediante un enlace simbólico.
#[test]
fn una_fuente_enlazada_fuera_del_proyecto_se_rechaza() {
    let raiz = carpeta_temporal_contexto("fuente-enlazada");
    let exterior = raiz.with_file_name(format!("mmcelt-fuente-exterior-{}", uuid::Uuid::new_v4()));
    std::fs::write(&exterior, "INSTRUCCIÓN EXTERIOR").expect("crear fuente exterior");
    let enlace = raiz.join("AGENTS.md");

    #[cfg(windows)]
    let creado = std::os::windows::fs::symlink_file(&exterior, &enlace).is_ok();
    #[cfg(unix)]
    let creado = std::os::unix::fs::symlink(&exterior, &enlace).is_ok();

    if !creado {
        std::fs::remove_dir_all(raiz).expect("limpiar raíz sin enlace");
        std::fs::remove_file(exterior).expect("limpiar fuente exterior");
        eprintln!(
            "[MMCelt] El sistema no permite crear el enlace simbólico de la prueba de fuentes."
        );
        return;
    }

    let contexto = crate::proyecto_trabajo::ContextoProyecto::nuevo(
        crate::proyecto_trabajo::IdProyecto::nuevo(),
        "Fuente enlazada",
        &raiz,
    )
    .expect("contexto válido");
    assert!(crate::sesiones_agentes::detectar_fuentes_nativas(&contexto).is_err());
    std::fs::remove_file(enlace).expect("retirar enlace");
    std::fs::remove_dir_all(raiz).expect("limpiar raíz");
    std::fs::remove_file(exterior).expect("limpiar fuente exterior");
}

/// Aceptar una fuente vuelve a validar la ruta y no convierte un enlace exterior en confianza.
#[test]
fn no_se_puede_guardar_consentimiento_para_una_fuente_enlazada_fuera() {
    let raiz = carpeta_temporal_contexto("aceptacion-enlace");
    let exterior = raiz.with_file_name(format!("mmcelt-aceptacion-{}", uuid::Uuid::new_v4()));
    std::fs::write(&exterior, "INSTRUCCIÓN EXTERIOR").expect("crear fuente exterior");
    let enlace = raiz.join("AGENTS.md");

    #[cfg(windows)]
    let creado = std::os::windows::fs::symlink_file(&exterior, &enlace).is_ok();
    #[cfg(unix)]
    let creado = std::os::unix::fs::symlink(&exterior, &enlace).is_ok();

    if !creado {
        std::fs::remove_dir_all(raiz).expect("limpiar raíz sin enlace");
        std::fs::remove_file(exterior).expect("limpiar fuente exterior");
        eprintln!("[MMCelt] El sistema no permite crear el enlace de la prueba de aceptación.");
        return;
    }

    let contexto = crate::proyecto_trabajo::ContextoProyecto::nuevo(
        crate::proyecto_trabajo::IdProyecto::nuevo(),
        "Aceptación enlazada",
        &raiz,
    )
    .expect("contexto válido");
    assert!(crate::configuracion_agente_proyecto::aceptar_fuente(&contexto, "AGENTS.md").is_err());
    assert!(
        !raiz.join(".mmcelt/configuracion-agente.json").exists(),
        "rechazar el enlace no debe dejar una aceptación parcial"
    );

    std::fs::remove_file(enlace).expect("retirar enlace");
    std::fs::remove_dir_all(raiz).expect("limpiar raíz");
    std::fs::remove_file(exterior).expect("limpiar fuente exterior");
}

/// Prepara un proyecto y un borrador mínimos para ejercitar el expediente en disco.
fn datos_de_expediente(
    nombre: &str,
) -> (
    std::path::PathBuf,
    crate::proyecto_trabajo::ContextoProyecto,
    crate::sesiones_agentes::BorradorSesion,
) {
    let raiz = carpeta_temporal_contexto(nombre);
    std::fs::write(raiz.join("mapa.mmcelt"), "MAPA GUARDADO").expect("crear mapa de referencia");
    let contexto = crate::proyecto_trabajo::ContextoProyecto::nuevo(
        crate::proyecto_trabajo::IdProyecto::nuevo(),
        "Expediente",
        &raiz,
    )
    .expect("contexto válido");
    let borrador = borrador_de_sesion("REGLAS", "MAPA", "ENCARGO");
    (raiz, contexto, borrador)
}

/// El expediente es la prueba durable de qué texto se confirmó, sin recomponerlo después.
#[test]
fn el_expediente_conserva_exactamente_el_prompt_aprobado() {
    let (raiz, contexto, borrador) = datos_de_expediente("prompt-exacto");
    let prompt = prompt_de_sesion(&borrador);
    let preparada = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar expediente");

    assert_eq!(
        std::fs::read_to_string(&preparada.ruta_inicio).expect("leer prompt persistido"),
        prompt.texto()
    );
    assert_eq!(preparada.metadatos.prompt_bytes, prompt.texto().len());
    assert!(preparada.carpeta.starts_with(contexto.raiz()));
    std::fs::remove_dir_all(raiz).expect("limpiar expediente");
}

/// Cada CLI conserva una identidad portable y distinta en el nombre de su expediente.
#[test]
fn los_tres_cli_nombran_su_expediente_con_la_identidad_correcta() {
    for (agente, identidad) in [
        (crate::conectores::IdAgente::ClaudeCode, "claude-code"),
        (crate::conectores::IdAgente::CodexCli, "codex-cli"),
        (crate::conectores::IdAgente::GeminiCli, "gemini-cli"),
    ] {
        let (raiz, contexto, mut borrador) = datos_de_expediente("nombre-expediente-cli");
        borrador.agente = agente;
        let prompt = prompt_de_sesion(&borrador);
        let preparada = crate::sesiones_agentes::preparar_sesion(
            &contexto,
            std::path::Path::new("mapa.mmcelt"),
            &prompt,
        )
        .expect("cada CLI debe poder preparar su expediente");
        let nombre = preparada
            .carpeta
            .file_name()
            .and_then(|valor| valor.to_str())
            .expect("el nombre del expediente debe ser portable");
        let esperado = format!(
            "{}-{identidad}-{}",
            preparada.metadatos.fecha_utc.format("%Y%m%dT%H%M%S%.3fZ"),
            preparada.metadatos.id_sesion
        );

        assert_eq!(
            nombre, esperado,
            "el expediente de {agente:?} debe conservar exactamente su identidad"
        );
        assert_eq!(preparada.metadatos.agente, agente);
        std::fs::remove_dir_all(raiz).expect("limpiar expediente del CLI");
    }
}

/// La vista de confirmación y el expediente consumen el mismo objeto, sin recomponer sus bytes.
#[test]
fn vista_confirmacion_y_expediente_conservan_el_mismo_prompt_byte_por_byte() {
    let (raiz, contexto, borrador) = datos_de_expediente("prompt-tres-representaciones");
    let vista = crate::ui::sesion_agente_modal::componer_vista_previa(&borrador)
        .expect("componer la vista confirmable");
    let bytes_vistos = vista.texto().as_bytes().to_vec();
    let preparada = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &vista,
    )
    .expect("persistir exactamente la vista");

    assert_eq!(std::fs::read(&preparada.ruta_inicio).unwrap(), bytes_vistos);
    std::fs::remove_dir_all(raiz).expect("limpiar igualdad de prompt");
}

/// Cualquier cambio posterior a la vista confirmada obliga a revisarla de nuevo.
#[test]
fn la_confirmacion_caduca_si_cambia_un_bloque_antes_del_lanzamiento() {
    use crate::sesiones_agentes::{ConfirmacionSesion, FuenteInstrucciones};

    let mut proyecto = Proyecto::nuevo_vacio("Mapa confirmable");
    let borrador = borrador_de_sesion("REGLAS", "CONTEXTO", "ENCARGO");
    let prompt = prompt_de_sesion(&borrador);
    let fuentes = Vec::<FuenteInstrucciones>::new();
    let confirmacion =
        ConfirmacionSesion::nueva(prompt, proyecto.revision(), "REGLAS", "ENCARGO", &fuentes);

    confirmacion
        .validar(proyecto.revision(), "REGLAS", "ENCARGO", &fuentes)
        .expect("la misma instantánea sigue vigente");

    proyecto.marcar_modificado();
    for resultado in [
        confirmacion.validar(proyecto.revision(), "REGLAS", "ENCARGO", &fuentes),
        confirmacion.validar(
            crate::model::RevisionProyecto::INICIAL,
            "REGLAS CAMBIADAS",
            "ENCARGO",
            &fuentes,
        ),
        confirmacion.validar(
            crate::model::RevisionProyecto::INICIAL,
            "REGLAS",
            "ENCARGO CAMBIADO",
            &fuentes,
        ),
    ] {
        assert!(matches!(
            resultado,
            Err(crate::error::AppError::ConfirmacionCaducada)
        ));
    }

    let mut fuente_modificada = borrador_de_sesion("", "", "").fuentes_nativas;
    fuente_modificada.push(FuenteInstrucciones {
        nombre: "AGENTS.md",
        ruta: std::path::PathBuf::from("AGENTS.md"),
        contenido: "CAMBIO".to_string(),
        incorporada: true,
        estado: crate::configuracion_agente_proyecto::EstadoFuenteNativa::AceptadaSinCambios,
        contenido_anterior: Some("ANTERIOR".to_string()),
    });
    assert!(matches!(
        confirmacion.validar(
            crate::model::RevisionProyecto::INICIAL,
            "REGLAS",
            "ENCARGO",
            &fuente_modificada,
        ),
        Err(crate::error::AppError::ConfirmacionCaducada)
    ));

    let fuente_sin_incorporar = FuenteInstrucciones {
        nombre: "AGENTS.md",
        ruta: std::path::PathBuf::from("AGENTS.md"),
        contenido: "MISMO CONTENIDO".to_string(),
        incorporada: false,
        estado: crate::configuracion_agente_proyecto::EstadoFuenteNativa::Nueva,
        contenido_anterior: None,
    };
    let prompt = prompt_de_sesion(&borrador);
    let confirmacion = ConfirmacionSesion::nueva(
        prompt,
        crate::model::RevisionProyecto::INICIAL,
        "REGLAS",
        "ENCARGO",
        std::slice::from_ref(&fuente_sin_incorporar),
    );
    let mut fuente_elegida = fuente_sin_incorporar;
    fuente_elegida.incorporada = true;
    confirmacion
        .validar(
            crate::model::RevisionProyecto::INICIAL,
            "REGLAS",
            "ENCARGO",
            &[fuente_elegida],
        )
        .expect("la selección visible no simula un cambio del archivo en disco");
}

/// Los metadatos describen la ejecución, no la cuenta autenticada del proveedor.
#[test]
fn el_expediente_no_contiene_credenciales_ni_correos() {
    let (raiz, contexto, borrador) = datos_de_expediente("sin-credenciales");
    let prompt = prompt_de_sesion(&borrador);
    let preparada = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar expediente");
    let json = std::fs::read_to_string(&preparada.ruta_metadatos).expect("leer metadatos");

    for prohibido in ["token", "api_key", "email", "orgid"] {
        assert!(
            !json.to_lowercase().contains(prohibido),
            "los metadatos no deben contener {prohibido}: {json}"
        );
    }
    std::fs::remove_dir_all(raiz).expect("limpiar expediente");
}

/// La ruta del mapa se valida antes de crear una sola carpeta del expediente.
#[test]
fn el_expediente_rechaza_un_mapa_fuera_del_proyecto() {
    let (raiz, contexto, borrador) = datos_de_expediente("mapa-exterior");
    let prompt = prompt_de_sesion(&borrador);
    assert!(crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("../fuera.mmcelt"),
        &prompt,
    )
    .is_err());
    assert!(
        !raiz.join(".mmcelt/sesiones").exists(),
        "un mapa inválido no debe dejar un expediente parcial"
    );
    std::fs::remove_dir_all(raiz).expect("limpiar expediente");
}

