/// El estado en memoria solo se anuncia después de persistir la misma transición.
#[test]
fn actualizar_el_estado_reescribe_los_metadatos_del_expediente() {
    let (raiz, contexto, borrador) = datos_de_expediente("estado-expediente");
    let prompt = prompt_de_sesion(&borrador);
    let mut preparada = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar expediente");
    crate::sesiones_agentes::actualizar_estado(
        &contexto,
        &mut preparada,
        crate::sesiones_agentes::EstadoLanzamiento::Iniciado,
    )
    .expect("persistir transición");

    let guardados: crate::sesiones_agentes::MetadatosSesion =
        serde_json::from_slice(&std::fs::read(&preparada.ruta_metadatos).expect("leer metadatos"))
            .expect("interpretar metadatos");
    assert_eq!(
        guardados.estado,
        crate::sesiones_agentes::EstadoLanzamiento::Iniciado
    );
    assert_eq!(preparada.metadatos, guardados);
    std::fs::remove_dir_all(raiz).expect("limpiar expediente");
}

/// Una estructura manipulada no puede convertir la actualización de estado en escritura general.
#[test]
fn actualizar_estado_rechaza_un_destino_que_no_es_su_expediente() {
    let (raiz, contexto, borrador) = datos_de_expediente("estado-falsificado");
    let prompt = prompt_de_sesion(&borrador);
    let mut preparada = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar expediente");
    preparada.ruta_metadatos = raiz.join("mapa.mmcelt");

    assert!(crate::sesiones_agentes::actualizar_estado(
        &contexto,
        &mut preparada,
        crate::sesiones_agentes::EstadoLanzamiento::Iniciado,
    )
    .is_err());
    assert_eq!(
        std::fs::read_to_string(raiz.join("mapa.mmcelt")).expect("leer mapa protegido"),
        "MAPA GUARDADO"
    );
    std::fs::remove_dir_all(raiz).expect("limpiar expediente");
}

/// Ni siquiera otro expediente válido puede sustituir al que conserva la identidad de la sesión.
#[test]
fn actualizar_estado_no_puede_sustituir_el_expediente_por_otra_sesion() {
    let (raiz, contexto, borrador) = datos_de_expediente("estado-otra-sesion");
    let prompt = prompt_de_sesion(&borrador);
    let mut primera = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar primera sesión");
    let segunda = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar segunda sesión");
    let segunda_antes = std::fs::read(&segunda.ruta_metadatos).expect("leer segunda sesión");
    primera.carpeta = segunda.carpeta.clone();
    primera.ruta_inicio = segunda.ruta_inicio.clone();
    primera.ruta_metadatos = segunda.ruta_metadatos.clone();

    assert!(crate::sesiones_agentes::actualizar_estado(
        &contexto,
        &mut primera,
        crate::sesiones_agentes::EstadoLanzamiento::Iniciado,
    )
    .is_err());
    assert_eq!(
        std::fs::read(&segunda.ruta_metadatos).expect("releer segunda sesión"),
        segunda_antes,
        "rechazar la sustitución no debe modificar el expediente ajeno"
    );
    std::fs::remove_dir_all(raiz).expect("limpiar expediente");
}

// ============================================================================
// «Enviar a...» — órdenes CLI y detección de ejecutables
// ============================================================================

/// Construye una orden sobre un expediente real y devuelve también la raíz para limpiarla.
fn orden_cli_de_prueba(
    agente: crate::conectores::IdAgente,
    nombre_raiz: &str,
) -> (std::path::PathBuf, crate::lanzador_agentes::OrdenCli) {
    let (raiz, contexto, mut borrador) = datos_de_expediente(nombre_raiz);
    borrador.agente = agente;
    borrador.encargo = "SECRETO-MUY-LARGO & calc $(whoami)".to_string();
    let prompt = prompt_de_sesion(&borrador);
    let sesion = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar sesión para orden");
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");
    let mut agente_detectado = agente_cli_para_vista_previa(ejecutable);
    agente_detectado.id = agente;
    let ejecutable =
        crate::lanzador_agentes::confirmar_ejecutable(&agente_detectado, contexto.raiz())
            .expect("confirmar ejecutable de pruebas");
    let orden = crate::lanzador_agentes::orden_para(agente, ejecutable, &contexto, &sesion)
        .expect("componer orden");
    (raiz, orden)
}

/// El proceso recibe una referencia breve al expediente, no el prompt completo ni sus secretos.
#[test]
fn ninguna_orden_cli_contiene_el_prompt_completo() {
    for agente in [
        crate::conectores::IdAgente::ClaudeCode,
        crate::conectores::IdAgente::CodexCli,
        crate::conectores::IdAgente::GeminiCli,
    ] {
        let (raiz, orden) = orden_cli_de_prueba(agente, "orden-sin-prompt");
        let argumentos = orden.argumentos.join(" ").replace('\\', "/");
        assert!(!argumentos.contains("SECRETO-MUY-LARGO"));
        assert!(!argumentos.contains("whoami"));
        assert!(argumentos.contains(".mmcelt/sesiones/"));
        std::fs::remove_dir_all(raiz).expect("limpiar orden");
    }
}

/// Gemini necesita `-i` para conservar la sesión interactiva después del mensaje inicial.
#[test]
fn gemini_recibe_un_prompt_inicial_y_sigue_interactivo() {
    let (raiz, orden) = orden_cli_de_prueba(crate::conectores::IdAgente::GeminiCli, "orden-gemini");
    assert_eq!(orden.argumentos.first().map(String::as_str), Some("-i"));
    std::fs::remove_dir_all(raiz).expect("limpiar orden");
}

/// La orden CLI es exhaustiva para los tres CLI oficiales y rechaza de forma tipada cualquier conector retirado.
#[test]
fn orden_para_es_exhaustiva_para_los_tres_cli_y_rechaza_conectores_retirados() {
    for agente in [
        crate::conectores::IdAgente::ClaudeCode,
        crate::conectores::IdAgente::CodexCli,
        crate::conectores::IdAgente::GeminiCli,
    ] {
        let (raiz, orden) = orden_cli_de_prueba(agente, "orden-cli-exhaustiva");
        if agente == crate::conectores::IdAgente::GeminiCli {
            assert_eq!(orden.argumentos.first().map(String::as_str), Some("-i"));
        } else {
            assert_ne!(orden.argumentos.first().map(String::as_str), Some("-i"));
        }
        std::fs::remove_dir_all(raiz).expect("limpiar orden");
    }

    let (raiz, contexto, borrador) = datos_de_expediente("orden-no-cli");
    let prompt = prompt_de_sesion(&borrador);
    let sesion = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar sesión");
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");
    let agente_detectado = agente_cli_para_vista_previa(ejecutable);
    let confirmado =
        crate::lanzador_agentes::confirmar_ejecutable(&agente_detectado, contexto.raiz())
            .expect("confirmar ejecutable");

    for no_cli in [
        crate::conectores::IdAgente::ClaudeDesktop,
        crate::conectores::IdAgente::Antigravity,
        crate::conectores::IdAgente::Cursor,
        crate::conectores::IdAgente::Windsurf,
    ] {
        let error =
            crate::lanzador_agentes::orden_para(no_cli, confirmado.clone(), &contexto, &sesion)
                .expect_err("los conectores no-CLI deben ser rechazados sin consola compatible");
        let mensaje_error = format!("{error}");
        assert!(
            mensaje_error.contains("no ofrece una consola compatible"),
            "{no_cli:?} debe rechazar con consola incompatible, se obtuvo: {mensaje_error}"
        );
    }
    std::fs::remove_dir_all(raiz).expect("limpiar no-cli");
}

/// Los caracteres de shell pertenecen al nombre de una carpeta, no a una cadena ejecutable.
#[test]
fn caracteres_de_shell_en_la_carpeta_no_se_convierten_en_ordenes() {
    let (raiz, orden) = orden_cli_de_prueba(
        crate::conectores::IdAgente::ClaudeCode,
        "Proyecto & calc $(whoami) ' comillas",
    );
    assert_eq!(
        orden.directorio,
        raiz.canonicalize().expect("raíz canónica")
    );
    assert!(!orden
        .argumentos
        .iter()
        .any(|argumento| argumento.contains("calc") || argumento.contains("whoami")));
    std::fs::remove_dir_all(raiz).expect("limpiar orden");
}

/// La búsqueda respeta las entradas separadas de PATH y las extensiones ejecutables de Windows.
#[test]
fn buscar_ejecutable_recorre_path_y_pathext_sin_concatenar_ordenes() {
    let raiz = carpeta_temporal_contexto("buscar-ejecutable");
    let primera = raiz.join("primera");
    let segunda = raiz.join("segunda & no-es-una-orden");
    std::fs::create_dir_all(&primera).expect("crear primera entrada");
    std::fs::create_dir_all(&segunda).expect("crear segunda entrada");
    #[cfg(windows)]
    let candidato = segunda.join("claude.EXE");
    #[cfg(unix)]
    let candidato = segunda.join("claude");
    std::fs::write(&candidato, "simulado").expect("crear candidato");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut permisos = std::fs::metadata(&candidato)
            .expect("leer permisos")
            .permissions();
        permisos.set_mode(0o755);
        std::fs::set_permissions(&candidato, permisos).expect("hacer ejecutable");
    }
    let path = std::env::join_paths([primera, segunda]).expect("formar PATH aislado");

    assert_eq!(
        crate::conectores::buscar_ejecutable(
            "claude",
            path.as_os_str(),
            std::ffi::OsStr::new(".COM;.EXE;.CMD"),
        ),
        Some(candidato)
    );
    std::fs::remove_dir_all(raiz).expect("limpiar búsqueda");
}

/// Solo aparecen los tres CLI aunque persistan huellas locales de conectores retirados.
#[test]
fn detectar_agentes_ignora_huellas_de_los_conectores_retirados() {
    let personal = carpeta_temporal_contexto("detectar-consolas");
    std::fs::create_dir_all(personal.join(".antigravity")).expect("simular Antigravity");
    std::fs::create_dir_all(personal.join(".cursor")).expect("simular Cursor");
    std::fs::create_dir_all(personal.join(".codeium/windsurf")).expect("simular Windsurf");
    let configuracion_antigravity = personal.join(".gemini/antigravity/mcp_config.json");
    std::fs::create_dir_all(
        configuracion_antigravity
            .parent()
            .expect("la configuración tiene carpeta contenedora"),
    )
    .expect("simular la carpeta real de Antigravity dentro de .gemini");
    std::fs::write(&configuracion_antigravity, "")
        .expect("simular el archivo vacío que queda tras desconectarlo");
    for carpeta in [
        ".gemini/antigravity-backup",
        ".gemini/antigravity-browser-profile",
        ".gemini/antigravity-ide",
    ] {
        std::fs::create_dir_all(personal.join(carpeta))
            .expect("simular una carpeta real adicional de Antigravity");
    }
    for archivo in [
        ".gemini/GEMINI.md",
        ".gemini/config",
        ".gemini/history",
        ".gemini/google_accounts.json",
    ] {
        std::fs::write(personal.join(archivo), "")
            .expect("simular un archivo real adicional del perfil de Google");
    }
    let bin = personal.join("bin");
    std::fs::create_dir_all(&bin).expect("crear bin aislado");
    #[cfg(windows)]
    let ejecutables = ["claude.EXE", "codex.EXE"];
    #[cfg(unix)]
    let ejecutables = ["claude", "codex"];
    for nombre in ejecutables {
        let ruta = bin.join(nombre);
        std::fs::write(&ruta, "simulado").expect("crear consola simulada");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut permisos = std::fs::metadata(&ruta)
                .expect("leer permisos")
                .permissions();
            permisos.set_mode(0o755);
            std::fs::set_permissions(&ruta, permisos).expect("hacer consola ejecutable");
        }
    }
    let path = std::env::join_paths([&bin]).expect("formar PATH aislado");
    let agentes = crate::conectores::detectar_agentes_en_con_entorno(
        &personal,
        path.as_os_str(),
        std::ffi::OsStr::new(".EXE;.CMD"),
    );

    let ids: Vec<_> = agentes.iter().map(|agente| agente.id).collect();
    assert_eq!(
        ids,
        [
            crate::conectores::IdAgente::ClaudeCode,
            crate::conectores::IdAgente::CodexCli,
            crate::conectores::IdAgente::GeminiCli,
        ],
        "las huellas antiguas no pueden reactivar conectores sin consola"
    );
    for id in [
        crate::conectores::IdAgente::ClaudeCode,
        crate::conectores::IdAgente::CodexCli,
    ] {
        let agente = agentes
            .iter()
            .find(|agente| agente.id == id)
            .expect("cada consola simulada debe detectarse");
        assert!(agente.cli.is_some());
        assert!(!agente.conectado);
    }
    let gemini = agentes
        .iter()
        .find(|agente| agente.id == crate::conectores::IdAgente::GeminiCli)
        .expect("la carpeta .gemini debe seguir identificándose como Gemini CLI");
    assert!(
        gemini.cli.is_none(),
        "este caso debe demostrar la detección por la carpeta, no por PATH"
    );
    assert_eq!(
        gemini.ruta_configuracion,
        personal.join(".gemini/settings.json"),
        "los restos internos de Antigravity no pueden cambiar la configuración de Gemini CLI"
    );
    assert!(!gemini.conectado);
    std::fs::remove_dir_all(personal).expect("limpiar detección");
}

/// En Windows, una instalación npm deja un script Unix sin extensión junto al lanzador de
/// `PATHEXT`; la detección debe elegir el segundo porque es el que Windows puede ejecutar.
#[cfg(windows)]
#[test]
fn pathext_manda_sobre_un_script_npm_sin_extension() {
    let carpeta = carpeta_temporal_contexto("pathext-npm");
    std::fs::write(carpeta.join("claude"), "#!/bin/sh\n").expect("crear script Unix");
    std::fs::write(carpeta.join("claude.CMD"), "@echo off\r\n").expect("crear lanzador Windows");
    let path = std::env::join_paths([&carpeta]).expect("construir PATH aislado");

    let encontrado = crate::conectores::buscar_ejecutable(
        "claude",
        &path,
        std::ffi::OsStr::new(".EXE;.CMD;.PS1"),
    );

    assert_eq!(encontrado, Some(carpeta.join("claude.CMD")));
    std::fs::remove_dir_all(carpeta).expect("limpiar PATHEXT");
}

/// El lanzador se verifica mediante el contrato inyectable, sin abrir una ventana real.
#[test]
fn el_ejecutor_recibe_la_orden_estructurada_sin_una_shell() {
    use crate::lanzador_agentes::{
        ConsolaDelSistema, EjecutorDeConsola, OrdenCli, ResultadoLanzamiento,
    };
    use std::cell::RefCell;

    struct EjecutorFalso {
        recibida: RefCell<Option<OrdenCli>>,
    }
    impl EjecutorDeConsola for EjecutorFalso {
        fn abrir(&self, orden: &OrdenCli) -> crate::error::AppResult<ResultadoLanzamiento> {
            self.recibida.replace(Some(orden.clone()));
            Ok(ResultadoLanzamiento { pid: 4242 })
        }
    }

    let (raiz, orden) =
        orden_cli_de_prueba(crate::conectores::IdAgente::CodexCli, "ejecutor-falso");
    let ejecutor = EjecutorFalso {
        recibida: RefCell::new(None),
    };
    let resultado = ejecutor.abrir(&orden).expect("lanzamiento simulado");
    assert_eq!(resultado.pid, 4242);
    assert_eq!(ejecutor.recibida.into_inner(), Some(orden));
    let _ejecutor_real = ConsolaDelSistema;
    std::fs::remove_dir_all(raiz).expect("limpiar ejecutor");
}

