/// Agente con una consola simulada para preparar la vista previa sin abrir procesos.
fn agente_cli_para_vista_previa(ejecutable: std::path::PathBuf) -> crate::conectores::Agente {
    let mut agente = agente_de_prueba(
        "agente-vista-previa.json",
        crate::conectores::FormatoConfiguracion::Json,
    );
    agente.cli = Some(crate::conectores::CapacidadCli { ejecutable });
    agente
}

/// Un programa guardado dentro del proyecto podría ser sustituido por el propio agente. MMCelt
/// debe negarse a confiar en él antes de mostrar la vista previa.
#[test]
fn un_ejecutable_dentro_del_proyecto_se_rechaza() {
    let raiz = carpeta_temporal_contexto("ejecutable-dentro-proyecto");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    let ejecutable = raiz.join("claude.exe");
    std::fs::write(&ejecutable, "simulado").expect("crear ejecutable dentro del proyecto");
    let agente = agente_cli_para_vista_previa(ejecutable);

    let resultado = crate::lanzador_agentes::confirmar_ejecutable(&agente, &raiz);

    assert!(matches!(
        resultado,
        Err(crate::error::AppError::CarpetaProyectoInvalida { .. })
    ));
    std::fs::remove_dir_all(raiz).expect("limpiar prueba de confianza");
}

/// Adaptador auxiliar para las pruebas de interfaz que ejercitan la preparación del envío a agentes.
fn preparar_envio_para_prueba(
    app: &mut crate::AplicacionMapaMental,
    agente: &crate::conectores::Agente,
) -> crate::error::AppResult<()> {
    let idioma = app.idioma();
    let es_solo_lectura = app.es_solo_lectura_por_raiz();
    let editor_ia = app.presentacion.editor_proyecto_ia().clone();
    let res = crate::envio_agente_comando::preparar_envio(
        &mut app.agentes,
        agente,
        &app.mapa.proyecto,
        idioma,
        es_solo_lectura,
        editor_ia.as_ref(),
    );
    if let Err(crate::error::AppError::CarpetaProyectoInvalida {
        motivo: crate::error::MotivoCarpetaInvalida::MapaEnRaizDebeTrasladarse,
        ..
    }) = &res
    {
        app.abrir_aviso_mapa_en_raiz();
    } else if let Err(crate::error::AppError::CarpetaProyectoInvalida {
        motivo: crate::error::MotivoCarpetaInvalida::AgenteRegistradoParaOtraCarpeta,
        ..
    }) = &res
    {
        app.presentacion.ventanas.modal_conexiones = true;
    }
    res
}

/// Adaptador auxiliar para las pruebas de interfaz que confirman el envío hacia el trabajador en segundo plano.
fn iniciar_envio_confirmado_para_prueba(
    app: &mut crate::AplicacionMapaMental,
    ctx: &egui::Context,
) -> crate::error::AppResult<bool> {
    let proyecto = app.mapa.proyecto.clone();
    let ruta_actual = app.persistencia.ruta_actual.clone();
    let carpeta_sugerida = app.sugerir_carpeta_para_guardar();
    let idioma = app.idioma();
    crate::envio_agente_comando::iniciar_envio_confirmado(
        &mut app.agentes,
        &proyecto,
        ruta_actual.as_deref(),
        carpeta_sugerida.as_deref(),
        idioma,
        ctx,
    )
}

/// Adaptador auxiliar para las pruebas de interfaz que ejercitan la confirmación con ejecutor inyectado.
fn iniciar_envio_confirmado_con_para_prueba<E: crate::lanzador_agentes::EjecutorDeConsola>(
    app: &mut crate::AplicacionMapaMental,
    ctx: &egui::Context,
    ejecutor: &E,
) -> crate::error::AppResult<bool> {
    let revision = app.mapa.proyecto.revision();
    let ruta_actual = app.persistencia.ruta_actual.clone();
    let idioma = app.idioma();
    let proyecto = app.mapa.proyecto.clone();
    let servicios = app.servicios().clone();
    let servicios_exp = servicios.clone();
    let proyecto_exp = proyecto.clone();
    let mut persistencia_envio = crate::envio_agente_comando::PersistenciaEnvioAplicacion::nuevo(
        move || {
            let ruta = ruta_actual.as_ref()?.clone();
            servicios.guardar(&proyecto, &ruta).ok()?;
            Some(ruta)
        },
        move |ruta_markdown| servicios_exp.exportar(&proyecto_exp, ruta_markdown, idioma),
    );
    crate::envio_agente_comando::iniciar_envio_confirmado_con(
        &mut app.agentes,
        &mut app.persistencia,
        revision,
        ctx,
        ejecutor,
        &mut persistencia_envio,
    )
}

/// La confirmación muestra la ruta canónica exacta, no el nombre ni la ruta provisional que
/// devolvió `PATH`.
#[test]
fn el_ejecutable_del_agente_se_muestra_antes_de_abrirlo() {
    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("ejecutable-visible");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    app.agentes.espacio_de_trabajo = raiz.clone();
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");
    let ruta_canonica = ejecutable
        .canonicalize()
        .expect("resolver ruta canónica del ejecutable");

    preparar_envio_para_prueba(&mut app, &agente_cli_para_vista_previa(ejecutable))
        .expect("preparar vista previa");

    let textos = crate::arnes_interfaz::textos_del_modal_sesion_agente(&mut app, &ctx);
    let ruta_esperada = crate::ui::limpiar_ruta_para_interfaz(&ruta_canonica);
    assert!(
        textos.iter().any(|texto| texto == &ruta_esperada),
        "la vista previa debe mostrar la ruta canónica completa: {textos:?}"
    );
    std::fs::remove_dir_all(raiz).expect("limpiar vista previa");
}

/// Si el archivo cambia después de que el usuario haya visto su ruta, la orden ya no es válida.
#[test]
fn sustituir_el_ejecutable_tras_confirmarlo_cancela_el_lanzamiento() {
    let contenedor = carpeta_temporal_contexto("ejecutable-sustituido");
    let raiz = contenedor.join("proyecto");
    std::fs::create_dir_all(&raiz).expect("crear carpeta del proyecto");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    let ejecutable = contenedor.join("bin").join("codex.exe");
    std::fs::create_dir_all(ejecutable.parent().expect("carpeta bin"))
        .expect("crear carpeta del ejecutable");
    std::fs::write(&ejecutable, "primera versión").expect("crear ejecutable inicial");
    let agente = agente_cli_para_vista_previa(ejecutable.clone());
    let confirmado = crate::lanzador_agentes::confirmar_ejecutable(&agente, &raiz)
        .expect("confirmar ejecutable inicial");
    std::fs::write(&ejecutable, "segunda versión, con otro tamaño").expect("sustituir ejecutable");
    let crate::proyecto_trabajo::CargaProyecto::Confirmado(contexto) =
        crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
            .expect("abrir proyecto")
    else {
        panic!("el proyecto debe permanecer confirmado")
    };
    let mut borrador = borrador_de_sesion("reglas", "contexto", "probar identidad");
    borrador.agente = crate::conectores::IdAgente::CodexCli;
    std::fs::write(raiz.join("mapa.mmcelt"), "mapa").expect("crear mapa de prueba");
    let prompt = prompt_de_sesion(&borrador);
    let sesion = crate::sesiones_agentes::preparar_sesion(
        &contexto,
        std::path::Path::new("mapa.mmcelt"),
        &prompt,
    )
    .expect("preparar expediente");

    let resultado = crate::lanzador_agentes::orden_para(
        crate::conectores::IdAgente::CodexCli,
        confirmado,
        &contexto,
        &sesion,
    );

    assert!(resultado.is_err(), "un archivo sustituido no debe lanzarse");
    std::fs::remove_dir_all(contenedor).expect("limpiar ejecutable sustituido");
}

