/// Criterios 1, 3, 4 y 5: Encargo y reglas persisten en disco por carpeta al cerrar «Proyecto e instrucciones»,
/// sobreviven al reinicio completo de la aplicación y alimentan de forma idéntica a «Enviar a un agente».
#[test]
fn el_encargo_y_las_reglas_persisten_en_disco_al_cerrar_proyecto_e_instrucciones_y_se_recuperan_tras_reiniciar(
) {
    use crate::ui::proyecto_ia_modal::{
        aplicar_accion_para_prueba, cargar_editor_para_prueba, AccionProyectoIa,
        EstadoEditorProyectoIa, PestanaProyectoIa,
    };

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("persistencia-encargo-reglas");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    app.agentes.espacio_de_trabajo = raiz.clone();
    let raiz_canonica = std::fs::canonicalize(&raiz).expect("canonizar proyecto");

    let ruta_mapa = raiz.join("mapa_prueba.mmcelt");
    app.persistencia.ruta_actual = Some(ruta_mapa.clone());
    crate::storage::guardar_proyecto_en_archivo(&app.mapa.proyecto, &ruta_mapa)
        .expect("guardar mapa inicial");

    let mut editor = EstadoEditorProyectoIa {
        raiz_proyecto: raiz_canonica.clone(),
        pestana: PestanaProyectoIa::Proyecto,
        reglas: "REGLAS PERSISTIDAS EN DISCO".to_owned(),
        encargo: "ENCARGO PERSISTIDO EN DISCO".to_owned(),
        idioma_documento: Idioma::Ingles,
        fuentes: Vec::new(),
        indice_plantilla_seleccionada: 0,
        nombre_nueva_plantilla: String::new(),
    };

    app.mapa.proyecto.creator_vision = "Visión modificada para persistencia".to_owned();

    let conservar = aplicar_accion_para_prueba(
        &mut app,
        &mut editor,
        AccionProyectoIa::Cerrar,
        Idioma::Espanol,
    );
    assert!(!conservar, "cerrar debe retirar el editor visual");

    // 1. Comprobación directa sobre archivos en disco
    let ruta_config = raiz.join(".mmcelt/configuracion-agente.json");
    assert!(
        ruta_config.exists(),
        "la configuración del agente debe existir en disco tras cerrar"
    );
    let texto_config =
        std::fs::read_to_string(&ruta_config).expect("leer configuracion-agente.json");
    assert!(
        texto_config.contains("ENCARGO PERSISTIDO EN DISCO"),
        "configuracion-agente.json debe contener el encargo persistido"
    );

    let ruta_reglas = raiz.join(".mmcelt/instrucciones-agente.md");
    assert!(
        ruta_reglas.exists(),
        "las reglas comunes deben existir en disco tras cerrar"
    );
    let texto_reglas = std::fs::read_to_string(&ruta_reglas).expect("leer instrucciones-agente.md");
    assert_eq!(
        texto_reglas, "REGLAS PERSISTIDAS EN DISCO",
        "instrucciones-agente.md debe contener las reglas persistidas"
    );

    let mapa_en_disco =
        crate::storage::cargar_proyecto_de_archivo(&ruta_mapa).expect("recargar mapa");
    assert_eq!(
        mapa_en_disco.creator_vision, "Visión modificada para persistencia",
        "el mapa debe haberse guardado en disco al cerrar"
    );

    // 2. Comprobación tras REINICIO COMPLETO de la aplicación
    let (mut app2, _ctx2) = crate::arnes_interfaz::aplicacion_de_prueba();
    app2.agentes.espacio_de_trabajo = raiz.clone();
    let reabierto = cargar_editor_para_prueba(&app2).expect("reabrir editor en app2");
    assert_eq!(
        reabierto.encargo, "ENCARGO PERSISTIDO EN DISCO",
        "el encargo debe recuperarse del disco en una instancia limpia"
    );
    assert_eq!(
        reabierto.reglas, "REGLAS PERSISTIDAS EN DISCO",
        "las reglas deben recuperarse del disco en una instancia limpia"
    );
    assert_eq!(
        reabierto.idioma_documento,
        Idioma::Ingles,
        "el idioma del documento debe recuperarse del disco"
    );

    // 3. Comprobación de copia única: «Enviar a un agente» ve exactamente el mismo encargo y reglas
    let ejecutable = std::env::current_exe().expect("localizar ejecutable");
    preparar_envio_para_prueba(&mut app2, &agente_cli_para_vista_previa(ejecutable))
        .expect("preparar envio");
    let editor_sesion = app2.agentes.editor_sesion.as_ref().expect("editor sesion");
    assert_eq!(
        editor_sesion.borrador.encargo, "ENCARGO PERSISTIDO EN DISCO",
        "el borrador de envio debe coincidir con el encargo configurado"
    );
    assert_eq!(
        editor_sesion.borrador.reglas_proyecto, "REGLAS PERSISTIDAS EN DISCO",
        "el borrador de envio debe coincidir con las reglas configuradas"
    );

    std::fs::remove_dir_all(raiz).expect("limpiar prueba");
}

/// Un encargo sin enviar pertenece a la raíz donde se preparó y no debe aparecer en otra.
#[test]
fn el_encargo_preparado_no_cruza_a_otro_proyecto() {
    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz_a = carpeta_temporal_contexto("encargo-proyecto-a");
    let raiz_b = carpeta_temporal_contexto("encargo-proyecto-b");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz_a)
        .expect("identificar proyecto A");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz_b)
        .expect("identificar proyecto B");
    app.agentes.espacio_de_trabajo = raiz_a.clone();
    let raiz_a_canonica = std::fs::canonicalize(&raiz_a).expect("canonizar proyecto A");
    app.agentes
        .conservar_encargo_preparado(raiz_a_canonica, "SOLO PARA A".to_owned());
    app.agentes.espacio_de_trabajo = raiz_b.clone();
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");

    preparar_envio_para_prueba(&mut app, &agente_cli_para_vista_previa(ejecutable))
        .expect("preparar envío para B");

    assert!(
        app.agentes
            .editor_sesion
            .as_ref()
            .expect("editor de B")
            .borrador
            .encargo
            .is_empty(),
        "el encargo de A no debe viajar al proyecto B"
    );
    std::fs::remove_dir_all(raiz_a).expect("limpiar proyecto A");
    std::fs::remove_dir_all(raiz_b).expect("limpiar proyecto B");
}

