/// La ventana de envío es 100% de solo lectura: ni reglas ni encargo son editables,
/// no admite foco de edición ni mutación por teclado, y no ofrece botones de plantillas
/// ni acciones de restaurar o guardar reglas.
#[test]
fn la_ventana_de_envio_es_totalmente_de_solo_lectura_y_no_ofrece_plantillas_ni_guardado_de_reglas()
{
    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("envio-solo-lectura");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");
    app.agentes.espacio_de_trabajo = raiz.clone();
    let raiz_canonica = std::fs::canonicalize(&raiz).expect("canonizar proyecto");
    app.agentes
        .conservar_encargo_preparado(raiz_canonica, "ENCARGO DE PRUEBA".to_owned());
    preparar_envio_para_prueba(&mut app, &agente_cli_para_vista_previa(ejecutable))
        .expect("preparar vista previa");

    let textos = crate::arnes_interfaz::textos_del_modal_sesion_agente(&mut app, &ctx);
    let idioma = app.idioma();

    // 1. Los botones de plantilla no deben estar en la ventana de envío
    for plantilla in crate::ai_export::PlantillaEncargo::TODAS {
        let titulo = plantilla.titulo_interfaz(idioma);
        assert!(
            !textos.iter().any(|t| t == titulo),
            "la ventana de envío no debe contener botones de plantilla ({titulo}): {textos:?}"
        );
        let encabezado = plantilla.encabezado_markdown(idioma);
        assert!(
            !textos.iter().any(|t| t == encabezado),
            "la ventana de envío no debe contener encabezados markdown de plantilla ({encabezado}): {textos:?}"
        );
    }

    // 2. Los botones obsoletos no deben estar en la ventana de envío
    for texto_restaurar in [
        "Restaurar esta sesión",
        "Restore this session",
        "Restaurer cette session",
        "Diese Sitzung wiederherstellen",
        "Восстановить эту сессию",
        "恢复本次会话",
    ] {
        assert!(
            !textos.iter().any(|t| t == texto_restaurar),
            "la ventana de envío no debe contener botón de restaurar ({texto_restaurar}): {textos:?}"
        );
    }
    let guardar_reglas = Texto::SesionAgenteGuardarReglas.en(idioma);
    assert!(
        !textos.iter().any(|t| t == guardar_reglas),
        "la ventana de envío no debe contener botón de guardar reglas ({guardar_reglas}): {textos:?}"
    );

    // 3. Vigilancia mecánica de no interactividad en el encargo:
    // Intentar hacer clic sobre el encargo y mecanografiar texto nuevo.
    let encargo_antes = app
        .agentes
        .editor_sesion
        .as_ref()
        .expect("editor sesion")
        .borrador
        .encargo
        .clone();
    assert_eq!(encargo_antes, "ENCARGO DE PRUEBA");

    let (encontrado_encargo, foco_encargo) =
        crate::arnes_interfaz::intentar_escribir_en_texto_visible(
            &mut app,
            crate::ui::sesion_agente_modal::dibujar_contenido_para_prueba,
            "ENCARGO DE PRUEBA",
            " MUTACION_ENCARGO",
        );
    assert!(
        encontrado_encargo,
        "el encargo debe ser visible en la ventana de envío para poder ejercitarlo"
    );
    assert!(
        !foco_encargo,
        "el campo de encargo en la ventana de envío no debe admitir foco interactivo"
    );
    let encargo_despues = app
        .agentes
        .editor_sesion
        .as_ref()
        .expect("editor sesion")
        .borrador
        .encargo
        .clone();
    assert_eq!(
        encargo_antes, encargo_despues,
        "el encargo en la ventana de envío no debe admitir escritura ni cambiar su contenido"
    );

    // 4. Vigilancia mecánica de no interactividad en las reglas:
    // Configuramos texto conocido en reglas del borrador para ejercitar el clic y teclado.
    app.agentes
        .editor_sesion
        .as_mut()
        .unwrap()
        .borrador
        .reglas_proyecto = "REGLAS_INTOCABLES_PARA_PRUEBA".to_owned();

    let (encontrado_reglas, foco_reglas) =
        crate::arnes_interfaz::intentar_escribir_en_texto_visible(
            &mut app,
            crate::ui::sesion_agente_modal::dibujar_contenido_para_prueba,
            "REGLAS_INTOCABLES_PARA_PRUEBA",
            " MUTACION_REGLAS",
        );
    assert!(
        encontrado_reglas,
        "las reglas deben ser visibles en la ventana de envío para poder ejercitarlas"
    );
    assert!(
        !foco_reglas,
        "el campo de reglas en la ventana de envío no debe admitir foco interactivo"
    );
    let reglas_despues = app
        .agentes
        .editor_sesion
        .as_ref()
        .expect("editor sesion")
        .borrador
        .reglas_proyecto
        .clone();
    assert_eq!(
        "REGLAS_INTOCABLES_PARA_PRUEBA", reglas_despues,
        "las reglas en la ventana de envío no deben admitir escritura ni cambiar su contenido"
    );

    std::fs::remove_dir_all(raiz).expect("limpiar prueba");
}

/// Si el encargo está vacío, la ventana de envío muestra aviso claro y botón de configuración en los 6 idiomas,
/// con contenido sustancial independiente y palabras clave explícitas (no tautológico).
#[test]
fn la_ventana_de_envio_muestra_aviso_y_boton_cuando_el_encargo_esta_vacio_en_los_seis_idiomas() {
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");

    // Palabras clave esperadas sustanciales e independientes por idioma (aviso, botón)
    let terminos_esperados: [(Idioma, &str, &str); 6] = [
        (Idioma::Espanol, "encargo está vacío", "Configurar encargo"),
        (Idioma::Ingles, "task is empty", "Configure task"),
        (Idioma::Frances, "mission est vide", "Configurer la mission"),
        (Idioma::Aleman, "Auftrag ist leer", "Auftrag konfigurieren"),
        (Idioma::Ruso, "Задание пусто", "Настроить задание"),
        (Idioma::ChinoSimplificado, "任务为空", "配置任务"),
    ];

    for (idioma, clave_aviso, clave_boton) in terminos_esperados {
        let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
        app.presentacion_mut().preferencias().idioma = idioma;
        let raiz = carpeta_temporal_contexto(&format!("aviso-encargo-vacio-{:?}", idioma));
        crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
            .expect("identificar proyecto");
        app.agentes.espacio_de_trabajo = raiz.clone();

        preparar_envio_para_prueba(&mut app, &agente_cli_para_vista_previa(ejecutable.clone()))
            .expect("preparar vista previa con encargo vacío");

        let textos = crate::arnes_interfaz::textos_del_modal_sesion_agente(&mut app, &ctx);
        let aviso = Texto::SesionAgenteEncargoVacioAviso.en(idioma);
        let boton = Texto::SesionAgenteBotonConfigurarEncargo.en(idioma);

        // 1. Longitud sustancial mínima (no admite traducciones vacías o mutiladas)
        assert!(
            aviso.len() >= 25,
            "el aviso en {:?} debe tener contenido sustancial (longitud {})",
            idioma,
            aviso.len()
        );
        assert!(
            boton.len() >= 5,
            "el botón en {:?} debe tener contenido sustancial (longitud {})",
            idioma,
            boton.len()
        );

        // 2. Validación sustancial de términos requeridos (no tautológica)
        assert!(
            aviso.contains(clave_aviso),
            "el aviso en {:?} debe contener '{}': {}",
            idioma,
            clave_aviso,
            aviso
        );
        assert!(
            boton.contains(clave_boton),
            "el botón en {:?} debe contener '{}': {}",
            idioma,
            clave_boton,
            boton
        );

        // 3. Presencia en la interfaz renderizada
        assert!(
            textos.iter().any(|t| t == aviso),
            "falta aviso de encargo vacío renderizado en {:?}: esperado '{}', encontrados: {:?}",
            idioma,
            aviso,
            textos
        );
        assert!(
            textos.iter().any(|t| t == boton),
            "falta botón de configurar encargo renderizado en {:?}: esperado '{}', encontrados: {:?}",
            idioma,
            boton,
            textos
        );

        std::fs::remove_dir_all(raiz).expect("limpiar prueba de aviso");
    }
}

/// Pulsar el botón de configurar encargo cuando está vacío cierra la vista previa y abre la pestaña de plantillas.
