/// Criterio 1: Escribir en la ventana de configuración alimenta de inmediato y exactamente
/// a la ventana de envío; no existen dos borradores editables independientes.
#[test]
fn escribir_en_la_ventana_de_configuracion_se_refleja_de_inmediato_y_exactamente_en_la_de_envio() {
    use crate::ui::proyecto_ia_modal::{AccionProyectoIa, PestanaProyectoIa};

    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("copia-unica-ventanas");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");
    app.agentes.espacio_de_trabajo = raiz.clone();

    // 1. El usuario abre «Proyecto e instrucciones» y escribe encargo y reglas
    app.abrir_proyecto_ia_en_pestana(PestanaProyectoIa::Plantillas);
    {
        let editor = app
            .presentacion_mut()
            .editor_proyecto_ia()
            .as_mut()
            .expect("editor de configuración");
        editor.encargo = "ENCARGO EXACTO DESDE CONFIGURACIÓN".to_string();
        editor.reglas = "REGLAS EXACTAS DESDE CONFIGURACIÓN".to_string();
    }

    // 2. Sin cerrar la ventana o cerrándola, la ventana de envío toma exactamente ese contenido
    preparar_envio_para_prueba(&mut app, &agente_cli_para_vista_previa(ejecutable.clone()))
        .expect("preparar envío con configuración viva");
    {
        let sesion = app.agentes.editor_sesion.as_ref().expect("editor sesión");
        assert_eq!(
            sesion.borrador.encargo, "ENCARGO EXACTO DESDE CONFIGURACIÓN",
            "la ventana de envío debe mostrar exactamente el encargo de la ventana de configuración"
        );
        assert_eq!(
            sesion.borrador.reglas_proyecto, "REGLAS EXACTAS DESDE CONFIGURACIÓN",
            "la ventana de envío debe mostrar exactamente las reglas de la ventana de configuración"
        );
    }

    // Comprobamos en los textos visuales que la ventana de envío muestra ese encargo exacto
    let textos = crate::arnes_interfaz::textos_del_modal_sesion_agente(&mut app, &ctx);
    assert!(
        textos
            .iter()
            .any(|t| t.contains("ENCARGO EXACTO DESDE CONFIGURACIÓN")),
        "el texto visual de la ventana de envío debe reflejar el encargo: {textos:?}"
    );

    // 3. Al cerrar la ventana de configuración, persiste en disco
    let mut editor_ia = app
        .presentacion_mut()
        .editor_proyecto_ia()
        .take()
        .expect("tomar editor para cerrar");
    crate::ui::proyecto_ia_modal::aplicar_accion_para_prueba(
        &mut app,
        &mut editor_ia,
        AccionProyectoIa::Cerrar,
        Idioma::Espanol,
    );

    // 4. Se reinicia MMCelt en una nueva instancia fría sobre la misma carpeta
    let (mut app2, _ctx2) = crate::arnes_interfaz::aplicacion_de_prueba();
    app2.agentes.espacio_de_trabajo = raiz.clone();
    preparar_envio_para_prueba(&mut app2, &agente_cli_para_vista_previa(ejecutable))
        .expect("preparar envío tras reiniciar");
    {
        let sesion2 = app2
            .agentes
            .editor_sesion
            .as_ref()
            .expect("editor sesión app2");
        assert_eq!(
            sesion2.borrador.encargo, "ENCARGO EXACTO DESDE CONFIGURACIÓN",
            "tras reiniciar, la ventana de envío recupera exactamente el encargo configurado"
        );
        assert_eq!(
            sesion2.borrador.reglas_proyecto, "REGLAS EXACTAS DESDE CONFIGURACIÓN",
            "tras reiniciar, la ventana de envío recupera exactamente las reglas configuradas"
        );
    }

    std::fs::remove_dir_all(raiz).expect("limpiar prueba");
}

/// Sin fuentes nativas, la pestaña explica qué falta y dónde debe crearlo la persona.
#[test]
fn instrucciones_sin_fuentes_muestran_estado_vacio_y_raiz_exacta() {
    use crate::ui::proyecto_ia_modal::PestanaProyectoIa;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("estado-vacio-fuentes");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    // Se canoniza antes de asignar, igual que hace el único punto de verdad del dominio
    // (`sincronizar_espacio_de_trabajo_con_el_mapa`, A-2): en entornos donde la ruta cruda no
    // coincide con la canónica —nombres cortos 8.3 de Windows, `/var` symlink de macOS—, asignar
    // la ruta cruda rompería la invariante que toda pantalla da por hecha.
    let raiz_canonica = std::fs::canonicalize(&raiz).expect("canonizar raíz esperada");
    app.agentes.espacio_de_trabajo = raiz_canonica.clone();
    let mut editor = crate::ui::proyecto_ia_modal::cargar_editor_para_prueba(&app)
        .expect("detectar realmente la ausencia de fuentes");
    editor.pestana = PestanaProyectoIa::Instrucciones;
    assert!(
        editor.fuentes.is_empty(),
        "la carpeta controlada no tiene fuentes"
    );

    let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
        crate::ui::proyecto_ia_modal::dibujar_contenido_para_prueba(
            app,
            &mut editor,
            Idioma::Espanol,
            ui,
        );
    });

    assert!(
        textos
            .iter()
            .any(|texto| texto.contains("No se han encontrado archivos de instrucciones nativas")),
        "falta explicar el estado sin fuentes: {textos:?}"
    );
    for nombre in crate::sesiones_agentes::NOMBRES_FUENTES_NATIVAS {
        assert!(
            textos.iter().any(|texto| texto.contains(nombre)),
            "falta mostrar el nombre admitido {nombre}: {textos:?}"
        );
    }
    let raiz_esperada = crate::ui::limpiar_ruta_para_interfaz(&raiz_canonica);
    assert!(
        textos.iter().any(|texto| texto.contains(&raiz_esperada)),
        "falta mostrar la raíz exacta de las fuentes: {textos:?}"
    );
    std::fs::remove_dir_all(raiz).expect("limpiar estado vacío de fuentes");
}

/// La pestaña de instrucciones muestra siempre la carpeta de trabajo del proyecto y su
/// explicación en los seis idiomas, incluso cuando ya existen fuentes nativas detectadas.
#[test]
fn instrucciones_muestran_carpeta_de_trabajo_y_explicacion_incluso_con_fuentes_presentes() {
    use crate::ui::proyecto_ia_modal::PestanaProyectoIa;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("carpeta-trabajo-con-fuentes");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    std::fs::write(raiz.join("AGENTS.md"), "# Reglas").expect("crear fuente nativa");
    // Se canoniza antes de asignar: mismo motivo que en la prueba anterior (A-2).
    let raiz_canonica = std::fs::canonicalize(&raiz).expect("canonizar raíz esperada");
    app.agentes.espacio_de_trabajo = raiz_canonica.clone();
    let mut editor = crate::ui::proyecto_ia_modal::cargar_editor_para_prueba(&app)
        .expect("detectar fuentes existentes");
    editor.pestana = PestanaProyectoIa::Instrucciones;
    assert!(
        !editor.fuentes.is_empty(),
        "la carpeta debe contener al menos una fuente nativa"
    );
    let raiz_esperada = crate::ui::limpiar_ruta_para_interfaz(&raiz_canonica);

    for idioma in Idioma::TODOS {
        let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
            crate::ui::proyecto_ia_modal::dibujar_contenido_para_prueba(
                app,
                &mut editor,
                idioma,
                ui,
            );
        });

        assert!(
            textos
                .iter()
                .any(|texto| texto.contains(Texto::ProyectoIaCarpetaTrabajo.en(idioma))),
            "falta rótulo de carpeta de trabajo en {idioma:?}: {textos:?}"
        );
        assert!(
            textos
                .iter()
                .any(|texto| texto.contains(Texto::ProyectoIaExplicacionCarpetaTrabajo.en(idioma))),
            "falta explicación de carpeta de trabajo en {idioma:?}: {textos:?}"
        );
        assert!(
            textos
                .iter()
                .any(|texto| texto.contains(&raiz_esperada)),
            "la raíz de trabajo debe ser visible incluso con fuentes presentes en {idioma:?}: {textos:?}"
        );
    }

    std::fs::remove_dir_all(raiz).expect("limpiar carpeta de prueba");
}

/// Las pestañas con contenido de longitud libre (Proyecto, Instrucciones y Vista completa)
/// deben contener su contenido dentro de un `ScrollArea`, de modo que un texto masivo
/// (reglas, fuentes nativas extensas o historial) no desborde la altura asignada ni expulse
/// los controles de la ventana.
#[test]
fn pestanas_con_contenido_libre_estan_contenidas_en_un_scroll_area() {
    use crate::ui::proyecto_ia_modal::PestanaProyectoIa;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("pestanas-contenido-libre-scroll");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");

    let contenido_extenso = (0..200)
        .map(|i| format!("Línea de regla libre {i}: no asumir hechos sin prueba verificable.\n"))
        .collect::<String>();
    std::fs::write(raiz.join("AGENTS.md"), &contenido_extenso).expect("crear fuente nativa masiva");
    app.agentes.espacio_de_trabajo = raiz.clone();

    let mut editor = crate::ui::proyecto_ia_modal::cargar_editor_para_prueba(&app)
        .expect("cargar editor con fuentes extensas");
    editor.reglas = contenido_extenso.clone();
    editor.encargo = contenido_extenso.clone();
    if let Some(fuente) = editor.fuentes.first_mut() {
        fuente.contenido_anterior = Some(contenido_extenso.clone());
    }

    for pestana in PestanaProyectoIa::TODAS {
        editor.pestana = pestana;
        let mut altura_consumida = 0.0;
        let altura_disponible_limite = 400.0;

        let ctx = egui::Context::default();
        let entrada = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(800.0, 600.0),
            )),
            ..Default::default()
        };
        let mut salida = ctx.run_ui(entrada, |ui| {
            ui.allocate_ui_with_layout(
                egui::vec2(760.0, altura_disponible_limite),
                egui::Layout::top_down(egui::Align::Min),
                |ui| {
                    crate::ui::proyecto_ia_modal::dibujar_contenido_para_prueba(
                        &mut app,
                        &mut editor,
                        Idioma::Espanol,
                        ui,
                    );
                    altura_consumida = ui.min_rect().height();
                },
            );
        });
        salida.textures_delta.clear();

        assert!(
            altura_consumida <= altura_disponible_limite + 50.0,
            "la pestaña {pestana:?} desbordó la altura asignada ({altura_consumida} > {altura_disponible_limite}): falta ScrollArea para contener su longitud libre"
        );
    }

    std::fs::remove_dir_all(raiz).expect("limpiar carpeta de prueba");
}

/// Las rutas mostradas en la interfaz nunca deben filtrar prefijos técnicos del sistema
/// operativo (como `\\?\` o `\\?\UNC\` de Windows) hacia las etiquetas o campos de texto.
#[test]
fn rutas_en_interfaz_no_filtran_prefijo_verbatim_de_windows() {
    use crate::ui::proyecto_ia_modal::PestanaProyectoIa;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("rutas-sin-prefijo-verbatim");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    std::fs::write(raiz.join("AGENTS.md"), "# Reglas").expect("crear fuente nativa");
    app.agentes.espacio_de_trabajo = raiz.clone();

    let mut editor = crate::ui::proyecto_ia_modal::cargar_editor_para_prueba(&app)
        .expect("cargar editor para prueba de rutas");
    editor.pestana = PestanaProyectoIa::Instrucciones;

    for idioma in Idioma::TODOS {
        let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
            crate::ui::proyecto_ia_modal::dibujar_contenido_para_prueba(
                app,
                &mut editor,
                idioma,
                ui,
            );
        });

        assert!(
            !textos.iter().any(|t| t.contains(r"\\?\")),
            "se filtró el prefijo verbatim \\\\?\\ en los textos de Instrucciones ({idioma:?}): {textos:?}"
        );
    }

    let ejecutable = std::env::current_exe().expect("localizar ejecutable");
    let raiz_canonica = std::fs::canonicalize(&raiz).expect("canonizar");
    app.agentes
        .conservar_encargo_preparado(raiz_canonica, "Prueba rutas".to_owned());
    preparar_envio_para_prueba(&mut app, &agente_cli_para_vista_previa(ejecutable))
        .expect("preparar envío");

    let textos_sesion = crate::arnes_interfaz::textos_del_modal_sesion_agente(&mut app, &_ctx);
    assert!(
        !textos_sesion.iter().any(|t| t.contains(r"\\?\")),
        "se filtró el prefijo verbatim \\\\?\\ en los textos de sesión de agente: {textos_sesion:?}"
    );

    std::fs::remove_dir_all(raiz).expect("limpiar carpeta de prueba");
}

/// La etiqueta de estado para una fuente recién detectada debe aclarar en los seis idiomas
/// que se encuentra pendiente de aceptación por la persona antes de surtir efecto.
#[test]
fn estado_fuente_nueva_indica_pendiente_de_aceptar_en_todos_los_idiomas() {
    for idioma in Idioma::TODOS {
        let texto = Texto::ProyectoIaFuenteNueva.en(idioma);
        assert!(
            (texto.contains('(') && texto.contains(')'))
                || (texto.contains('（') && texto.contains('）')),
            "el texto de fuente nueva en {idioma:?} no contiene la aclaración entre paréntesis: '{texto}'"
        );
    }
}

/// Si la persona cambia de mapa (o de espacio de trabajo) mientras la ventana de
/// «Proyecto e instrucciones para la IA» permanece abierta, el editor no debe conservar
/// la raíz ni el contenido del mapa anterior. La ventana debe sincronizar la raíz activa,
/// mostrar la nueva carpeta y dirigir cualquier guardado o consentimiento al proyecto en curso.
#[test]
fn modal_proyecto_ia_sincroniza_editor_si_cambia_el_espacio_de_trabajo() {
    use crate::ui::proyecto_ia_modal::PestanaProyectoIa;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz_a = carpeta_temporal_contexto("modal-sincroniza-espacio-a");
    let raiz_b = carpeta_temporal_contexto("modal-sincroniza-espacio-b");
    std::fs::write(raiz_a.join("AGENTS.md"), "FUENTE NATIVA A").expect("crear fuente nativa A");
    std::fs::write(raiz_b.join("AGENTS.md"), "FUENTE NATIVA B").expect("crear fuente nativa B");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz_a)
        .expect("identificar proyecto A");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz_b)
        .expect("identificar proyecto B");
    let contexto_a =
        crate::proyecto_trabajo::RepositorioProyecto::contexto_para_vista_previa(&raiz_a)
            .expect("contexto A");
    let contexto_b =
        crate::proyecto_trabajo::RepositorioProyecto::contexto_para_vista_previa(&raiz_b)
            .expect("contexto B");

    crate::sesiones_agentes::guardar_reglas_comunes(&contexto_a, "REGLAS PROYECTO A")
        .expect("guardar reglas A");
    crate::sesiones_agentes::guardar_reglas_comunes(&contexto_b, "REGLAS PROYECTO B")
        .expect("guardar reglas B");

    let raiz_a_canonica = std::fs::canonicalize(&raiz_a).expect("canonizar A");
    let raiz_b_canonica = std::fs::canonicalize(&raiz_b).expect("canonizar B");

    // 1. Abrir con el proyecto A y pasar a la pestaña de Instrucciones
    // Se asigna la ruta ya canonizada: es lo que hace el único punto de verdad del dominio
    // (`sincronizar_espacio_de_trabajo_con_el_mapa`, A-2) antes de que cualquier pantalla la lea.
    app.agentes.espacio_de_trabajo = raiz_a_canonica.clone();
    app.presentacion_mut().ventanas().modal_datos_del_proyecto = true;

    // Dibujar el primer fotograma: se inicializa el editor para A
    let _ = crate::arnes_interfaz::textos_de_ventana_en_pantalla(
        &mut app,
        egui::vec2(1024.0, 768.0),
        crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia,
    );

    let editor_inicial = app
        .presentacion_mut()
        .editor_proyecto_ia()
        .as_mut()
        .expect("el editor debe estar inicializado para A");
    assert_eq!(
        editor_inicial.raiz_proyecto, raiz_a_canonica,
        "el editor inicial debe pertenecer al proyecto A"
    );
    assert_eq!(
        editor_inicial.reglas, "REGLAS PROYECTO A",
        "el editor inicial debe contener las reglas de A"
    );
    // La persona está mirando la pestaña Instrucciones y redacta un encargo para A
    editor_inicial.pestana = PestanaProyectoIa::Instrucciones;
    editor_inicial.encargo = "ENCARGO PARA A".to_string();

    // 2. Simular apertura de otro mapa desde la barra (el espacio de trabajo pasa a B)
    // mientras la ventana «Proyecto e instrucciones» sigue abierta
    app.agentes.espacio_de_trabajo = raiz_b_canonica.clone();

    // Dibujar el siguiente fotograma
    let textos_b = crate::arnes_interfaz::textos_de_ventana_en_pantalla(
        &mut app,
        egui::vec2(1024.0, 768.0),
        crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia,
    );

    let (
        raiz_b_editor,
        reglas_b_editor,
        encargo_b_editor,
        pestana_b_editor,
        mut editor_para_guardar,
    ) = {
        let ed = app
            .presentacion_mut()
            .editor_proyecto_ia()
            .as_ref()
            .expect("el editor debe existir tras el segundo fotograma");
        (
            ed.raiz_proyecto.clone(),
            ed.reglas.clone(),
            ed.encargo.clone(),
            ed.pestana,
            ed.clone(),
        )
    };

    // ESTA ES LA BARRERA: el editor DEBE haber cambiado a B, no quedarse en A
    assert_eq!(
        raiz_b_editor, raiz_b_canonica,
        "el editor en memoria debe sincronizarse a la raíz del proyecto B y no quedarse en A"
    );
    assert_eq!(
        reglas_b_editor, "REGLAS PROYECTO B",
        "el editor debe mostrar las reglas del proyecto B tras el cambio de espacio"
    );
    assert_eq!(
        encargo_b_editor, "",
        "el encargo redactado para A no debe filtrarse al editor de B"
    );
    assert_eq!(
        pestana_b_editor,
        PestanaProyectoIa::Instrucciones,
        "la pestaña activa debe preservarse al sincronizar con el nuevo proyecto"
    );

    // Comprobar que en pantalla se muestra la ruta de B y no la de A
    let ruta_a_limpia = crate::ui::limpiar_ruta_para_interfaz(&raiz_a_canonica);
    let ruta_b_limpia = crate::ui::limpiar_ruta_para_interfaz(&raiz_b_canonica);
    assert!(
        !textos_b.iter().any(|t| t.contains(&ruta_a_limpia)),
        "la ventana abierta sigue mostrando la ruta del proyecto anterior A ({ruta_a_limpia}) tras cambiar a B"
    );
    assert!(
        textos_b.iter().any(|t| t.contains(&ruta_b_limpia)),
        "la ventana abierta no muestra la ruta del nuevo proyecto B ({ruta_b_limpia})"
    );

    // Modificar reglas en B y guardarlas
    editor_para_guardar.reglas = "REGLAS ACTUALIZADAS PARA B".to_string();
    // Fuerza una divergencia defensiva: la acción debe seguir la raíz B mostrada por el editor,
    // nunca otro espacio vivo que pudiera cambiar antes de aplicar el efecto.
    app.agentes.espacio_de_trabajo = raiz_a.clone();
    let _ = crate::ui::proyecto_ia_modal::aplicar_accion_para_prueba(
        &mut app,
        &mut editor_para_guardar,
        crate::ui::proyecto_ia_modal::AccionProyectoIa::GuardarReglas,
        Idioma::Espanol,
    );

    // Verificar en disco: B recibió las nuevas reglas, A no fue tocado
    assert_eq!(
        crate::sesiones_agentes::cargar_reglas_comunes(&contexto_b).expect("leer reglas B"),
        "REGLAS ACTUALIZADAS PARA B",
        "guardar reglas debe escribir en el proyecto B mostrado por el editor"
    );
    assert_eq!(
        crate::sesiones_agentes::cargar_reglas_comunes(&contexto_a).expect("leer reglas A"),
        "REGLAS PROYECTO A",
        "las reglas del proyecto A no deben ser alteradas"
    );

    let _ = crate::ui::proyecto_ia_modal::aplicar_accion_para_prueba(
        &mut app,
        &mut editor_para_guardar,
        crate::ui::proyecto_ia_modal::AccionProyectoIa::AceptarFuente("AGENTS.md".to_owned()),
        Idioma::Espanol,
    );
    let fuente_a = crate::sesiones_agentes::detectar_fuentes_nativas(&contexto_a)
        .expect("revisar fuente A")
        .into_iter()
        .find(|fuente| fuente.nombre == "AGENTS.md")
        .expect("fuente A detectada");
    let fuente_b = crate::sesiones_agentes::detectar_fuentes_nativas(&contexto_b)
        .expect("revisar fuente B")
        .into_iter()
        .find(|fuente| fuente.nombre == "AGENTS.md")
        .expect("fuente B detectada");
    assert!(!fuente_a.incorporada, "no se debe consentir la fuente de A");
    assert!(
        fuente_b.incorporada,
        "se debe consentir la fuente B que muestra el editor"
    );

    // 3. Volver al proyecto A: comprobar que el encargo original de A se restaura
    app.agentes.espacio_de_trabajo = raiz_a.clone();
    let _ = crate::arnes_interfaz::textos_de_ventana_en_pantalla(
        &mut app,
        egui::vec2(1024.0, 768.0),
        crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia,
    );

    let editor_vuelta_a = app
        .presentacion_mut()
        .editor_proyecto_ia()
        .as_ref()
        .expect("editor de vuelta a A");
    assert_eq!(
        editor_vuelta_a.raiz_proyecto, raiz_a_canonica,
        "el editor debe volver a sincronizarse con A"
    );
    assert_eq!(
        editor_vuelta_a.encargo, "ENCARGO PARA A",
        "el encargo preparado para A debe haberse conservado y restaurado"
    );

    std::fs::remove_dir_all(raiz_a).expect("limpiar carpeta A");
    std::fs::remove_dir_all(raiz_b).expect("limpiar carpeta B");
}

/// Los controles generales (idioma del documento y guardar como reglas comunes)
/// residen en el pie común de la ventana y son visibles desde las cuatro pestañas.
#[test]
fn controles_generales_de_idioma_y_reglas_visibles_en_las_cuatro_pestanas() {
    use crate::ui::proyecto_ia_modal::{EstadoEditorProyectoIa, PestanaProyectoIa};

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("controles-generales-pie-comun");
    let mut editor = EstadoEditorProyectoIa {
        raiz_proyecto: std::fs::canonicalize(&raiz).unwrap_or_else(|_| raiz.clone()),
        pestana: PestanaProyectoIa::Proyecto,
        reglas: "REGLAS".to_string(),
        encargo: "ENCARGO".to_string(),
        idioma_documento: Idioma::Espanol,
        fuentes: Vec::new(),
        indice_plantilla_seleccionada: 0,
        nombre_nueva_plantilla: String::new(),
    };

    let controles_generales_exigidos = [
        Texto::ProyectoIaIdiomaDocumento,
        Texto::SesionAgenteGuardarReglas,
        Texto::BotonCerrar,
    ];

    for idioma in [Idioma::Espanol, Idioma::Ingles] {
        for pestana in PestanaProyectoIa::TODAS {
            editor.pestana = pestana;
            let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
                crate::ui::proyecto_ia_modal::dibujar_contenido_para_prueba(
                    app,
                    &mut editor,
                    idioma,
                    ui,
                );
            });

            for texto_esperado in &controles_generales_exigidos {
                let rotulo = texto_esperado.en(idioma);
                assert!(
                    textos.iter().any(|t| t.contains(rotulo)),
                    "el control general «{rotulo}» debe ser visible en el pie común desde la pestaña {pestana:?} en {idioma:?}: {textos:?}"
                );
            }
        }
    }

    let _ = std::fs::remove_dir_all(raiz);
}

/// Cambiar el idioma del documento en el editor genera una acción semántica que persiste
/// inmediatamente la preferencia en disco sin depender de «Guardar reglas», y el idioma
/// se conserva intacto tras cerrar y reabrir la ventana.
#[test]
fn cambio_de_idioma_persiste_inmediatamente_sin_guardar_reglas_y_sobrevive_al_cierre() {
    use crate::ui::proyecto_ia_modal::cargar_editor_para_prueba;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("cambio-idioma-persiste-inmediato");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("inicializar proyecto");
    let contexto = crate::proyecto_trabajo::RepositorioProyecto::contexto_para_vista_previa(&raiz)
        .expect("contexto del proyecto");

    app.agentes.espacio_de_trabajo = raiz.clone();

    // 1. Cargar el editor: por defecto el idioma es el de la aplicación (Español)
    let editor = cargar_editor_para_prueba(&app).expect("cargar editor");
    assert_eq!(editor.idioma_documento, Idioma::Espanol);

    // Comprobar que en disco todavía no hay idioma guardado
    let config_inicial =
        crate::configuracion_agente_proyecto::cargar_configuracion(&contexto).expect("config");
    assert_eq!(config_inicial.idioma_documento, None);

    // 2. Cambiar idioma a Francés a través de la interfaz (desplegable en el pie común)
    let ctx = egui::Context::default();
    let tamano = egui::vec2(1024.0, 768.0);
    app.presentacion_mut().ventanas().modal_datos_del_proyecto = true;

    fn buscar_posicion_en_formas(
        forma: &egui::Shape,
        texto_buscado: &str,
        encontrado: &mut Option<egui::Pos2>,
    ) {
        if encontrado.is_some() {
            return;
        }
        match forma {
            egui::Shape::Text(texto) => {
                if texto.galley.text().contains(texto_buscado) {
                    let rect = texto.galley.rect.translate(texto.pos.to_vec2());
                    *encontrado = Some(rect.center());
                }
            }
            egui::Shape::Vec(formas) => {
                for f in formas {
                    buscar_posicion_en_formas(f, texto_buscado, encontrado);
                }
            }
            _ => {}
        }
    }

    // Pases de inicialización: egui::Window requiere dos pases para medir y posicionar el contenido
    for _ in 0..2 {
        let entrada = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, tamano)),
            ..Default::default()
        };
        ctx.begin_pass(entrada);
        crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia(&mut app, &ctx);
        let mut salida = ctx.end_pass();
        salida.textures_delta.clear();
    }

    // Fotograma para localizar el selector en pantalla
    let entrada_localizar = egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, tamano)),
        ..Default::default()
    };
    ctx.begin_pass(entrada_localizar);
    crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia(&mut app, &ctx);
    let mut salida1 = ctx.end_pass();
    salida1.textures_delta.clear();

    let mut pos_combo = None;
    for forma in &salida1.shapes {
        buscar_posicion_en_formas(&forma.shape, "Español", &mut pos_combo);
    }
    let pos_combo = pos_combo.expect("encontrar selector de idioma 'Español' en el pie común");

    // Fotograma 2: hacer clic sobre el desplegable para abrirlo
    let entrada_clic_combo = egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, tamano)),
        events: vec![
            egui::Event::PointerMoved(pos_combo),
            egui::Event::PointerButton {
                pos: pos_combo,
                button: egui::PointerButton::Primary,
                pressed: true,
                modifiers: egui::Modifiers::default(),
            },
            egui::Event::PointerButton {
                pos: pos_combo,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::default(),
            },
        ],
        ..Default::default()
    };
    ctx.begin_pass(entrada_clic_combo);
    crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia(&mut app, &ctx);
    let mut salida2 = ctx.end_pass();
    salida2.textures_delta.clear();

    // Fotograma 3: medir en el siguiente fotograma para que el menú emergente se presente
    let entrada_medir = egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, tamano)),
        ..Default::default()
    };
    ctx.begin_pass(entrada_medir);
    crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia(&mut app, &ctx);
    let mut salida3 = ctx.end_pass();
    salida3.textures_delta.clear();

    let mut pos_frances = None;
    for forma in &salida2.shapes {
        buscar_posicion_en_formas(&forma.shape, "Français", &mut pos_frances);
    }
    if pos_frances.is_none() {
        for forma in &salida3.shapes {
            buscar_posicion_en_formas(&forma.shape, "Français", &mut pos_frances);
        }
    }
    let pos_frances = pos_frances.expect("encontrar opción 'Français' en el desplegable");

    // Fotograma 4: hacer clic en "Français" dentro del desplegable
    let entrada_clic_frances = egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, tamano)),
        events: vec![
            egui::Event::PointerMoved(pos_frances),
            egui::Event::PointerButton {
                pos: pos_frances,
                button: egui::PointerButton::Primary,
                pressed: true,
                modifiers: egui::Modifiers::default(),
            },
            egui::Event::PointerButton {
                pos: pos_frances,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::default(),
            },
        ],
        ..Default::default()
    };
    ctx.begin_pass(entrada_clic_frances);
    crate::ui::proyecto_ia_modal::dibujar_modal_proyecto_ia(&mut app, &ctx);
    let mut salida4 = ctx.end_pass();
    salida4.textures_delta.clear();

    // 3. Comprobar que en DISCO el idioma ya está persistido como Francés sin pulsar GuardarReglas
    let config_tras_cambio = crate::configuracion_agente_proyecto::cargar_configuracion(&contexto)
        .expect("releer config");
    assert_eq!(
        config_tras_cambio.idioma_documento,
        Some(Idioma::Frances),
        "cambiar de idioma a través de la interfaz debe persistir inmediatamente en disco"
    );

    // 4. Cerrar la ventana simulando el cierre normal (apagar modal_datos_del_proyecto)
    app.presentacion_mut().ventanas().modal_datos_del_proyecto = false;
    let _ = app.presentacion_mut().editor_proyecto_ia().take();

    // 5. Reabrir la ventana: debe cargar el idioma guardado (Francés)
    let nuevo_editor = cargar_editor_para_prueba(&app).expect("reabrir editor");
    assert_eq!(
        nuevo_editor.idioma_documento,
        Idioma::Frances,
        "al reabrir el editor, debe cargarse el idioma persistido del proyecto"
    );

    let _ = std::fs::remove_dir_all(raiz);
}

