/// Un CLI registrado conserva exportación, expediente y vigilancia aunque su ejecutable no esté
/// disponible en el entorno actual.
#[test]
fn un_cli_solo_mcp_prepara_la_sesion_sin_inventar_una_consola() {
    use crate::envio_agente::EstadoEnvio;
    use crate::sesiones_agentes::EstadoLanzamiento;

    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("cli-solo-mcp");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    app.agentes.espacio_de_trabajo = raiz.clone();
    app.persistencia.ruta_actual = Some(raiz.join("plan.mmcelt"));
    let mut agente = agente_cli_para_vista_previa(raiz.join("no-debe-usarse.exe"));
    agente.id = crate::conectores::IdAgente::GeminiCli;
    agente.nombre = "Gemini CLI";
    agente.cli = None;
    agente.conectado = true;
    agente.espacio_registrado = Some(raiz.display().to_string().replace('\\', "/"));
    preparar_envio_para_prueba(&mut app, &agente).expect("preparar un destino solo MCP");
    let textos = crate::arnes_interfaz::textos_del_modal_sesion_agente(&mut app, &ctx);
    assert!(
        textos.iter().any(|texto| texto.contains("Solo MCP")),
        "la vista debe explicar que no abrirá una consola: {textos:?}"
    );
    assert!(
        textos
            .iter()
            .any(|texto| texto.contains("Preparar para MCP")),
        "el botón no puede prometer una consola inexistente: {textos:?}"
    );
    let iniciado =
        iniciar_envio_confirmado_para_prueba(&mut app, &ctx).expect("confirmar sesión MCP");

    assert!(iniciado);
    assert_eq!(app.agentes.envio, EstadoEnvio::Preparando);
    assert!(
        app.agentes.editor_sesion.is_some(),
        "la vista previa sigue visible mientras se preparan los archivos"
    );
    assert!(
        !iniciar_envio_confirmado_para_prueba(&mut app, &ctx)
            .expect("un segundo clic no es un error"),
        "un segundo clic no puede poner otro envío en cola"
    );

    let limite = std::time::Instant::now() + std::time::Duration::from_secs(2);
    while app.agentes.envio == EstadoEnvio::Preparando {
        app.procesar_eventos_de_envio(&ctx);
        assert!(
            std::time::Instant::now() < limite,
            "la preparación asíncrona no terminó"
        );
        std::thread::sleep(std::time::Duration::from_millis(2));
    }

    assert_eq!(app.agentes.envio, EstadoEnvio::Preparado);
    assert!(raiz.join("plan_AI.md").is_file());
    assert_eq!(
        metadatos_del_unico_expediente(&raiz).estado,
        EstadoLanzamiento::Preparado
    );
    assert!(app.persistencia.vigilante.is_some());
    assert!(app.agentes.editor_sesion.is_none());
    drop(app);
    std::fs::remove_dir_all(raiz).expect("limpiar sesión MCP");
}

/// Un fallo durante la preparación asíncrona vuelve a la interfaz sin cerrar el borrador,
/// activar la vigilancia ni escribir primero en una ruta exterior al proyecto.
#[test]
fn un_fallo_de_preparacion_asincrona_conserva_el_borrador() {
    use crate::envio_agente::EstadoEnvio;

    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("fallo-preparacion-asincrona");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    let ruta_exterior = raiz
        .parent()
        .expect("carpeta contenedora")
        .join(format!("fuera-{}.mmcelt", uuid::Uuid::new_v4()));
    app.agentes.espacio_de_trabajo = raiz.clone();
    app.persistencia.ruta_actual = Some(ruta_exterior.clone());
    let mut agente = agente_cli_para_vista_previa(raiz.join("no-debe-usarse.exe"));
    agente.id = crate::conectores::IdAgente::GeminiCli;
    agente.nombre = "Gemini CLI";
    agente.cli = None;
    agente.conectado = true;
    agente.espacio_registrado = Some(raiz.display().to_string().replace('\\', "/"));
    preparar_envio_para_prueba(&mut app, &agente).expect("preparar vista previa");

    assert!(iniciar_envio_confirmado_para_prueba(&mut app, &ctx).expect("poner el trabajo en cola"));
    let limite = std::time::Instant::now() + std::time::Duration::from_secs(2);
    while app.agentes.envio == EstadoEnvio::Preparando {
        app.procesar_eventos_de_envio(&ctx);
        assert!(std::time::Instant::now() < limite, "el fallo no regresó");
        std::thread::sleep(std::time::Duration::from_millis(2));
    }

    assert_eq!(app.agentes.envio, EstadoEnvio::Fallido);
    assert!(
        app.agentes.editor_sesion.is_some(),
        "el borrador se conserva"
    );
    assert!(
        app.persistencia.vigilante.is_none(),
        "un envío fallido no se vigila"
    );
    assert!(
        !ruta_exterior.exists(),
        "la ruta exterior se rechaza antes de guardar"
    );
    drop(app);
    std::fs::remove_dir_all(raiz).expect("limpiar fallo asíncrono");
}

/// Cuenta las líneas del cuerpo de una función concreta a partir de su fuente.
fn lineas_de_funcion(fuente: &str, nombre: &str) -> usize {
    let aguja = format!("fn {nombre}(");
    let inicio = fuente
        .lines()
        .position(|linea| linea.contains(&aguja))
        .unwrap_or_else(|| panic!("no se encontró la función {nombre}"));
    let mut profundidad = 0_i32;
    let mut cuerpo_iniciado = false;
    for (desplazamiento, linea) in fuente.lines().skip(inicio).enumerate() {
        for caracter in linea.chars() {
            match caracter {
                '{' => {
                    cuerpo_iniciado = true;
                    profundidad += 1;
                }
                '}' if cuerpo_iniciado => profundidad -= 1,
                _ => {}
            }
        }
        if cuerpo_iniciado && profundidad == 0 {
            return desplazamiento + 1;
        }
    }
    panic!("la función {nombre} no tiene un cuerpo completo")
}

/// Las cuatro funciones de lógica señaladas por la auditoría deben quedar por debajo del
/// umbral de revisión. Las tablas exhaustivas de traducción no pasan por esta lista.
#[test]
fn las_funciones_de_logica_tienen_una_responsabilidad_acotada() {
    const MAXIMO: usize = 60;
    for (fuente, nombre) in [
        (include_str!("ui/canvas.rs"), "dibujar_lienzo"),
        (
            include_str!("mcp_server/operaciones.rs"),
            "crear_nodo_desde_la_actualizacion",
        ),
        (
            include_str!("envio_agente_comando.rs"),
            "iniciar_envio_confirmado",
        ),
        (
            include_str!("model/validacion.rs"),
            "validar_longitudes_de_texto",
        ),
    ] {
        let lineas = lineas_de_funcion(fuente, nombre);
        assert!(
            lineas <= MAXIMO,
            "{nombre} ocupa {lineas} líneas; debe separar responsabilidades antes de {MAXIMO}"
        );
    }
}

/// Mide el coste total de una selección visible sobre 10.000 posiciones frente a consultar
/// un índice por celdas. La medición incluye los dos recorridos completos que el lienzo aún
/// necesita para jerarquía y ramas; así no se atribuye al índice un ahorro que el fotograma
/// real no puede obtener.
#[test]
fn un_indice_espacial_solo_se_anade_si_mejora_un_veinticinco_por_ciento() {
    use std::collections::HashMap;
    use std::hint::black_box;
    use std::time::{Duration, Instant};

    const LADO: i32 = 100;
    const REPETICIONES: usize = 80;
    let posiciones: Vec<(i32, i32)> = (0..LADO)
        .flat_map(|x| (0..LADO).map(move |y| (x * 40, y * 30)))
        .collect();
    let mut indice: HashMap<(i32, i32), Vec<usize>> = HashMap::new();
    for (id, &(x, y)) in posiciones.iter().enumerate() {
        indice.entry((x / 400, y / 300)).or_default().push(id);
    }

    let medir = |con_indice: bool| -> Duration {
        let inicio = Instant::now();
        for _ in 0..REPETICIONES {
            // Jerarquía y cálculo de rama siguen necesitando ver todos los nodos.
            black_box(
                posiciones
                    .iter()
                    .fold(0_i64, |suma, &(x, y)| suma.wrapping_add((x ^ y) as i64)),
            );
            black_box(
                posiciones
                    .iter()
                    .fold(0_i64, |suma, &(x, y)| suma.wrapping_add((x + y) as i64)),
            );
            if con_indice {
                let mut visibles = 0;
                for x in 0..=2 {
                    for y in 0..=2 {
                        visibles += indice.get(&(x, y)).map_or(0, Vec::len);
                    }
                }
                black_box(visibles);
            } else {
                let visibles = posiciones
                    .iter()
                    .filter(|&&(x, y)| x <= 800 && y <= 600)
                    .count();
                black_box(visibles);
            }
        }
        inicio.elapsed()
    };
    let mut recorridos = [medir(false), medir(false), medir(false)];
    let mut indexados = [medir(true), medir(true), medir(true)];
    recorridos.sort();
    indexados.sort();
    let base = recorridos[1].as_secs_f64();
    let mejora = (base - indexados[1].as_secs_f64()) / base;

    assert!(
        mejora >= 0.25,
        "el índice espacial está implementado, pero la mediana solo mejora un {:.1}%; por debajo del umbral que justifica mantenerlo",
        mejora * 100.0
    );
}

/// La confirmación persiste todos los artefactos antes de entregar el control al proceso externo.
#[test]
fn confirmar_envio_respeta_guardar_exportar_expediente_lanzar_y_vigilar() {
    use crate::lanzador_agentes::{EjecutorDeConsola, OrdenCli, ResultadoLanzamiento};
    use crate::sesiones_agentes::{EstadoLanzamiento, MetadatosSesion};

    struct EjecutorQueInspecciona {
        mapa: std::path::PathBuf,
        markdown: std::path::PathBuf,
    }
    impl EjecutorDeConsola for EjecutorQueInspecciona {
        fn abrir(&self, orden: &OrdenCli) -> crate::error::AppResult<ResultadoLanzamiento> {
            assert!(
                self.mapa.is_file(),
                "el mapa debe estar guardado antes de lanzar"
            );
            assert!(
                self.markdown.is_file(),
                "el contexto Markdown debe existir antes de lanzar"
            );
            let referencia = orden.argumentos[0]
                .split('`')
                .nth(1)
                .expect("referencia delimitada al expediente");
            let inicio = orden.directorio.join(referencia);
            assert!(
                inicio.is_file(),
                "el expediente debe existir antes de lanzar"
            );
            let metadatos: MetadatosSesion = serde_json::from_slice(
                &std::fs::read(inicio.with_file_name("sesion.json")).expect("leer expediente"),
            )
            .expect("deserializar expediente");
            assert_eq!(metadatos.estado, EstadoLanzamiento::Preparado);
            Ok(ResultadoLanzamiento { pid: 4242 })
        }
    }

    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("confirmar-envio");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");
    let mapa = raiz.join("plan.mmcelt");
    let markdown = raiz.join("plan_AI.md");
    let ejecutable = std::env::current_exe().expect("localizar ejecutable de pruebas");
    app.agentes.espacio_de_trabajo = raiz.clone();
    let mut agente = agente_cli_para_vista_previa(ejecutable);
    agente.id = crate::conectores::IdAgente::CodexCli;
    preparar_envio_para_prueba(&mut app, &agente).expect("preparar vista previa");
    app.persistencia.ruta_actual = Some(mapa.clone());

    let iniciado = iniciar_envio_confirmado_con_para_prueba(
        &mut app,
        &ctx,
        &EjecutorQueInspecciona { mapa, markdown },
    )
    .expect("confirmar sesión");

    assert!(iniciado);
    assert!(
        app.persistencia.vigilante.is_some(),
        "la vigilancia comienza tras lanzar"
    );
    assert!(app.agentes.editor_sesion.is_none());
    let metadatos = metadatos_del_unico_expediente(&raiz);
    assert_eq!(metadatos.estado, EstadoLanzamiento::Iniciado);
    drop(app);
    std::fs::remove_dir_all(raiz).expect("limpiar confirmación");
}

