/// El recorrido de envío tiene un orden único y comprobable sin construir una interfaz gráfica.
#[test]
fn el_envio_es_un_caso_de_uso_independiente_de_la_interfaz() {
    use crate::envio_agente::{
        EnvioAAgente, LanzadorAgente, PersistenciaEnvio, RepositorioSesiones, ResultadoLanzamiento,
        ResultadoPreparacion, SolicitudEnvio,
    };
    use crate::sesiones_agentes::{EstadoLanzamiento, MetadatosSesion, SesionPreparada};
    use std::cell::RefCell;
    use std::path::{Path, PathBuf};
    use std::rc::Rc;

    type Eventos = Rc<RefCell<Vec<&'static str>>>;

    struct PersistenciaFalsa {
        eventos: Eventos,
        ruta_mapa: PathBuf,
        fallar_en: Option<&'static str>,
    }
    impl PersistenciaEnvio for PersistenciaFalsa {
        fn guardar(&mut self) -> crate::error::AppResult<ResultadoPreparacion> {
            self.eventos.borrow_mut().push("guardar");
            if self.fallar_en == Some("guardar") {
                return Err(error_de_prueba("guardar"));
            }
            Ok(ResultadoPreparacion::Preparado {
                ruta_mapa: self.ruta_mapa.clone(),
            })
        }

        fn exportar(&mut self, _ruta_mapa: &Path) -> crate::error::AppResult<()> {
            self.eventos.borrow_mut().push("exportar");
            if self.fallar_en == Some("exportar") {
                return Err(error_de_prueba("exportar"));
            }
            Ok(())
        }
    }

    struct SesionesFalsas {
        eventos: Eventos,
        sesion: SesionPreparada,
        fallar_en: Option<&'static str>,
    }
    impl RepositorioSesiones for SesionesFalsas {
        fn preparar(
            &self,
            _contexto: &crate::proyecto_trabajo::ContextoProyecto,
            _ruta_mapa: &Path,
            _prompt: &crate::sesiones_agentes::PromptSesionCompuesto,
        ) -> crate::error::AppResult<SesionPreparada> {
            self.eventos.borrow_mut().push("expediente");
            if self.fallar_en == Some("expediente") {
                return Err(error_de_prueba("expediente"));
            }
            Ok(self.sesion.clone())
        }

        fn actualizar(
            &self,
            _contexto: &crate::proyecto_trabajo::ContextoProyecto,
            sesion: &mut SesionPreparada,
            estado: EstadoLanzamiento,
        ) -> crate::error::AppResult<()> {
            self.eventos.borrow_mut().push(match estado {
                EstadoLanzamiento::Preparado => "estado:Preparado",
                EstadoLanzamiento::Iniciado => "estado:Iniciado",
                EstadoLanzamiento::Fallido => "estado:Fallido",
            });
            sesion.metadatos.estado = estado;
            Ok(())
        }
    }

    struct LanzadorFalso {
        eventos: Eventos,
        fallar: bool,
    }
    impl LanzadorAgente for LanzadorFalso {
        fn lanzar(
            &self,
            _agente: crate::conectores::IdAgente,
            _ejecutable: crate::lanzador_agentes::EjecutableConfirmado,
            _contexto: &crate::proyecto_trabajo::ContextoProyecto,
            _sesion: &SesionPreparada,
        ) -> crate::error::AppResult<crate::lanzador_agentes::ResultadoLanzamiento> {
            self.eventos.borrow_mut().push("lanzar");
            if self.fallar {
                return Err(error_de_prueba("lanzar"));
            }
            Ok(crate::lanzador_agentes::ResultadoLanzamiento { pid: 42 })
        }
    }

    fn error_de_prueba(paso: &'static str) -> crate::error::AppError {
        crate::error::AppError::lectura(
            paso,
            std::io::Error::other(format!("fallo simulado en {paso}")),
        )
    }

    fn sesion_falsa(raiz: &Path) -> SesionPreparada {
        let carpeta = raiz.join("expediente-falso");
        SesionPreparada {
            ruta_inicio: carpeta.join("inicio.md"),
            ruta_metadatos: carpeta.join("sesion.json"),
            carpeta,
            metadatos: MetadatosSesion {
                version_formato: 1,
                id_sesion: uuid::Uuid::nil(),
                fecha_utc: chrono::DateTime::UNIX_EPOCH,
                agente: crate::conectores::IdAgente::CodexCli,
                mapa_relativo: PathBuf::from("mapa.mmcelt"),
                fuentes_incorporadas: Vec::new(),
                fuentes_nativas_detectadas: Vec::new(),
                prompt_bytes: 0,
                estado: EstadoLanzamiento::Preparado,
            },
        }
    }

    fn ejecutar(
        fallar_en: Option<&'static str>,
        solo_mcp: bool,
    ) -> (
        crate::error::AppResult<ResultadoLanzamiento>,
        Vec<&'static str>,
    ) {
        let (raiz, contexto, mut borrador) = datos_de_expediente("caso-uso-envio");
        borrador.agente = crate::conectores::IdAgente::CodexCli;
        let ejecutable = if solo_mcp {
            None
        } else {
            let agente = agente_cli_para_vista_previa(
                std::env::current_exe().expect("localizar ejecutable de pruebas"),
            );
            Some(
                crate::lanzador_agentes::confirmar_ejecutable(&agente, &raiz)
                    .expect("confirmar ejecutable"),
            )
        };
        let solicitud = SolicitudEnvio {
            contexto,
            confirmacion: crate::sesiones_agentes::ConfirmacionSesion::nueva(
                prompt_de_sesion(&borrador),
                crate::model::RevisionProyecto::INICIAL,
                &borrador.reglas_proyecto,
                &borrador.encargo,
                &borrador.fuentes_nativas,
            ),
            ejecutable,
            conectado_por_mcp: solo_mcp,
        };
        let eventos = Rc::new(RefCell::new(Vec::new()));
        let mut persistencia = PersistenciaFalsa {
            eventos: Rc::clone(&eventos),
            ruta_mapa: raiz.join("mapa.mmcelt"),
            fallar_en,
        };
        let sesiones = SesionesFalsas {
            eventos: Rc::clone(&eventos),
            sesion: sesion_falsa(&raiz),
            fallar_en,
        };
        let lanzador = LanzadorFalso {
            eventos: Rc::clone(&eventos),
            fallar: fallar_en == Some("lanzar"),
        };
        let resultado =
            EnvioAAgente::nuevo(&lanzador, &mut persistencia, &sesiones).ejecutar(solicitud);
        let registrados = eventos.borrow().clone();
        std::fs::remove_dir_all(raiz).expect("limpiar caso de uso");
        (resultado, registrados)
    }

    let (resultado, eventos) = ejecutar(None, false);
    assert!(matches!(
        resultado,
        Ok(ResultadoLanzamiento::Iniciado { pid: 42, .. })
    ));
    assert_eq!(
        eventos,
        [
            "guardar",
            "exportar",
            "expediente",
            "lanzar",
            "estado:Iniciado"
        ]
    );

    for (fallo, esperados) in [
        ("guardar", vec!["guardar"]),
        ("exportar", vec!["guardar", "exportar"]),
        ("expediente", vec!["guardar", "exportar", "expediente"]),
        (
            "lanzar",
            vec![
                "guardar",
                "exportar",
                "expediente",
                "lanzar",
                "estado:Fallido",
            ],
        ),
    ] {
        let (resultado, eventos) = ejecutar(Some(fallo), false);
        assert!(resultado.is_err(), "{fallo} debe propagarse");
        assert_eq!(eventos, esperados, "{fallo} ejecutó pasos posteriores");
    }

    let (resultado, eventos) = ejecutar(None, true);
    assert!(matches!(
        resultado,
        Ok(ResultadoLanzamiento::PreparadoMcp { .. })
    ));
    assert_eq!(eventos, ["guardar", "exportar", "expediente"]);
}

/// La guía de «Enviar a...» explica el recorrido supervisado en los seis idiomas.
///
/// `la_ayuda_cubre_las_funcionalidades_de_la_aplicacion` solo lee el castellano y junta las
/// veintitrés guías en un único texto, así que un término colocado en cualquier otra guía la
/// deja en verde. Eso basta para vigilar que una funcionalidad esté documentada **en alguna
/// parte**, y no basta para esta: el usuario que abre «Enviar a...» y no sabe qué se transmite
/// va a mirar *esa* guía, y la va a mirar en su idioma.
///
/// Por eso aquí se comprueba un solo tema, seis veces, y siempre sobre el documento concreto.
///
/// Los términos van en dos grupos porque se comprueban de forma distinta:
///
/// - Los **comunes** son nombres propios, siglas y rutas de disco. Se escriben igual en los seis
///   idiomas y se buscan respetando mayúsculas: `API` en mayúsculas no lo satisface el «api» que
///   esconden «rapid» o «capital», y `macOS` no lo satisface un «macos» escrito de cualquier
///   manera.
/// - Los **propios de cada idioma** son las seis ideas que sí hay que traducir. Se buscan en
///   minúsculas porque una de ellas puede abrir frase.
#[test]
fn la_ayuda_del_envio_neutral_cubre_el_recorrido_en_los_seis_idiomas() {
    use crate::textos::Idioma;
    use crate::ui::help_system::TemaDeAyuda;

    // (qué buscar tal cual, qué obliga a explicar)
    const COMUNES: [(&str, &str); 11] = [
        (
            "Claude Code",
            "la consola oficial de Anthropic como destino",
        ),
        ("Codex CLI", "la consola oficial de OpenAI como destino"),
        (
            "Gemini CLI",
            "la consola oficial de Google como destino propio",
        ),
        (
            "MCP",
            "la vía por la que el agente devuelve trabajo al mapa",
        ),
        (
            ".mmcelt/sesiones",
            "dónde queda el expediente de cada envío",
        ),
        (
            "inicio.md",
            "el prompt exacto con el que se repite la sesión",
        ),
        (
            "sesion.json",
            "los datos no secretos que acompañan al prompt",
        ),
        (
            "API",
            "que MMCelt no usa ninguna API de pago y se apoya en la sesión ya autenticada del CLI",
        ),
        ("Windows", "una de las dos plataformas comprobadas"),
        ("Linux", "la otra plataforma comprobada"),
        ("macOS", "la plataforma que todavía no se afirma"),
    ];

    // (qué buscar en minúsculas, qué obliga a explicar)
    fn propios_de(idioma: Idioma) -> [(&'static str, &'static str); 6] {
        match idioma {
            Idioma::Espanol => [
                ("vista previa", "que el prompt se revisa antes de enviarlo"),
                ("editable", "qué bloques puede cambiar el usuario"),
                ("autentica", "que la sesión la aporta el CLI, no MMCelt"),
                ("capacidades", "que MCP y consola son capacidades separadas"),
                ("detener", "cómo se paran vigilancia y consola"),
                ("repetir", "cómo se repite una sesión ya lanzada"),
            ],
            Idioma::Ingles => [
                ("preview", "que el prompt se revisa antes de enviarlo"),
                ("editable", "qué bloques puede cambiar el usuario"),
                ("authenticat", "que la sesión la aporta el CLI, no MMCelt"),
                (
                    "capabilities",
                    "que MCP y consola son capacidades separadas",
                ),
                ("stop", "cómo se paran vigilancia y consola"),
                ("repeat", "cómo se repite una sesión ya lanzada"),
            ],
            Idioma::Frances => [
                ("aperçu", "que el prompt se revisa antes de enviarlo"),
                ("modifiable", "qué bloques puede cambiar el usuario"),
                (
                    "authentification",
                    "que la sesión la aporta el CLI, no MMCelt",
                ),
                ("capacités", "que MCP y consola son capacidades separadas"),
                ("arrêter", "cómo se paran vigilancia y consola"),
                ("rejouer", "cómo se repite una sesión ya lanzada"),
            ],
            Idioma::Aleman => [
                ("vorschau", "que el prompt se revisa antes de enviarlo"),
                ("bearbeitbar", "qué bloques puede cambiar el usuario"),
                (
                    "authentifizierung",
                    "que la sesión la aporta el CLI, no MMCelt",
                ),
                ("fähigkeiten", "que MCP y consola son capacidades separadas"),
                ("beenden", "cómo se paran vigilancia y consola"),
                ("wiederholen", "cómo se repite una sesión ya lanzada"),
            ],
            Idioma::Ruso => [
                (
                    "предварительный просмотр",
                    "que el prompt se revisa antes de enviarlo",
                ),
                ("редактир", "qué bloques puede cambiar el usuario"),
                ("аутентификац", "que la sesión la aporta el CLI, no MMCelt"),
                ("возможност", "que MCP y consola son capacidades separadas"),
                ("останов", "cómo se paran vigilancia y consola"),
                ("повтор", "cómo se repite una sesión ya lanzada"),
            ],
            Idioma::ChinoSimplificado => [
                ("预览", "que el prompt se revisa antes de enviarlo"),
                ("可编辑", "qué bloques puede cambiar el usuario"),
                ("身份验证", "que la sesión la aporta el CLI, no MMCelt"),
                ("能力", "que MCP y consola son capacidades separadas"),
                ("停止", "cómo se paran vigilancia y consola"),
                ("重复", "cómo se repite una sesión ya lanzada"),
            ],
        }
    }

    for idioma in Idioma::TODOS {
        let guia = TemaDeAyuda::EnviarAYVigilancia.guia_completa(idioma);
        for (buscado, explicado) in COMUNES {
            assert!(
                guia.contains(buscado),
                "la guía de «Enviar a...» en {idioma:?} no menciona «{buscado}»: \
                 falta explicar {explicado}"
            );
        }
        let guia_en_minusculas = guia.to_lowercase();
        for (buscado, explicado) in propios_de(idioma) {
            assert!(
                guia_en_minusculas.contains(buscado),
                "la guía de «Enviar a...» en {idioma:?} no menciona «{buscado}»: \
                 falta explicar {explicado}"
            );
        }
    }
}

/// Lee el JSON del único expediente creado por una prueba de confirmación.
fn metadatos_del_unico_expediente(
    raiz: &std::path::Path,
) -> crate::sesiones_agentes::MetadatosSesion {
    let carpetas: Vec<_> = std::fs::read_dir(raiz.join(".mmcelt/sesiones"))
        .expect("listar expedientes")
        .map(|entrada| entrada.expect("entrada de expediente").path())
        .collect();
    assert_eq!(carpetas.len(), 1, "debe existir un único expediente");
    serde_json::from_slice(&std::fs::read(carpetas[0].join("sesion.json")).expect("leer metadatos"))
        .expect("deserializar metadatos")
}

/// La conexión cruzada se llamaba de dos maneras distintas dentro de la misma interfaz.
///
/// El menú de Edición ofrecía «Crear Conexión Cruzada», pero el cuadro que se abría al
/// pulsarlo se titulaba «Crear Relación Cruzada Transversal», su desplegable pedía el
/// «Tipo de relación» y los dos avisos con que terminaba hablaban otra vez de «relación».
/// Quien seguía el menú no volvía a encontrar en ningún sitio la palabra que acababa de
/// leer, y tenía que deducir que las dos nombraban lo mismo.
///
/// El criterio fijado es que **manda el menú**: es lo primero
/// que ve el usuario. Esta prueba ata las siete piezas visibles del recorrido a un único
/// término por idioma y prohíbe expresamente los que se descartaron, que es el modo de
/// fallo real: la palabra vieja vuelve al añadir un texto nuevo copiando uno antiguo.
///
/// **No alcanza al modelo de datos.** `TipoRelacion` y la columna «Relación» del Markdown
/// de intercambio son contrato con los agentes y se dejaron intactos a propósito:
/// cambiarlos rompería la compatibilidad de los mapas ya escritos.
#[test]
fn la_conexion_cruzada_se_llama_igual_en_toda_la_interfaz() {
    use crate::textos::{Idioma, Texto};

    // Las siete piezas visibles del mismo recorrido: el menú que la crea, el rótulo del
    // inspector donde se listan, el cuadro que se abre, su desplegable, su botón de
    // confirmación y los dos avisos con que termina.
    const PIEZAS: [Texto; 8] = [
        Texto::EdicionCrearConexionCruzada,
        Texto::InspectorBotonConexion,
        Texto::InspectorRelacionesCruzadas,
        Texto::ModalCrearRelacionCruzadaTransversal,
        Texto::ModalTipoDeRelacion,
        Texto::ModalCrearRelacion,
        Texto::AvisoRelacionAnadida,
        Texto::AvisoRelacionNoCreada,
    ];

    // Para cada idioma: la raíz que deben compartir las seis, y las que quedaron
    // descartadas. Se compara en minúsculas para no depender de si la palabra abre frase.
    // El ruso y el chino ya eran coherentes y no tienen ninguna raíz prohibida.
    let terminos: [(Idioma, &str, &[&str]); 6] = [
        (Idioma::Espanol, "conexi", &["relaci"]),
        (Idioma::Ingles, "link", &["relationship"]),
        (Idioma::Frances, "liaison", &["relation"]),
        (Idioma::Aleman, "verbindung", &["beziehung", "verknüpfung"]),
        (Idioma::Ruso, "связ", &[]),
        (Idioma::ChinoSimplificado, "关联", &[]),
    ];

    for (idioma, esperado, descartados) in terminos {
        for pieza in PIEZAS {
            let visible = pieza.en(idioma);
            let comparable = visible.to_lowercase();

            assert!(
                comparable.contains(esperado),
                "en {idioma:?}, «{pieza:?}» dice «{visible}» y no usa «{esperado}», el término del menú"
            );

            for prohibido in descartados {
                assert!(
                    !comparable.contains(prohibido),
                    "en {idioma:?}, «{pieza:?}» vuelve a usar «{prohibido}», descartado: «{visible}»"
                );
            }
        }
    }
}

/// El programa no miraba en qué idioma está el sistema: abría siempre en castellano.
///
/// Se vio el 2026-08-30 en una captura de macOS: un Mac configurado en inglés abrió MMCelt
/// en español. No es un defecto de macOS —`Idioma` llevaba `#[default] Espanol` y no había
/// detección en ninguna parte—, así que afectaba a los tres sistemas y a la primera
/// impresión de cualquiera que no hable castellano.
///
/// Esta prueba fija cómo se interpreta la etiqueta que declara el sistema. Hay que aceptar
/// las dos notaciones que llegan en la práctica: la de Windows, `es-ES`, y la POSIX de
/// Linux y macOS, `es_ES.UTF-8`, que además arrastra codificación y a veces modificador.
#[test]
fn el_idioma_del_sistema_se_reconoce_en_las_dos_notaciones() {
    use crate::textos::Idioma;

    let casos = [
        ("es-ES", Idioma::Espanol),
        ("es_ES.UTF-8", Idioma::Espanol),
        ("es-419", Idioma::Espanol),
        ("en-US", Idioma::Ingles),
        ("en_GB.UTF-8", Idioma::Ingles),
        ("EN", Idioma::Ingles),
        ("fr-FR", Idioma::Frances),
        ("fr_CA.UTF-8", Idioma::Frances),
        ("de-DE", Idioma::Aleman),
        ("de_AT@euro", Idioma::Aleman),
        ("ru-RU", Idioma::Ruso),
        ("ru_RU.UTF-8", Idioma::Ruso),
    ];

    for (etiqueta, esperado) in casos {
        assert_eq!(
            Idioma::desde_etiqueta_del_sistema(etiqueta),
            Some(esperado),
            "la etiqueta «{etiqueta}» debería reconocerse como {esperado:?}"
        );
    }
}

/// Un idioma que el programa no habla no puede confundirse con otro que empiece igual.
///
/// Es el modo de fallo de comparar por prefijo: `et` (estonio) empieza por `e` como `es`,
/// y `dev` no es alemán. Se compara el **subtag primario entero**, no un prefijo, y lo que
/// no está entre los seis se responde con `None` para que decida quien llame.
#[test]
fn un_idioma_que_el_programa_no_habla_no_se_hace_pasar_por_otro() {
    use crate::textos::Idioma;

    for ajeno in [
        "et-EE", "eu-ES", "da-DK", "nl-NL", "pt-PT", "it-IT", "C", "POSIX", "", "-", "und",
    ] {
        assert_eq!(
            Idioma::desde_etiqueta_del_sistema(ajeno),
            None,
            "«{ajeno}» no es ninguno de los seis idiomas y no debería reconocerse"
        );
    }

    // Y con lo que no se reconoce, el programa se queda en el idioma en que se escribió.
    assert_eq!(
        Idioma::desde_etiqueta_del_sistema("it-IT").unwrap_or(Idioma::Espanol),
        Idioma::Espanol
    );
}

/// El chino tradicional no puede hacerse pasar por simplificado.
///
/// El programa solo habla **chino simplificado**. A alguien en Taiwán, Hong Kong o Macao
/// mostrarle simplificado no es traducirle: es darle un texto que no es el suyo. Vale más
/// que caiga al idioma de respaldo, que al menos no finge.
#[test]
fn el_chino_tradicional_no_se_hace_pasar_por_simplificado() {
    use crate::textos::Idioma;

    for simplificado in ["zh-Hans-CN", "zh-CN", "zh_CN.UTF-8", "zh-SG", "zh"] {
        assert_eq!(
            Idioma::desde_etiqueta_del_sistema(simplificado),
            Some(Idioma::ChinoSimplificado),
            "«{simplificado}» es chino simplificado"
        );
    }

    for tradicional in [
        "zh-Hant-TW",
        "zh-TW",
        "zh_TW.UTF-8",
        "zh-HK",
        "zh-MO",
        "zh-Hant",
    ] {
        assert_eq!(
            Idioma::desde_etiqueta_del_sistema(tradicional),
            None,
            "«{tradicional}» es chino tradicional y el programa no lo habla"
        );
    }
}

/// Quien ya venía usando el programa no se encuentra la interfaz cambiada de idioma.
///
/// La detección es **solo para el primer arranque**, cuando todavía no hay archivo de
/// preferencias. Un archivo que existe pero no trae el campo `idioma` es el de alguien que
/// ya usaba MMCelt antes de que esto existiera: a esa persona no se le cambia el idioma por
/// debajo, porque lo que veía hasta ayer era el castellano.
#[test]
fn un_usuario_que_ya_tenia_preferencias_no_cambia_de_idioma_solo() {
    use crate::preferencias::Preferencias;
    use crate::textos::Idioma;

    // Un archivo válido sin el campo «idioma»: se queda en el de fábrica, mire lo que mire
    // el sistema operativo.
    assert_eq!(
        Preferencias::desde_texto("{\"tema\": \"Oscuro\"}").idioma,
        Idioma::default(),
        "a quien ya tenía preferencias no se le cambia el idioma al detectar el del sistema"
    );

    // El primer arranque, en cambio, sí pregunta al sistema.
    assert_eq!(
        Preferencias::primer_arranque().idioma,
        Idioma::del_sistema(),
        "sin preferencias guardadas, el idioma tiene que salir del sistema"
    );
}

/// La consulta al sistema tiene que responder de verdad, no fallar en silencio.
///
/// Es el modo de fallo que las pruebas de la traducción de etiquetas **no** ven: si la
/// llamada a Windows dejara de responder, `del_sistema()` caería al castellano y las doce
/// etiquetas de `el_idioma_del_sistema_se_reconoce_en_las_dos_notaciones` seguirían pasando
/// tan tranquilas. El programa volvería a abrirse siempre en español y nada se pondría rojo.
///
/// Este proyecto ya se ha encontrado ocho controles que no hacían nada con la batería en
/// verde, así que la llamada real se comprueba aparte. Solo en Windows: es el único sistema
/// donde el idioma no viaja en una variable de entorno y hay que preguntárselo con FFI.
#[cfg(windows)]
#[test]
fn windows_declara_de_verdad_en_que_idioma_esta() {
    let etiqueta = crate::textos::etiqueta_del_sistema()
        .expect("Windows siempre tiene una configuración regional que declarar");

    assert!(
        !etiqueta.trim().is_empty(),
        "la configuración regional de Windows no puede llegar vacía"
    );

    // Forma mínima de una etiqueta BCP 47: el subtag primario son dos o tres letras.
    let primario = etiqueta.split('-').next().unwrap_or_default();
    assert!(
        (2..=3).contains(&primario.len()) && primario.chars().all(|c| c.is_ascii_alphabetic()),
        "«{etiqueta}» no tiene forma de etiqueta de idioma: el subtag primario es «{primario}»"
    );
}

/// Deshacer devuelve el mapa al estado anterior, y rehacer lo trae de vuelta.
///
/// El programa no tenía deshacer: un borrado en cascada —que se lleva toda la descendencia
/// del nodo— era definitivo. Es la ausencia más grave de un editor, porque el usuario no
/// tiene forma de arriesgarse a probar nada.
#[test]
fn deshacer_devuelve_el_mapa_al_estado_anterior_y_rehacer_lo_trae_de_vuelta() {
    use crate::historial::{HistorialDeCambios, AGRUPACION};
    use crate::model::Proyecto;
    use std::time::Instant;

    let mut historial = HistorialDeCambios::nuevo();
    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;

    let inicio = Instant::now();
    historial.observar(&proyecto, inicio);
    assert!(
        !historial.puede_deshacer(),
        "un mapa recién abierto no tiene nada que deshacer"
    );

    proyecto.anadir_hijo(raiz, "Nodo añadido");
    historial.observar(&proyecto, inicio + AGRUPACION * 2);
    assert!(
        historial.puede_deshacer(),
        "añadir un nodo es un paso deshacible"
    );
    assert_eq!(proyecto.nodes.len(), 2);

    let anterior = historial
        .deshacer(&proyecto)
        .expect("debería poder deshacerse");
    assert_eq!(
        anterior.nodes.len(),
        1,
        "al deshacer, el nodo añadido tiene que desaparecer"
    );
    assert!(
        historial.puede_rehacer(),
        "lo deshecho tiene que poder rehacerse"
    );

    let rehecho = historial
        .rehacer(&anterior)
        .expect("debería poder rehacerse");
    assert_eq!(
        rehecho.nodes.len(),
        2,
        "al rehacer, el nodo tiene que volver"
    );
}

/// Deshacer no puede registrarse a sí mismo como un cambio del usuario.
///
/// Es el modo de fallo propio de un historial que se entera mirando en lugar de que le
/// avisen: deshacer **también** cambia el mapa, así que el vistazo siguiente lo vería como
/// un cambio nuevo, lo apuntaría en el pasado y borraría el futuro. El resultado sería que
/// rehacer nunca funciona y que pulsar deshacer dos veces devuelve al punto de partida.
#[test]
fn deshacer_no_se_registra_a_si_mismo_como_un_cambio_nuevo() {
    use crate::historial::{HistorialDeCambios, AGRUPACION};
    use crate::model::Proyecto;
    use std::time::Instant;

    let mut historial = HistorialDeCambios::nuevo();
    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;

    let inicio = Instant::now();
    historial.observar(&proyecto, inicio);
    proyecto.anadir_hijo(raiz, "Primero");
    historial.observar(&proyecto, inicio + AGRUPACION * 2);
    proyecto.anadir_hijo(raiz, "Segundo");
    historial.observar(&proyecto, inicio + AGRUPACION * 4);

    // Se deshace un paso y el bucle sigue corriendo: el fotograma siguiente vuelve a mirar.
    let un_paso_atras = historial.deshacer(&proyecto).expect("un paso atrás");
    historial.observar(&un_paso_atras, inicio + AGRUPACION * 6);

    assert!(
        historial.puede_rehacer(),
        "el vistazo posterior a deshacer no puede borrar lo que había que rehacer"
    );

    let rehecho = historial
        .rehacer(&un_paso_atras)
        .expect("tiene que seguir habiendo algo que rehacer");
    assert_eq!(rehecho.nodes.len(), 3, "rehacer devuelve los dos nodos");
}

/// Los cambios que van seguidos se deshacen de una vez.
///
/// Arrastrar un nodo cambia el mapa en cada fotograma. Sin agrupar, un arrastre de dos
/// segundos dejaría más de cien pasos y haría falta pulsar deshacer cien veces para volver
/// al sitio: deshacer sería inservible justo cuando más se necesita.
#[test]
fn los_cambios_que_van_seguidos_se_deshacen_de_una_vez() {
    use crate::historial::{HistorialDeCambios, AGRUPACION};
    use crate::model::Proyecto;
    use std::time::{Duration, Instant};

    let mut historial = HistorialDeCambios::nuevo();
    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;

    let inicio = Instant::now();
    historial.observar(&proyecto, inicio);

    // Veinte cambios muy seguidos, como los fotogramas de un arrastre.
    let mut momento = inicio;
    for numero in 0..20 {
        proyecto.anadir_hijo(raiz, format!("Nodo {numero}"));
        momento += Duration::from_millis(16);
        historial.observar(&proyecto, momento);
    }

    let vuelta = historial
        .deshacer(&proyecto)
        .expect("la ráfaga tiene que poder deshacerse");
    assert_eq!(
        vuelta.nodes.len(),
        1,
        "una ráfaga de cambios seguidos se deshace entera de una vez"
    );
    assert!(
        !historial.puede_deshacer(),
        "y no deja veinte pasos detrás, sino uno solo"
    );

    // En cambio, dos cambios separados por una pausa son dos pasos distintos.
    let mut separado = HistorialDeCambios::nuevo();
    let mut otro = Proyecto::nuevo_vacio("Mapa");
    let raiz_otro = otro.root_id;
    separado.observar(&otro, inicio);
    otro.anadir_hijo(raiz_otro, "Uno");
    separado.observar(&otro, inicio + AGRUPACION * 2);
    otro.anadir_hijo(raiz_otro, "Dos");
    separado.observar(&otro, inicio + AGRUPACION * 4);

    let primera = separado.deshacer(&otro).expect("primer paso atrás");
    assert_eq!(primera.nodes.len(), 2, "se deshace un cambio, no los dos");
    assert!(separado.puede_deshacer(), "queda el otro paso");
}

/// Un cambio nuevo invalida lo que se podía rehacer.
///
/// Si alguien deshace y luego escribe algo distinto, el camino que había deshecho ya no
/// ocurrió. Conservarlo permitiría rehacer encima de un mapa que ya no es aquel, y el
/// resultado sería un mapa que nunca existió.
#[test]
fn un_cambio_nuevo_invalida_lo_que_se_podia_rehacer() {
    use crate::historial::{HistorialDeCambios, AGRUPACION};
    use crate::model::Proyecto;
    use std::time::Instant;

    let mut historial = HistorialDeCambios::nuevo();
    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;

    let inicio = Instant::now();
    historial.observar(&proyecto, inicio);
    proyecto.anadir_hijo(raiz, "Camino viejo");
    historial.observar(&proyecto, inicio + AGRUPACION * 2);

    let mut atras = historial.deshacer(&proyecto).expect("un paso atrás");
    assert!(historial.puede_rehacer());

    // El usuario toma otro camino.
    let raiz_atras = atras.root_id;
    atras.anadir_hijo(raiz_atras, "Camino nuevo");
    historial.observar(&atras, inicio + AGRUPACION * 4);

    assert!(
        !historial.puede_rehacer(),
        "tomar un camino nuevo tiene que descartar el que se había deshecho"
    );
}

/// El historial no crece sin freno.
///
/// Cada paso es una copia del mapa entero. Sin tope, una sesión larga sobre un mapa grande
/// multiplicaría la memoria del programa sin que nadie lo pidiera.
#[test]
fn el_historial_no_crece_sin_freno() {
    use crate::historial::{HistorialDeCambios, AGRUPACION, PASOS_MAXIMOS};
    use crate::model::Proyecto;
    use std::time::Instant;

    let mut historial = HistorialDeCambios::nuevo();
    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;

    let mut momento = Instant::now();
    historial.observar(&proyecto, momento);

    for numero in 0..(PASOS_MAXIMOS + 20) {
        proyecto.anadir_hijo(raiz, format!("Nodo {numero}"));
        momento += AGRUPACION * 2;
        historial.observar(&proyecto, momento);
    }

    // Se deshace hasta agotar el historial, contando los pasos.
    let mut pasos = 0;
    let mut actual = proyecto.clone();
    while let Some(anterior) = historial.deshacer(&actual) {
        actual = anterior;
        pasos += 1;
    }

    assert_eq!(
        pasos, PASOS_MAXIMOS,
        "el historial tiene que quedarse en {PASOS_MAXIMOS} pasos, no crecer sin freno"
    );
}

/// Abrir otro mapa olvida el historial del anterior.
///
/// Deshacer después de abrir un archivo distinto traería de vuelta un mapa que no es el que
/// está abierto, y lo pisaría. Es la forma más directa de destruir el trabajo del usuario
/// con una función que existe justo para lo contrario.
#[test]
fn abrir_otro_mapa_olvida_el_historial_del_anterior() {
    use crate::historial::{HistorialDeCambios, AGRUPACION};
    use crate::model::Proyecto;
    use std::time::Instant;

    let mut historial = HistorialDeCambios::nuevo();
    let mut primero = Proyecto::nuevo_vacio("Primero");
    let raiz = primero.root_id;

    let inicio = Instant::now();
    historial.observar(&primero, inicio);
    primero.anadir_hijo(raiz, "Algo");
    historial.observar(&primero, inicio + AGRUPACION * 2);
    assert!(historial.puede_deshacer());

    let segundo = Proyecto::nuevo_vacio("Segundo");
    historial.olvidar(&segundo);

    assert!(
        !historial.puede_deshacer(),
        "el historial del mapa anterior no puede sobrevivir a abrir otro"
    );
    assert!(!historial.puede_rehacer());
}

/// Las dos entradas nuevas se pintan de verdad en el menú de Edición, en los seis idiomas.
///
/// Que el texto exista en `textos.rs` no dice que el menú lo use. Este proyecto ya se ha
/// encontrado ocho controles que no hacían nada con la batería en verde, así que el menú se
/// dibuja y se mira qué salió pintado.
#[test]
fn el_menu_de_edicion_ofrece_deshacer_y_rehacer_en_los_seis_idiomas() {
    use crate::textos::{Idioma, Texto};

    for idioma in Idioma::TODOS {
        let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
        app.presentacion.preferencias.idioma = idioma;

        let pintados = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
            crate::ui::toolbar::menu_edicion(app, ui);
        });

        for entrada in [Texto::EdicionDeshacer, Texto::EdicionRehacer] {
            let esperado = entrada.en(idioma);
            assert!(
                pintados.iter().any(|texto| texto.contains(esperado)),
                "en {idioma:?}, el menú de Edición no pinta «{esperado}». Pintó: {pintados:?}"
            );
        }
    }
}

/// Deshacer recupera un nodo borrado desde la aplicación, no solo desde el módulo.
///
/// Es la prueba que cierra el hueco entre las dos mitades: el historial puede estar perfecto
/// y no servir de nada si la aplicación no lo mira, o si mira el mapa antes de que el usuario
/// lo toque. Aquí se hace el recorrido entero —borrar un nodo con toda su descendencia y
/// deshacerlo— sobre la aplicación de verdad.
#[test]
fn deshacer_recupera_desde_la_aplicacion_un_nodo_borrado_con_su_descendencia() {
    use crate::historial::AGRUPACION;
    use std::time::Instant;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    // El mapa de arranque ya trae nodos, así que no se supone ninguna cifra: se miden.
    let raiz = app.mapa.proyecto.root_id;
    let rama = app
        .mapa
        .proyecto
        .anadir_hijo(raiz, "Rama con trabajo dentro");
    app.mapa
        .proyecto
        .anadir_hijo(rama, "Hoja que se iría con ella");
    let nodos_antes = app.mapa.proyecto.nodes.len();

    // El fotograma en que el historial toma la referencia del estado con trabajo.
    let momento = Instant::now();
    app.mapa.historial.observar(&app.mapa.proyecto, momento);

    // El usuario borra la rama entera.
    app.mapa.nodo_seleccionado = Some(rama);
    app.eliminar_nodo_seleccionado();
    app.mapa
        .historial
        .observar(&app.mapa.proyecto, momento + AGRUPACION * 2);
    assert_eq!(
        app.mapa.proyecto.nodes.len(),
        nodos_antes - 2,
        "el borrado se lleva la rama y la hoja que colgaba de ella"
    );

    app.deshacer();

    assert_eq!(
        app.mapa.proyecto.nodes.len(),
        nodos_antes,
        "deshacer tiene que devolver la rama con toda su descendencia"
    );
    assert!(
        app.mapa.proyecto.nodes.contains_key(&rama),
        "y el nodo tiene que volver con su mismo identificador"
    );

    // Y la selección no puede quedar apuntando a un nodo que no existe.
    let seleccion = app
        .mapa
        .nodo_seleccionado
        .expect("tiene que quedar algo seleccionado");
    assert!(
        app.mapa.proyecto.nodes.contains_key(&seleccion),
        "tras deshacer, la selección apunta a un nodo que no está en el mapa"
    );
}

/// Rehacer vuelve a aplicar lo deshecho desde la aplicación.
#[test]
fn rehacer_desde_la_aplicacion_vuelve_a_aplicar_lo_deshecho() {
    use crate::historial::AGRUPACION;
    use std::time::Instant;

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    let raiz = app.mapa.proyecto.root_id;
    let nodos_iniciales = app.mapa.proyecto.nodes.len();
    let momento = Instant::now();
    app.mapa.historial.observar(&app.mapa.proyecto, momento);

    app.mapa.proyecto.anadir_hijo(raiz, "Añadido");
    app.mapa
        .historial
        .observar(&app.mapa.proyecto, momento + AGRUPACION * 2);
    assert_eq!(app.mapa.proyecto.nodes.len(), nodos_iniciales + 1);

    app.deshacer();
    assert_eq!(
        app.mapa.proyecto.nodes.len(),
        nodos_iniciales,
        "deshacer quita el nodo añadido"
    );

    app.rehacer();
    assert_eq!(
        app.mapa.proyecto.nodes.len(),
        nodos_iniciales + 1,
        "rehacer tiene que devolver el nodo que se había quitado"
    );
}

/// La búsqueda encuentra por título y por etiqueta, que es lo que identifica a un nodo.
///
/// En un mapa de cien nodos, dar con uno a ojo obliga a abrir ramas plegadas y a mover la
/// cámara sin saber hacia dónde. Las notas quedan fuera a propósito: son párrafos largos y
/// cualquier palabra común devolvería medio mapa, que es lo mismo que no devolver nada.
#[test]
fn la_busqueda_encuentra_por_titulo_y_por_etiqueta_pero_no_por_las_notas() {
    use crate::busqueda::buscar_nodos;
    use crate::model::{FiltroDeBusqueda, Proyecto};

    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;

    let por_titulo = proyecto.anadir_hijo(raiz, "Motor de facturación");
    let por_etiqueta = proyecto.anadir_hijo(raiz, "Pantalla de acceso");
    let solo_en_notas = proyecto.anadir_hijo(raiz, "Informe mensual");

    if let Some(nodo) = proyecto.nodes.get_mut(&por_etiqueta) {
        nodo.tags.push("facturacion".to_string());
    }
    if let Some(nodo) = proyecto.nodes.get_mut(&solo_en_notas) {
        nodo.notes = "Aquí se habla de facturación largo y tendido".to_string();
    }

    let encontrados = buscar_nodos(&proyecto, &FiltroDeBusqueda::por_texto("facturacion"));

    assert!(
        encontrados.contains(&por_titulo),
        "tiene que encontrarse el nodo cuyo título lo dice"
    );
    assert!(
        encontrados.contains(&por_etiqueta),
        "y el que lo lleva como etiqueta"
    );
    assert!(
        !encontrados.contains(&solo_en_notas),
        "pero no el que solo lo menciona en sus notas: las notas no se buscan"
    );
}

/// Se busca como se escribe, no como se acentúa.
///
/// Exigir la tilde exacta convierte la búsqueda en un examen de ortografía. Quien teclee
/// `diseno` tiene que encontrar «Diseño», igual que en cualquier buscador.
#[test]
fn la_busqueda_ignora_mayusculas_y_tildes() {
    use crate::busqueda::buscar_nodos;
    use crate::model::FiltroDeBusqueda;
    use crate::model::Proyecto;

    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;
    let nodo = proyecto.anadir_hijo(raiz, "Diseño de la Interfaz Gráfica");

    for consulta in [
        "diseño", "DISEÑO", "diseno", "Diseno", "gráfica", "grafica", "GRÁFICA",
    ] {
        assert!(
            buscar_nodos(&proyecto, &FiltroDeBusqueda::por_texto(consulta)).contains(&nodo),
            "«{consulta}» tendría que encontrar «Diseño de la Interfaz Gráfica»"
        );
    }
}

/// Una búsqueda vacía no devuelve nada, y no devuelve todo.
///
/// El campo vacío significa que todavía no se ha buscado. Devolver el mapa entero llenaría
/// la lista de resultados nada más abrir el programa.
#[test]
fn una_busqueda_vacia_no_devuelve_nada() {
    use crate::busqueda::buscar_nodos;
    use crate::model::FiltroDeBusqueda;
    use crate::model::Proyecto;

    let mut proyecto = Proyecto::nuevo_vacio("Mapa");
    let raiz = proyecto.root_id;
    proyecto.anadir_hijo(raiz, "Algo");

    for vacia in ["", " ", "   ", "\t"] {
        assert!(
            buscar_nodos(&proyecto, &FiltroDeBusqueda::por_texto(vacia)).is_empty(),
            "una consulta vacía no puede devolver resultados"
        );
    }
}

/// **C19** — Indicadores en el nodo: prioridad y control humano.
///
/// Evalúa que `calcular_indicadores_del_nodo` sea una función pura y desacoplada del pintor (C19-A),
/// que opere de manera determinista y sin requerir contexto de GPU ni dependencias de interfaz.
#[test]
fn c19_a_indicadores_del_nodo_es_funcion_pura_desacoplada() {
    use crate::model::{EstadoRevision, PrioridadNodo};
    use crate::ui::canvas::calcular_indicadores_del_nodo;

    let res1 = calcular_indicadores_del_nodo(PrioridadNodo::Critica, EstadoRevision::GeneradoPorIA);
    let res2 = calcular_indicadores_del_nodo(PrioridadNodo::Critica, EstadoRevision::GeneradoPorIA);

    assert_eq!(
        res1, res2,
        "C19-A: calcular_indicadores_del_nodo debe ser determinista e idéntica ante las mismas entradas"
    );
    assert_eq!(
        res1.len(),
        2,
        "C19-A: una combinación crítica generada por IA debe producir exactamente 2 indicadores"
    );
    assert_eq!(res1[0].simbolo, "🔥");
    assert!(res1[0].es_prioridad);
    assert_eq!(res1[1].simbolo, "🤖");
    assert!(!res1[1].es_prioridad);
}

/// **C19** — Barrera exhaustiva de 96 combinaciones sin GPU (C19-B, PH-0925-1).
///
/// Recorre el producto cartesiano de los 6 estados de nodo, 4 estados de revisión humana
/// y 4 niveles de prioridad estratégica (6 × 4 × 4 = 96 combinaciones).
///
/// Comprueba que:
/// 1. Prioridad: `Critica` (🔥), `Alta` (⚡), `Media` (🔷) y `Baja` (🔽) generan siempre su indicador.
/// 2. Control humano: `GeneradoPorIA` (🤖), `AprobadoPorHumano` (🛡️), `RequiereCorreccion` (⚠️)
///    y `PendienteRevision` (⏳) generan siempre su indicador.
/// 3. El número total de indicadores producidos es siempre exactamente 2 (uno de prioridad y uno de revisión).
#[test]
fn c19_b_evaluacion_exhaustiva_96_combinaciones() {
    use crate::model::{EstadoNodo, EstadoRevision, PrioridadNodo};
    use crate::ui::canvas::calcular_indicadores_del_nodo;

    let mut total_combinaciones = 0;

    for _estado in EstadoNodo::TODOS {
        for revision in EstadoRevision::TODOS {
            for prioridad in PrioridadNodo::TODOS {
                total_combinaciones += 1;
                let indicadores = calcular_indicadores_del_nodo(prioridad, revision);

                assert_eq!(
                    indicadores.len(),
                    2,
                    "C19-B: para prioridad {:?} y revisión {:?}, se esperaban exactamente 2 indicadores y se obtuvieron {}",
                    prioridad,
                    revision,
                    indicadores.len()
                );

                let ind_prio = indicadores.iter().find(|i| i.es_prioridad);
                assert!(
                    ind_prio.is_some(),
                    "C19-B: debe existir un indicador de prioridad para {:?}",
                    prioridad
                );
                let ind_prio = ind_prio.unwrap();
                let simbolo_prio_esperado = match prioridad {
                    PrioridadNodo::Critica => "🔥",
                    PrioridadNodo::Alta => "⚡",
                    PrioridadNodo::Media => "🔷",
                    PrioridadNodo::Baja => "🔽",
                };
                assert_eq!(
                    ind_prio.simbolo, simbolo_prio_esperado,
                    "C19-B: el símbolo de prioridad para {:?} debe ser «{}»",
                    prioridad, simbolo_prio_esperado
                );

                let ind_rev = indicadores.iter().find(|i| !i.es_prioridad);
                assert!(
                    ind_rev.is_some(),
                    "C19-B: debe existir un indicador de revisión para {:?}",
                    revision
                );
                let ind_rev = ind_rev.unwrap();
                let simbolo_rev_esperado = match revision {
                    EstadoRevision::GeneradoPorIA => "🤖",
                    EstadoRevision::AprobadoPorHumano => "🛡️",
                    EstadoRevision::RequiereCorreccion => "⚠️",
                    EstadoRevision::PendienteRevision => "⏳",
                };
                assert_eq!(
                    ind_rev.simbolo, simbolo_rev_esperado,
                    "C19-B: el símbolo de revisión para {:?} debe ser «{}»",
                    revision, simbolo_rev_esperado
                );
            }
        }
    }

    assert_eq!(
        total_combinaciones, 96,
        "C19-B: deben evaluarse exactamente 96 combinaciones (6 estados × 4 revisiones × 4 prioridades)"
    );
}

/// **C19** — Cero solapamiento geométrico en la tarjeta del nodo (C19-D).
///
/// Comprueba que el espacio horizontal reservado para los indicadores cuando están presentes
/// reduce adecuadamente el ancho asignado al título, y que la cota vertical de los indicadores
/// (esquina superior derecha) nunca intersecta con la fila inferior reservada para notas y etiquetas.
#[test]
fn c19_d_geometria_reserva_margen_sin_solapamiento() {
    use crate::layout::{ALTURA_BASE_NODO, ANCHO_MINIMO_NODO};
    use crate::ui::canvas::reserva_horizontal_de_indicadores;

    let reserva_cero = reserva_horizontal_de_indicadores(0, 1.0);
    assert_eq!(
        reserva_cero, 0.0,
        "C19-D: sin indicadores la reserva horizontal debe ser 0.0"
    );

    let reserva_uno = reserva_horizontal_de_indicadores(1, 1.0);
    assert!(
        reserva_uno >= 16.0,
        "C19-D: con 1 indicador la reserva horizontal debe ser de al menos 16.0 puntos"
    );

    let reserva_dos = reserva_horizontal_de_indicadores(2, 1.0);
    assert!(
        reserva_dos > reserva_uno,
        "C19-D: con 2 indicadores la reserva horizontal debe ser estrictamente mayor que con 1"
    );

    // En el ancho mínimo de un nodo (120 px), con 2 indicadores aún debe quedar al menos 60 px para el título
    let margen_texto_base = 20.0;
    let ancho_disponible = ANCHO_MINIMO_NODO - (margen_texto_base + reserva_dos);
    assert!(
        ancho_disponible >= 60.0,
        "C19-D: en el ancho mínimo del nodo debe quedar al menos 60 px para el título (quedan {ancho_disponible})"
    );

    // Verificación vertical:
    // La fila superior empieza en y = 12.0 con altura de letra ~13.0 (ocupa hasta y = 25.0).
    // La fila inferior de notas y etiquetas se sitúa en max.y - 14.0 = 34.0 (para altura base 48.0).
    // Existe un cortafuegos vertical de al menos 8.0 puntos entre ambas áreas.
    let cota_inferior_indicadores = 12.0 + 14.0;
    let cota_superior_fila_inferior = ALTURA_BASE_NODO - 14.0;
    assert!(
        cota_superior_fila_inferior > cota_inferior_indicadores,
        "C19-D: la fila inferior de notas/etiquetas ({cota_superior_fila_inferior}) debe estar por debajo de los indicadores ({cota_inferior_indicadores})"
    );
}

/// **C19** — Tipado y métodos propios de representación en el modelo (C19-E, PH-0925-1).
///
/// Comprueba que `PrioridadNodo::simbolo` y `EstadoRevision::simbolo_en_nodo` ofrecen
