/// Ir a un resultado lleva la vista hasta el nodo, sin cambiar el zoom.
///
/// Encontrarlo en una lista y que el mapa siga donde estaba deja el trabajo a medias: en un
/// mapa grande, el nodo puede quedar a miles de píxeles de lo que se ve.
#[test]
fn ir_a_un_nodo_lleva_la_vista_hasta_el_sin_cambiar_el_zoom() {
    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    let raiz = app.mapa.proyecto.root_id;
    let lejano = app.mapa.proyecto.anadir_hijo(raiz, "Nodo apartado");
    if let Some(nodo) = app.mapa.proyecto.nodes.get_mut(&lejano) {
        nodo.pos = [4000.0, -2500.0];
    }

    app.lienzo.vista.zoom = 0.75;
    app.lienzo.vista.desplazamiento = egui::Vec2::ZERO;

    app.centrar_en_el_nodo(lejano);

    // La conversión a pantalla es `centro + (posición + desplazamiento) * zoom`, así que el
    // nodo queda centrado cuando desplazamiento es su posición cambiada de signo.
    assert_eq!(
        app.lienzo.vista.desplazamiento,
        egui::Vec2::new(-4000.0, 2500.0),
        "la vista no ha ido hasta el nodo"
    );
    assert_eq!(
        app.lienzo.vista.zoom, 0.75,
        "ir a un nodo no puede cambiar el nivel de detalle al que se estaba mirando el mapa"
    );
}

/// El intervalo de autoguardado se puede cambiar y se puede apagar.
///
/// Antes eran dos minutos fijos escritos en el código: no había forma de cambiarlos ni de
/// desactivarlo sin recompilar el programa, aunque el campo que lo apagaba ya existiera.
#[test]
fn el_intervalo_de_autoguardado_se_puede_cambiar_y_apagar() {
    use crate::autoguardado::ControlAutoguardado;
    use std::time::Duration;

    let mut control = ControlAutoguardado::nuevo();
    assert_eq!(
        control.minutos(),
        crate::autoguardado::MINUTOS_DE_AUTOGUARDADO_POR_DEFECTO,
        "de fábrica tiene que seguir comportándose como siempre"
    );

    control.fijar_minutos(5);
    assert_eq!(control.minutos(), 5);
    assert_eq!(control.intervalo(), Duration::from_secs(300));
    assert!(
        control.activo,
        "cinco minutos es un intervalo, no un apagado"
    );

    // El cero apaga, en vez de fijar un intervalo nulo que escribiría el mapa entero en
    // cada fotograma.
    control.fijar_minutos(0);
    assert!(!control.activo, "el cero tiene que apagar el autoguardado");
    assert_eq!(
        control.minutos(),
        0,
        "apagado, el intervalo que dice tener es cero: cualquier otro número no describe \
         lo que el programa hace"
    );
    assert!(
        !control.toca_comprobar(),
        "apagado no puede tocar comprobar nunca"
    );

    // Y se vuelve a encender eligiendo un intervalo.
    control.fijar_minutos(10);
    assert!(control.activo, "elegir un intervalo vuelve a encenderlo");
    assert_eq!(control.minutos(), 10);
}

/// Un intervalo que el programa no ofrece se ignora.
///
/// Las preferencias son un archivo de texto que cualquiera puede editar a mano. Un `0.5` o un
/// `100000` escritos ahí no pueden dejar el programa escribiendo el mapa sin parar, ni
/// aparentar que hay autoguardado cuando la siguiente copia sería dentro de dos meses.
#[test]
fn un_intervalo_de_autoguardado_que_no_se_ofrece_se_ignora() {
    use crate::autoguardado::ControlAutoguardado;

    for absurdo in [3, 7, 99, 100_000, u64::MAX] {
        let mut control = ControlAutoguardado::nuevo();
        let antes = control.minutos();

        control.fijar_minutos(absurdo);

        assert_eq!(
            control.minutos(),
            antes,
            "«{absurdo}» no está entre los intervalos ofrecidos y no debería cambiar nada"
        );
        assert!(control.activo, "y tampoco debería apagar el autoguardado");
    }
}

/// El menú ofrece los intervalos de autoguardado en los seis idiomas.
///
/// Y **nunca** dice «Cada 1 minutos»: el plural mal concordado delata un rótulo compuesto sin
/// mirar lo que decía, y es de las cosas que más ensucian una interfaz por lo demás cuidada.
#[test]
fn el_menu_ofrece_los_intervalos_de_autoguardado_en_los_seis_idiomas() {
    use crate::textos::{Idioma, Texto};

    for idioma in Idioma::TODOS {
        let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
        app.presentacion.preferencias.idioma = idioma;

        let pintados = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
            crate::ui::toolbar::menu_ver_y_diseno(app, ui);
        });

        for clave in [
            Texto::VerAutoguardado,
            Texto::AutoguardadoDesactivado,
            Texto::AutoguardadoCadaMinuto,
        ] {
            let esperado = clave.en(idioma);
            assert!(
                pintados.iter().any(|texto| texto.contains(esperado)),
                "en {idioma:?}, el menú no ofrece «{esperado}». Pintó: {pintados:?}"
            );
        }

        // El plural, con un número de verdad dentro y sin el hueco de la plantilla.
        let plural = Texto::AutoguardadoCadaNMinutos
            .en(idioma)
            .replacen("{}", "10", 1);
        assert!(
            pintados.iter().any(|texto| texto.contains(&plural)),
            "en {idioma:?}, el menú no ofrece «{plural}». Pintó: {pintados:?}"
        );
        assert!(
            !pintados.iter().any(|texto| texto.contains("{}")),
            "en {idioma:?} ha quedado un hueco de plantilla sin rellenar. Pintó: {pintados:?}"
        );

        // Y el singular mal concordado no aparece por ninguna parte.
        let mal = Texto::AutoguardadoCadaNMinutos
            .en(idioma)
            .replacen("{}", "1", 1);
        assert!(
            !pintados.iter().any(|texto| texto.contains(&mal)),
            "en {idioma:?} el menú dice «{mal}», con el plural mal concordado"
        );
    }
}

/// El temporizador respeta el intervalo elegido, no el de fábrica.
///
/// Es el fallo que no se vería de ninguna otra forma: si el temporizador siguiera mirando la
/// constante de dos minutos, elegir «cada 10 minutos» guardaría igualmente cada dos y todas
/// las demás pruebas seguirían en verde, porque el desplegable mostraría el 10 correctamente.
/// Solo se notaría esperando delante del programa, que es lo que ninguna batería hace.
#[test]
fn el_temporizador_respeta_el_intervalo_elegido_y_no_el_de_fabrica() {
    use crate::autoguardado::ControlAutoguardado;
    use std::time::Duration;

    let mut control = ControlAutoguardado::nuevo();

    control.fijar_minutos(1);
    assert!(
        !control.debe_comprobar_tras(Duration::from_secs(59)),
        "con un minuto elegido, a los 59 segundos todavía no toca"
    );
    assert!(
        control.debe_comprobar_tras(Duration::from_secs(61)),
        "con un minuto elegido, al pasar el minuto sí toca"
    );

    control.fijar_minutos(10);
    assert!(
        !control.debe_comprobar_tras(Duration::from_secs(3 * 60)),
        "con diez minutos elegidos, a los tres minutos no puede tocar: eso sería seguir \
         usando el intervalo de fábrica"
    );
    assert!(
        control.debe_comprobar_tras(Duration::from_secs(11 * 60)),
        "con diez minutos elegidos, a los once sí toca"
    );

    control.fijar_minutos(0);
    assert!(
        !control.debe_comprobar_tras(Duration::from_secs(60 * 60 * 24)),
        "apagado no toca nunca, por mucho tiempo que pase"
    );
}

/// Los paneles de la derecha no se ensanchan por encima de su máximo declarado.
///
/// El inspector declara `max_size(450.0)` y el panel de ayuda `max_size(550.0)`. Que se
/// respeten no es cosmético: los dos están anclados al borde derecho, así que un panel que
/// crece lo hace **hacia la izquierda**, se mete debajo del lienzo y pierde los primeros
/// píxeles de cada línea. Fue el defecto de la 0.8.1 en el «Inspector de Nodo».
///
/// # Qué cubre esta prueba, y qué cubre su hermana
///
/// Esta vigila el **tope**: que ningún panel supere su `max_size` declarado, en tres
/// resoluciones y con la ayuda abierta y cerrada. Verificada por mutación —subiendo el máximo
/// del inspector, cae—, así que mide lo que dice medir.
///
/// La reproducción del defecto de la 0.8.1 la hace
/// [`ninguna_fila_del_inspector_ensancha_el_panel_fotograma_tras_fotograma`], y hace falta
/// porque esta no lo vería: el ensanchamiento arranca muy por debajo del máximo —360 → 381,25
/// → 402,25 píxeles, unos 21 por fotograma— y no tocaría el tope de 450 hasta varios pases
/// después de que el usuario ya estuviera viendo el panel recortado.
///
/// La documentación que había aquí daba aquel defecto por irreproducible sobre el código de
/// hoy, y sospechaba que `egui` 0.36 hubiera dejado de permitir el ensanchamiento. **Las dos
/// cosas eran falsas**: el mecanismo sigue vigente y se reprodujo el 2026-09-06. Lo que
/// fallaba era medir un solo fotograma, cuando `egui` no aplica el ancho nuevo hasta el pase
/// siguiente.
#[test]
fn los_paneles_de_la_derecha_no_superan_su_ancho_maximo() {
    /// Lo que declaran `ui/sidebar.rs` para el inspector y para la ayuda detallada.
    const MAXIMO_DECLARADO: f32 = 550.0;

    let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    app.mapa.proyecto = crate::model::Proyecto::nuevo_ejemplo_juego_ahorcado(Idioma::Espanol);
    app.mapa.nodo_seleccionado = Some(app.mapa.proyecto.root_id);

    // Un nodo con una ruta larguísima es lo que más empuja al inspector: es el campo que
    // pide todo el ancho disponible.
    let raiz = app.mapa.proyecto.root_id;
    if let Some(nodo) = app.mapa.proyecto.nodes.get_mut(&raiz) {
        nodo.file_path = Some(
            "src/dominio/subsistemas/persistencia/adaptadores/repositorio_de_mapas_mentales.rs"
                .to_string(),
        );
    }

    for (ancho, alto) in [(1024.0, 768.0), (1920.0, 1080.0), (3840.0, 2160.0)] {
        let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(ancho, alto));

        for ayuda_abierta in [false, true] {
            app.presentacion.ventanas.panel_de_ayuda = ayuda_abierta;
            app.presentacion.guia_de_ayuda_activa =
                Some(crate::ui::help_system::TemaDeAyuda::ControlHumanoCorrecciones);

            let salida = crate::arnes_interfaz::ejecutar_fotograma_completo(&mut app, &ctx, rect);
            let anchos = crate::arnes_interfaz::anchos_de_los_paneles_de_la_derecha(&salida, ancho);

            for medido in &anchos {
                assert!(
                    *medido <= MAXIMO_DECLARADO + 1.0,
                    "a {ancho}x{alto} con la ayuda {}, un panel mide {medido} y su máximo es \
                     {MAXIMO_DECLARADO}: un panel anclado a la derecha que crece lo hace \
                     hacia la izquierda, se mete debajo del lienzo y recorta los \
                     primeros píxeles de cada línea",
                    if ayuda_abierta { "abierta" } else { "cerrada" }
                );
            }

            assert!(
                !anchos.is_empty(),
                "a {ancho}x{alto} no se midió ningún panel de la derecha: si el inspector                  dejó de dibujarse, esta prueba estaría pasando sin comprobar nada"
            );
        }
    }
}

/// Una aplicación de prueba no puede escribir en el disco del usuario. Ni queriendo.
///
/// Cierra `COD-009` por el lado que faltaba. La prueba que ya existía,
/// `la_aplicacion_de_prueba_esta_aislada_del_perfil_en_disco`, comprueba que el arnés **no
/// lee** la copia de recuperación del usuario. Esta comprueba lo simétrico y más peligroso:
/// que tampoco **escriba**.
///
/// No es hipotético. El 2026-09-06, una ejecución de esta misma batería dejó el idioma del
/// usuario puesto en chino y su `sugerencia_mostrada` en `false`, porque una prueba de
/// interfaz simulaba un clic en el menú de idioma y el manejador guardaba las preferencias
/// donde dijera la carpeta global.
///
/// La garantía es estructural, no una promesa: una aplicación de prueba nace **sin carpeta de
/// datos**, y las dos puertas de escritura preguntan por ella antes de tocar nada. Se
/// comprueba por comportamiento —lo que devuelven— y no mirando el campo, porque lo que
/// importa no es cómo está guardado sino que no escriba.
#[test]
fn una_aplicacion_de_prueba_no_puede_escribir_en_el_disco_del_usuario() {
    let (app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    assert!(
        app.guardar_preferencias().is_err(),
        "la aplicación de prueba ha guardado preferencias: si hay carpeta de datos, la          batería puede reescribir el idioma, el tema y la escala de quien la ejecute"
    );

    assert!(
        app.guardar_copia_de_recuperacion().is_err(),
        "la aplicación de prueba ha escrito una copia de recuperación: eso pisa el trabajo          sin guardar que el usuario tuviera de una sesión anterior"
    );
}

/// Guardar preferencias devuelve el error de escritura completo en vez de esconderlo en `false`.
#[test]
fn guardar_preferencias_conserva_la_causa_de_escritura() {
    use std::error::Error;

    let raiz = carpeta_temporal_contexto("preferencias-error-tipado");
    let obstaculo = raiz.join("no-es-una-carpeta");
    std::fs::write(&obstaculo, "archivo").expect("crear obstáculo");

    let error = crate::preferencias::Preferencias::default()
        .guardar_en(&obstaculo)
        .expect_err("no se puede crear preferencias dentro de un archivo");

    assert!(matches!(error, crate::error::AppError::Escritura { .. }));
    assert!(error.source().is_some(), "debe conservar std::io::Error");
    std::fs::remove_dir_all(raiz).expect("limpiar prueba de preferencias");
}

/// El texto técnico del registro incluye la cadena de causas, no solo el error exterior.
#[test]
fn el_registro_incluye_la_cadena_de_causas() {
    let error = crate::error::AppError::lectura(
        "mapa.mmcelt",
        std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "acceso denegado reproducido",
        ),
    );

    let registro = crate::error::descripcion_para_registro(&error, "abrir mapa");

    assert!(registro.contains("abrir mapa"));
    assert!(registro.contains("error de lectura"));
    assert!(registro.contains("acceso denegado reproducido"));
    assert!(registro.contains("Causas:"));
    assert!(registro.contains("Traza:"));
}

/// Solo tres módulos pueden preguntar dónde guarda sus datos el usuario.
///
/// `directorio_datos()` es la única función que mira el sistema —`%APPDATA%`, `XDG_DATA_HOME`,
/// `HOME`— y devuelve una carpeta real. Cada sitio que la llama es un sitio que puede escribir
/// en el perfil de quien ejecute el programa **o la batería**.
///
/// Por eso se cierra la lista: la resuelve `ui/mod.rs` al arrancar y la guarda; `preferencias`
/// y `error` la necesitan para su archivo; y `autoguardado` es quien la define. Nadie más.
/// Todo lo demás recibe la carpeta por parámetro.
#[test]
fn solo_los_modulos_autorizados_preguntan_donde_viven_los_datos_del_usuario() {
    /// Fuente y si tiene permiso para llamar a `directorio_datos()`.
    const FUENTES: [(&str, &str, bool); 8] = [
        ("autoguardado.rs", include_str!("autoguardado.rs"), true),
        ("preferencias.rs", include_str!("preferencias.rs"), true),
        ("error.rs", include_str!("error.rs"), true),
        ("ui/mod.rs", include_str!("ui/mod.rs"), true),
        ("ui/toolbar.rs", include_str!("ui/toolbar.rs"), false),
        ("ui/sidebar.rs", include_str!("ui/sidebar.rs"), false),
        ("ui/ai_modal.rs", include_str!("ui/ai_modal.rs"), false),
        ("storage.rs", include_str!("storage.rs"), false),
    ];

    for (nombre, fuente, autorizado) in FUENTES {
        let lo_llama = fuente_normalizado(fuente).contains("directorio_datos()");

        if autorizado {
            continue;
        }

        assert!(
            !lo_llama,
            "{nombre} llama a `directorio_datos()`. Ese módulo tiene que recibir la carpeta              por parámetro: cada sitio que la resuelve por su cuenta es un sitio por donde la              batería puede volver a escribir en el perfil real de quien la ejecuta"
        );
    }
}

/// El ancho del inspector no crece fotograma tras fotograma por una fila que desborda.
///
/// # Qué defecto vigila
///
/// Es la reproducción del defecto de la 0.8.1, que hasta hoy no tenía prueba. El «Inspector
/// de Nodo» está anclado al borde derecho, así que un panel que se ensancha lo hace **hacia
/// la izquierda**: se mete debajo del lienzo, que se dibuja después, y el usuario ve los
/// rótulos cortados por delante. No es cosmético: ahí es donde escribe el título, las notas
/// y la ruta del archivo de su nodo.
///
/// La causa está descrita en `ui::sidebar::dibujar_la_ruta_del_archivo`: si el campo con
/// `desired_width(f32::INFINITY)` se añade **antes** que el botón «+info» y sin el
/// `with_layout(right_to_left)` que reparte de derecha a izquierda, el campo se queda con
/// todo el ancho libre, el botón ya no cabe y `egui` ensancha el `Ui` para meterlo.
///
/// # Por qué hacen falta varios fotogramas
///
/// **Este es el motivo de que el defecto se diera por irreproducible durante tres intentos.**
/// El ensanchamiento no se ve en el fotograma en que se produce: `egui` mide el desborde al
/// cerrar el `Panel` y lo guarda en su estado, de modo que el ancho nuevo no se aplica hasta
/// el fotograma **siguiente**. Un arnés que dibuja una sola vez mide siempre 360 píxeles y
/// concluye, en falso, que no pasa nada.
///
/// Medido el 2026-09-06 reponiendo la causa: fotograma 1 → 360,0; fotograma 2 → 381,25;
/// fotograma 3 → 402,25; fotograma 4 → 423,25. Crece unos 21 píxeles por fotograma hasta
/// toparse con el `max_size` del panel.
///
/// Por eso esta prueba no comprueba un ancho concreto, sino la **estabilidad** del ancho a
/// lo largo de varios fotogramas seguidos sobre el mismo contexto. Un panel sano mide
/// siempre lo mismo; uno que desborda, crece en cada pase.
///
/// # Verificación por mutación
///
/// Se la ha visto fallar. Reponiendo la causa en `ui::sidebar::dibujar_la_ruta_del_archivo`
/// —quitar el `with_layout(right_to_left)` y dejar el `TextEdit` antes del botón dentro del
/// `ui.horizontal`—, cae en el fotograma 2 con «pasó de [360.0] a [381.25, 369.0]».
/// Restaurado el orden correcto, vuelve a verde.
#[test]
fn ninguna_fila_del_inspector_ensancha_el_panel_fotograma_tras_fotograma() {
    /// Cuántos pases seguidos se dibujan sobre el mismo contexto.
    ///
    /// Con dos bastaría para ver el salto, pero cuatro dejan constancia de que el
    /// crecimiento es acumulativo y no un reajuste único del primer dibujado.
    const FOTOGRAMAS: usize = 4;

    /// Margen de tolerancia al comparar anchos, en píxeles.
    ///
    /// El medidor deduce el ancho de las regiones de recorte, que son valores en coma
    /// flotante. Medio píxel absorbe el redondeo sin dejar pasar un ensanchamiento real:
    /// el más pequeño observado es de 21 píxeles.
    const TOLERANCIA: f32 = 0.5;

    for (ancho, alto) in [(1024.0, 768.0), (1920.0, 1080.0)] {
        let (mut app, ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
        app.mapa.proyecto = crate::model::Proyecto::nuevo_ejemplo_juego_ahorcado(Idioma::Espanol);
        app.mapa.nodo_seleccionado = Some(app.mapa.proyecto.root_id);

        // Una ruta larga es lo que más empuja al inspector: es el campo que pide todo el
        // ancho disponible, y el que provocaba el defecto.
        let raiz = app.mapa.proyecto.root_id;
        if let Some(nodo) = app.mapa.proyecto.nodes.get_mut(&raiz) {
            nodo.file_path = Some(
                "src/dominio/subsistemas/persistencia/adaptadores/repositorio_de_mapas_mentales.rs"
                    .to_string(),
            );
        }

        let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(ancho, alto));

        let mut medidos: Vec<Vec<f32>> = Vec::with_capacity(FOTOGRAMAS);
        for _ in 0..FOTOGRAMAS {
            let salida = crate::arnes_interfaz::ejecutar_fotograma_completo(&mut app, &ctx, rect);
            medidos.push(crate::arnes_interfaz::anchos_de_los_paneles_de_la_derecha(
                &salida, ancho,
            ));
        }

        let primero = &medidos[0];

        // Si el inspector dejara de dibujarse, todas las medidas serían listas vacías,
        // todas iguales entre sí, y la prueba pasaría sin haber comprobado nada.
        assert!(
            !primero.is_empty(),
            "a {ancho}x{alto} no se midió ningún panel anclado a la derecha: el inspector no              se está dibujando y esta prueba no estaría comprobando nada"
        );

        for (posicion, actual) in medidos.iter().enumerate().skip(1) {
            let estable = actual.len() == primero.len()
                && actual
                    .iter()
                    .zip(primero.iter())
                    .all(|(uno, otro)| (uno - otro).abs() <= TOLERANCIA);

            assert!(
                estable,
                "a {ancho}x{alto} el panel de la derecha se ensanchó entre fotogramas: pasó de                  {primero:?} a {actual:?} en el fotograma {}. Una fila del inspector desborda                  su ancho disponible y `egui` engorda el panel en el pase siguiente; como está                  anclado al borde derecho, crece hacia la izquierda, queda debajo del lienzo y                  recorta los primeros píxeles de cada línea",
                posicion + 1
            );
        }
    }
}

/// Ninguna operación del hilo de la interfaz se sale de su presupuesto de tiempo.
///
/// # Qué vigila, y por qué existe en vez de un hilo de trabajo
///
/// MMCelt no bloquea el hilo principal con operaciones síncronas **pesadas**. La lectura de cambios externos y el recorrido completo de «Enviar a…» ya viven en
/// trabajadores estables. Permanecen síncronos el escaneo que la persona inicia desde un diálogo,
/// el autoguardado periódico y la composición en memoria del Markdown; por eso sus topes se miden.
///
/// Antes de meter concurrencia se midió, el 2026-09-06, cuánto cuestan de verdad:
///
/// | Operación | Coste medido |
/// |---|---|
/// | Escaneo del repositorio de MMCelt (75 nodos) | 53 ms |
/// | Escaneo de una carpeta con 689 entradas | 21 ms |
/// | Guardado en disco local | 2,5 ms |
/// | Guardado en una unidad de Google Drive | 2,7 ms |
/// | Exportación a Markdown (24 KB) | 1,5 ms |
///
/// El guardado y la exportación no se notan. El escaneo cuesta unos tres fotogramas de los
/// sesenta de un segundo, ocurre **una sola vez** y justo después de que el usuario cierre el
/// diálogo del sistema con el que elige la carpeta, que es donde ya estaba esperando.
///
/// Con esos números, añadir más concurrencia al escaneo iniciado expresamente o a una composición
/// de 1,5 ms no compra fluidez: compra cancelación y condiciones de carrera. La lectura reactiva sí
/// podía llegar desde una unidad lenta sin que la persona la iniciase, y preparar un envío encadena
/// varias escrituras y un proceso; esas dos rutas son las que se sacaron del fotograma.
///
/// **Lo que no se puede es dejar de mirarlo**, que es lo que pasaba antes: la decisión se
/// apoyaba en una suposición. Esta prueba la convierte en una medición que se repite sola. Si
/// alguien quita el tope de profundidad, deja de excluir `node_modules` o mete una lectura del
/// contenido de cada archivo, el coste sube un orden de magnitud y esto lo dice.
///
/// # Por qué los topes son tan holgados
///
/// Porque una prueba de tiempo que aprieta se vuelve intermitente en cuanto la CI comparte la
/// máquina, y una prueba que falla sola acaba ignorada. Estos topes son entre veinte y
/// cuarenta veces lo medido: no detectan una regresión pequeña, y no pretenden hacerlo.
/// Detectan que algo ha pasado de milisegundos a segundos.
#[test]
fn las_operaciones_del_hilo_de_la_interfaz_siguen_costando_milisegundos() {
    use std::time::Instant;

    /// Tope para el escaneo de una carpeta de código. Medido: 21-53 ms.
    const TOPE_ESCANEO: std::time::Duration = std::time::Duration::from_millis(2_000);
    /// Tope para guardar el mapa en disco. Medido: 2,5-2,7 ms.
    const TOPE_GUARDADO: std::time::Duration = std::time::Duration::from_millis(500);
    /// Tope para componer el documento que se le entrega a la IA. Medido: 1,5 ms.
    const TOPE_EXPORTACION: std::time::Duration = std::time::Duration::from_millis(500);

    /// Carpetas del árbol de prueba, y archivos dentro de cada una.
    ///
    /// Se construye aquí en vez de escanear el repositorio para que la medida no dependa de
    /// cuántos archivos tenga quien ejecute la batería.
    const CARPETAS: usize = 12;
    const ARCHIVOS_POR_CARPETA: usize = 40;

    let raiz = std::env::temp_dir().join(format!("mmcelt-coste-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&raiz);
    std::fs::create_dir_all(&raiz).expect("no se pudo crear el árbol de prueba");

    for carpeta in 0..CARPETAS {
        let ruta = raiz.join(format!("modulo_{carpeta}")).join("interno");
        std::fs::create_dir_all(&ruta).expect("no se pudo crear una subcarpeta");
        for archivo in 0..ARCHIVOS_POR_CARPETA {
            std::fs::write(
                ruta.join(format!("fuente_{archivo}.rs")),
                b"// prueba
",
            )
            .expect("no se pudo crear un archivo");
        }
    }

    let inicio = Instant::now();
    let proyecto = crate::model::Proyecto::desde_escaneo_de_carpeta(&raiz, Idioma::Espanol)
        .expect("el escaneo del árbol de prueba no debería fallar");
    let escaneo = inicio.elapsed();

    let destino = raiz.join("medicion.mmcelt");
    let inicio = Instant::now();
    crate::storage::guardar_proyecto_en_archivo(&proyecto, &destino).expect("no se pudo guardar");
    let guardado = inicio.elapsed();

    let inicio = Instant::now();
    let markdown = crate::ai_export::exportar_markdown_para_ia(&proyecto, Idioma::Espanol);
    let exportacion = inicio.elapsed();

    let _ = std::fs::remove_dir_all(&raiz);

    // Si el escaneo dejara de recorrer nada, todo sería instantáneo y la prueba pasaría sin
    // haber medido nada.
    assert!(
        proyecto.nodes.len() > CARPETAS,
        "el escaneo solo encontró {} nodos sobre un árbol de {CARPETAS} carpetas: no está          recorriendo el árbol y esta prueba no estaría midiendo nada",
        proyecto.nodes.len()
    );
    assert!(
        !markdown.is_empty(),
        "la exportación salió vacía: no se está midiendo el coste de componerla"
    );

    assert!(
        escaneo < TOPE_ESCANEO,
        "escanear {CARPETAS} carpetas con {ARCHIVOS_POR_CARPETA} archivos costó {escaneo:?},          por encima del tope de {TOPE_ESCANEO:?}. Ocurre en el hilo que dibuja la interfaz, así          que a partir de aquí el usuario ve la ventana congelada: o se vuelve a acotar el          recorrido, o toca sacarlo a un hilo de trabajo"
    );
    assert!(
        guardado < TOPE_GUARDADO,
        "guardar el mapa costó {guardado:?}, por encima del tope de {TOPE_GUARDADO:?}. El          autoguardado lo hace solo cada pocos minutos y sin avisar: si tarda, la aplicación se          queda quieta sin que el usuario haya pedido nada"
    );
    assert!(
        exportacion < TOPE_EXPORTACION,
        "componer el documento para la IA costó {exportacion:?}, por encima del tope de          {TOPE_EXPORTACION:?}. Se rehace cada vez que cambia el mapa con una vista previa          abierta"
    );
}

/// Las tres operaciones básicas para construir un mapa tienen botón visible en el inspector.
///
/// Un mapa crece de tres maneras: colgando un hijo, añadiendo un hermano y cruzando dos ramas
/// con una conexión. Las dos primeras tuvieron botón desde el principio; la tercera vivió
/// enterrada en el menú «Edición», de modo que quien abría el programa veía dos de las tres y
/// podía concluir razonablemente que la tercera no existía.
///
/// No es un descuido cosmético. Antes de que se arreglara, la conexión cruzada **no se podía
/// crear desde el programa**: el modal se cerraba en el mismo fotograma en que se abría, y las
/// conexiones que había en los mapas llegaban importadas de una IA, de un ejemplo o de editar
/// el archivo a mano. Una función que primero no funciona y después no se ve tiene todas las
/// papeletas para que nadie note nunca su ausencia.
///
/// El usuario lo pidió y la petición se perdió porque no quedó anotada en ninguna parte. Esta
/// prueba es lo que impide que se vuelva a perder: quitar cualquiera de los tres botones pone
/// la batería en rojo.
///
/// Se mira el fuente **normalizado**, no el archivo tal cual, para que comentar el botón no
/// deje la prueba en verde. Ese error ya se cometió aquí con `origen_de_la_conexion`.
#[test]
fn las_tres_operaciones_basicas_del_mapa_tienen_boton_en_el_inspector() {
    let inspector = fuente_normalizado(include_str!("ui/sidebar.rs"));

    for (variante, operacion) in [
        ("InspectorBotonHijo", "colgar un hijo"),
        ("InspectorBotonHermano", "añadir un hermano"),
        ("InspectorBotonConexion", "crear una conexión cruzada"),
    ] {
        assert!(
            inspector.contains(variante),
            "el inspector no ofrece un botón para {operacion}: falta `Texto::{variante}` en \
             `ui/sidebar.rs`. Las tres formas de hacer crecer un mapa se ofrecen juntas o el \
             usuario se queda sin saber que la que falta existe"
        );
    }
}

/// Extrae de un documento los rótulos de interfaz que cita entre acentos graves.
///
/// Solo devuelve los que empiezan por un símbolo visual de las tablas Unicode donde viven los
/// iconos usados por MMCelt. Así quedan fuera los atajos, nombres de archivo y palabras normales
/// escritas en alfabetos no latinos.
///
/// Las rutas de menú se parten por su flecha, porque `A → B` son dos rótulos distintos y cada
/// uno tiene que existir por separado.
fn rotulos_de_interfaz_citados(documento: &str) -> Vec<String> {
    let mut citados = Vec::new();
    for (indice, trozo) in documento.split('`').enumerate() {
        // Los índices pares quedan fuera de los acentos graves; los trozos con salto de línea
        // son bloques de código, no citas de un rótulo.
        if indice % 2 == 0 || trozo.contains('\n') {
            continue;
        }
        for tramo in trozo.split(['→', '>']) {
            let limpio = normalizar_rotulo(tramo);
            if limpio.chars().count() >= 4
                && limpio
                    .chars()
                    .next()
                    .is_some_and(es_inicio_de_rotulo_visual)
            {
                citados.push(limpio);
            }
        }
    }
    citados
}

/// Distingue los pictogramas y símbolos iniciales de una letra corriente de cualquier alfabeto.
///
/// MMCelt usa símbolos de las tablas Unicode «Arrows», «Miscellaneous Symbols», «Dingbats» y los
/// bloques modernos de pictogramas. Comprobar simplemente `!is_ascii()` clasificaría como icono
/// cada palabra rusa o china.
fn es_inicio_de_rotulo_visual(caracter: char) -> bool {
    matches!(
        caracter,
        '\u{2190}'..='\u{2BFF}' | '\u{1F300}'..='\u{1FAFF}'
    )
}

/// El alfabeto de un idioma no convierte una expresión normal en un botón de la interfaz.
#[test]
fn el_extractor_no_confunde_cirilico_ni_chino_con_un_icono() {
    let documento = "`Двойной клик` y `双击`, pero sí `🤖 Искусственный интеллект`";
    assert_eq!(
        rotulos_de_interfaz_citados(documento),
        vec!["🤖 Искусственный интеллект"]
    );
}

/// Deja un rótulo en la forma comparable: sin énfasis de Markdown y con los espacios colapsados.
///
/// El énfasis se quita porque el mismo rótulo aparece con asteriscos en las plantillas de
/// Markdown y sin ellos en los menús. La puntuación visible se conserva porque forma parte del
/// nombre que la persona debe localizar en la interfaz.
fn normalizar_rotulo(bruto: &str) -> String {
    normalizar_rotulo_exacto(bruto)
}

/// Una referencia de la ayuda debe conservar la puntuación que distingue el rótulo visible.
#[test]
fn la_ayuda_no_confunde_rotulos_con_puntos_suspensivos_distintos() {
    assert_ne!(
        normalizar_rotulo("📤 Enviar a..."),
        normalizar_rotulo("📤 Enviar a…")
    );
}

/// La documentación no manda al usuario a un rótulo que el programa no pinta.
///
/// El manual y la ayuda le dicen a una persona dónde pulsar. Cuando un rótulo cambia en la
/// interfaz y nadie actualiza el texto, esa persona abre el menú, no encuentra lo que se le
/// prometió y se queda ahí: no hay error, no hay aviso, y la batería sigue en verde.
///
/// No es hipotético. El 2026-09-10 se encontraron cuatro citas de un menú llamado «🤖 IA» que en
/// realidad se llama «🤖 Inteligencia Artificial», y la entrada de exportación citada con el
/// emoji equivocado. Los encontró una revisión a mano; esta prueba es para que la próxima vez no
/// haga falta.
///
/// Se recorren **los seis idiomas**: una traducción también puede citar un botón que en su idioma
/// no existe, y ahí el castellano no ayuda.
///
/// **Lo que esta prueba no puede ver**, y conviene saberlo: comprueba que cada rótulo exista, no
/// que la ruta sea correcta. Esa relación necesita una prueba específica como
/// `la_ayuda_indica_la_ruta_real_para_exportar_markdown`.
#[test]
fn ninguna_documentacion_cita_un_rotulo_que_el_programa_no_pinta() {
    use crate::model::{EstadoNodo, EstadoRevision, PrioridadNodo, RolNodo, TipoRelacion};
    use crate::textos::{Idioma, Texto};
    use crate::ui::help_system::TemaDeAyuda;
    let mut desajustes: Vec<String> = Vec::new();

    for idioma in Idioma::TODOS {
        // Todo lo que el programa es capaz de pintar en este idioma, en un solo corpus.
        let mut pintables: Vec<String> = Vec::new();
        for texto in Texto::TODOS {
            pintables.push(normalizar_rotulo(texto.en(idioma)));
        }
        for estado in EstadoNodo::TODOS {
            pintables.push(normalizar_rotulo(estado.nombre_para_interfaz(idioma)));
        }
        for revision in EstadoRevision::TODOS {
            pintables.push(normalizar_rotulo(revision.nombre_para_interfaz(idioma)));
        }
        for prioridad in PrioridadNodo::TODOS {
            pintables.push(normalizar_rotulo(prioridad.nombre_para_interfaz(idioma)));
        }
        for rol in RolNodo::TODOS {
            pintables.push(normalizar_rotulo(rol.nombre_para_interfaz(idioma)));
        }
        for relacion in TipoRelacion::TODOS {
            pintables.push(normalizar_rotulo(relacion.nombre_para_interfaz(idioma)));
        }
        for tema in TemaDeAyuda::TODOS {
            pintables.push(normalizar_rotulo(crate::ui::ayuda_textos::titulo_de(
                tema, idioma,
            )));
        }

        for tema in TemaDeAyuda::TODOS {
            let guia = crate::ui::ayuda_textos::guia_de(tema, idioma);
            for citado in rotulos_de_interfaz_citados(guia) {
                if !pintables.iter().any(|real| real.contains(&citado)) {
                    let sugerencia = mas_parecido(&citado, &pintables);
                    desajustes.push(format!(
                        "  {idioma:?} / {tema:?}: dice «{citado}» — el programa pinta «{sugerencia}»"
                    ));
                }
            }
        }
    }

    // Se acumulan todos antes de fallar. Corregir de uno en uno obliga a recompilar por cada
    // desajuste, y lo que hace falta al arreglar la documentación es la lista entera.
    assert!(
        desajustes.is_empty(),
        "la documentación manda al usuario a {} rótulos que el programa no pinta:
{}",
        desajustes.len(),
        desajustes.join(
            "
"
        )
    );
}

/// Devuelve el rótulo real que más se parece a uno citado, para poder sugerirlo al fallar.
///
/// Un mensaje que solo dice «esto no existe» obliga a buscar a mano en seis idiomas. Uno que
/// dice «quisiste decir esto otro» convierte la corrección en un reemplazo.
///
/// La cercanía se mide por palabras compartidas, que basta para este uso: los desajustes reales
/// son rótulos que cambiaron una palabra o el emoji, no textos distintos.
fn mas_parecido(citado: &str, candidatos: &[String]) -> String {
    let palabras_citadas: Vec<&str> = citado
        .split_whitespace()
        .filter(|p| p.chars().any(char::is_alphanumeric))
        .collect();

    let mut mejor = String::from("(ninguno parecido)");
    let mut mejor_puntuacion = 0usize;
    for candidato in candidatos {
        let puntuacion = palabras_citadas
            .iter()
            .filter(|palabra| candidato.contains(*palabra))
            .count();
        if puntuacion > mejor_puntuacion {
            mejor_puntuacion = puntuacion;
            mejor = candidato.clone();
        }
    }
    mejor
}

/// La ayuda cita el rótulo canónico del concepto que explica, no cualquier texto parecido.
///
/// La comprobación genérica garantiza que un rótulo exista en algún punto de la interfaz. Esta
/// tabla añade la relación semántica que aquella comprobación no puede deducir.
#[test]
fn cada_tema_cita_los_conceptos_que_explica() {
    use crate::model::{EstadoNodo, EstadoRevision};
    use crate::textos::{Idioma, Texto};
    use crate::ui::help_system::TemaDeAyuda;

    let mut ausentes = Vec::new();
    for idioma in Idioma::TODOS {
        let mut casos = vec![
            (
                TemaDeAyuda::ControlHumanoCorrecciones,
                EstadoRevision::RequiereCorreccion.nombre_para_interfaz(idioma),
            ),
            (
                TemaDeAyuda::ControlHumanoCorrecciones,
                EstadoRevision::AprobadoPorHumano.nombre_para_interfaz(idioma),
            ),
            (
                TemaDeAyuda::ControlHumanoCorrecciones,
                EstadoRevision::PendienteRevision.nombre_para_interfaz(idioma),
            ),
            (
                TemaDeAyuda::ControlHumanoCorrecciones,
                EstadoNodo::Descartado.nombre_para_interfaz(idioma),
            ),
            (
                TemaDeAyuda::ControlHumanoCorrecciones,
                Texto::IaEnviarCorrecciones.en(idioma),
            ),
            (
                TemaDeAyuda::ControlHumanoCorrecciones,
                Texto::ModalCopiarDirectivasDeCorreccion.en(idioma),
            ),
            (
                TemaDeAyuda::ModosDeDisposicion,
                Texto::VerReorganizarLosNodos.en(idioma),
            ),
            (
                TemaDeAyuda::ImportarDesdeIA,
                Texto::ModalSustituirElMapaPor.en(idioma),
            ),
            (
                TemaDeAyuda::ImportarDesdeIA,
                Texto::MenuInteligenciaArtificial.en(idioma),
            ),
            (
                TemaDeAyuda::ImportarDesdeIA,
                Texto::IaCopiarPromptMaestro.en(idioma),
            ),
            (
                TemaDeAyuda::ImportarDesdeIA,
                Texto::IaImportarDesdeIa.en(idioma),
            ),
            (
                TemaDeAyuda::ExportarMarkdownIA,
                Texto::MenuArchivo.en(idioma),
            ),
            (
                TemaDeAyuda::ExportarMarkdownIA,
                Texto::ArchivoExportarMarkdown.en(idioma),
            ),
            (
                TemaDeAyuda::EscanerDeRepositorios,
                Texto::MenuArchivo.en(idioma),
            ),
            (
                TemaDeAyuda::EscanerDeRepositorios,
                Texto::ArchivoEscanearCarpeta.en(idioma),
            ),
            (
                TemaDeAyuda::PlantillasDeSoftware,
                Texto::MenuArchivo.en(idioma),
            ),
            (
                TemaDeAyuda::PlantillasDeSoftware,
                Texto::ArchivoPlantillas.en(idioma),
            ),
            (TemaDeAyuda::VisionDelCreador, Texto::MenuEdicion.en(idioma)),
            (
                TemaDeAyuda::VisionDelCreador,
                Texto::ModalProyectoEInstruccionesIa.en(idioma),
            ),
            (
                TemaDeAyuda::PrimerosPasos,
                Texto::ModalProyectoEInstruccionesIa.en(idioma),
            ),
            (
                TemaDeAyuda::ColoresDelMapa,
                Texto::MenuVerYDiseno.en(idioma),
            ),
            (TemaDeAyuda::ColoresDelMapa, Texto::VerTemaVisual.en(idioma)),
            (
                TemaDeAyuda::GuardadoYRecuperacion,
                Texto::MenuVerYDiseno.en(idioma),
            ),
            (
                TemaDeAyuda::GuardadoYRecuperacion,
                Texto::VerAutoguardado.en(idioma),
            ),
            (
                TemaDeAyuda::ConexionesCruzadas,
                Texto::EdicionCrearConexionCruzada.en(idioma),
            ),
        ];

        casos.extend(EstadoNodo::TODOS.map(|estado| {
            (
                TemaDeAyuda::EstadosYProgreso,
                estado.nombre_para_interfaz(idioma),
            )
        }));

        for (tema, rotulo) in casos {
            let guia = normalizar_rotulo(crate::ui::ayuda_textos::guia_de(tema, idioma));
            let rotulo = normalizar_rotulo(rotulo);
            if !guia.contains(&rotulo) {
                ausentes.push(format!("{idioma:?}/{tema:?}: {rotulo}"));
            }
        }
    }

    assert!(
        ausentes.is_empty(),
        "la ayuda no conserva el significado de {} rótulos:\n{}",
        ausentes.len(),
        ausentes.join("\n")
    );
}

/// Las rutas críticas se comprueban como pares ordenados de menú y acción.
///
/// Saber que ambos rótulos existen por separado no demuestra que la ayuda conduzca al menú donde
/// se dibuja realmente la acción.
#[test]
fn la_ayuda_indica_la_ruta_real_para_exportar_markdown() {
    use crate::textos::{Idioma, Texto};
    use crate::ui::help_system::TemaDeAyuda;

    for idioma in Idioma::TODOS {
        let guia = crate::ui::ayuda_textos::guia_de(TemaDeAyuda::ExportarMarkdownIA, idioma);
        let guia = normalizar_rotulo(guia);
        let menu = normalizar_rotulo(Texto::MenuArchivo.en(idioma));
        let accion = normalizar_rotulo(Texto::ArchivoExportarMarkdown.en(idioma));
        let ruta = format!("`{menu}` > `{accion}`");
        assert!(
            guia.contains(&ruta),
            "la ruta de exportación no coincide con Archivo en {idioma:?}"
        );
    }
}

/// Los manuales vigentes no mandan pulsar controles que la interfaz no ofrece.
///
/// La ayuda integrada tiene sus propias barreras, pero estos cuatro documentos también guían al
/// usuario por la interfaz. Se recorren las citas entre acentos graves y comillas angulares. Una
/// cita se considera un control si empieza por un símbolo visual, coincide con un rótulo sin su
/// icono o solo se diferencia de él por el icono o los puntos suspensivos. Las citas arbitrarias
/// sin relación reconocible con ningún control quedan fuera: el formato Markdown no permite
/// deducir por sí solo que cualquier palabra entre comillas sea una acción de la aplicación.
#[test]
fn los_manuales_vigentes_usan_los_rotulos_reales_de_la_interfaz() {
    use crate::model::{
        EstadoNodo, EstadoRevision, ModoDisposicion, PrioridadNodo, RolNodo, TipoRelacion,
    };
    use crate::textos::{Idioma, Texto};
    use crate::theme::AppThemeMode;
    use crate::ui::help_system::TemaDeAyuda;

    let idioma = Idioma::Espanol;
    let documentos = [
        (
            "manual-de-uso.md",
            include_str!("../documentacion/manual-de-uso.md"),
        ),
        (
            "funcionalidades.md",
            include_str!("../documentacion/funcionalidades.md"),
        ),
        (
            "integraciones/manual-de-control-ia.md",
            include_str!("../documentacion/integraciones/manual-de-control-ia.md"),
        ),
        (
            "infraestructura/servicios.md",
            include_str!("../documentacion/infraestructura/servicios.md"),
        ),
    ];

    let mut rotulos_reales = std::collections::BTreeSet::new();
    rotulos_reales.extend(Texto::TODOS.map(|texto| normalizar_rotulo_exacto(texto.en(idioma))));
    rotulos_reales.extend(
        EstadoNodo::TODOS.map(|valor| normalizar_rotulo_exacto(valor.nombre_para_interfaz(idioma))),
    );
    rotulos_reales.extend(
        EstadoRevision::TODOS
            .map(|valor| normalizar_rotulo_exacto(valor.nombre_para_interfaz(idioma))),
    );
    rotulos_reales.extend(
        PrioridadNodo::TODOS
            .map(|valor| normalizar_rotulo_exacto(valor.nombre_para_interfaz(idioma))),
    );
    rotulos_reales.extend(
        RolNodo::TODOS.map(|valor| normalizar_rotulo_exacto(valor.nombre_para_interfaz(idioma))),
    );
    rotulos_reales.extend(TipoRelacion::TODOS.map(|valor| {
        normalizar_rotulo_exacto(&format!(
            "{} {}",
            valor.simbolo(),
            valor.nombre_para_interfaz(idioma)
        ))
    }));
    rotulos_reales.extend(
        [
            ModoDisposicion::HorizontalTree,
            ModoDisposicion::RadialTree,
            ModoDisposicion::FreeDrag,
        ]
        .map(|valor| normalizar_rotulo_exacto(valor.nombre_para_interfaz(idioma))),
    );
    rotulos_reales.extend(
        AppThemeMode::TODOS
            .map(|valor| normalizar_rotulo_exacto(valor.nombre_para_interfaz(idioma))),
    );
    rotulos_reales
        .extend(TemaDeAyuda::TODOS.map(|tema| {
            normalizar_rotulo_exacto(crate::ui::ayuda_textos::titulo_de(tema, idioma))
        }));
    rotulos_reales.extend(
        nombres_de_agentes_detectables()
            .into_iter()
            .map(|nombre| normalizar_rotulo_exacto(&nombre)),
    );

    let mut heredados = Vec::new();
    for (ruta, contenido) in documentos {
        for citado in rotulos_de_interfaz_citados_exactos(contenido) {
            let empieza_por_icono = citado
                .chars()
                .next()
                .is_some_and(es_inicio_de_rotulo_visual);
            let coincide_sin_icono = rotulos_reales
                .iter()
                .any(|real| quitar_icono_inicial(real) == citado);
            let equivalente_flexible = rotulos_reales.iter().any(|real| {
                normalizar_sin_icono_ni_elipsis(real) == normalizar_sin_icono_ni_elipsis(&citado)
            });
            let es_cita_de_control =
                empieza_por_icono || coincide_sin_icono || equivalente_flexible;
            let coincide_exactamente = rotulos_reales.contains(&citado) || coincide_sin_icono;

            if es_cita_de_control && !coincide_exactamente {
                heredados.push(format!("{ruta}: «{citado}»"));
            }
        }
    }

    assert!(
        heredados.is_empty(),
        "los manuales vigentes citan {} rótulos que la interfaz no pinta:\n{}",
        heredados.len(),
        heredados.join("\n")
    );
}

/// Extrae citas breves de los manuales conservando toda la puntuación visible.
fn rotulos_de_interfaz_citados_exactos(documento: &str) -> Vec<String> {
    let mut citados = Vec::new();
    for (indice, trozo) in documento.split('`').enumerate() {
        if indice % 2 == 0 || trozo.contains('\n') {
            continue;
        }
        for tramo in trozo.split(['→', '>']) {
            let limpio = normalizar_rotulo_exacto(tramo);
            if limpio.chars().count() >= 4 {
                citados.push(limpio);
            }
        }
    }

    let mut resto = documento;
    while let Some((_, despues_de_apertura)) = resto.split_once('«') {
        let Some((contenido, despues_de_cierre)) = despues_de_apertura.split_once('»') else {
            break;
        };
        for tramo in contenido.split(['→', '>']) {
            let limpio = normalizar_rotulo_exacto(tramo);
            if limpio.chars().count() >= 4 {
                citados.push(limpio);
            }
        }
        resto = despues_de_cierre;
    }
    citados
}

/// Quita únicamente el énfasis Markdown y colapsa espacios; la puntuación visible es contrato.
fn normalizar_rotulo_exacto(bruto: &str) -> String {
    bruto
        .replace('*', " ")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

/// Retira el pictograma inicial y su selector de variante para comparar una mención abreviada.
fn quitar_icono_inicial(rotulo: &str) -> &str {
    let rotulo = rotulo.trim();
    let Some(inicial) = rotulo.chars().next() else {
        return rotulo;
    };
    if !es_inicio_de_rotulo_visual(inicial) {
        return rotulo;
    }

    rotulo[inicial.len_utf8()..]
        .trim_start_matches('\u{FE0F}')
        .trim_start()
}

/// Forma auxiliar que permite reconocer un control aunque la cita use otro tipo de elipsis.
fn normalizar_sin_icono_ni_elipsis(rotulo: &str) -> String {
    quitar_icono_inicial(rotulo)
        .replace('…', "")
        .replace("...", "")
        .trim()
        .to_string()
}

/// Las dos formas de cita usadas por los manuales llegan al barrido de rótulos.
#[test]
fn el_extractor_exacto_reconoce_rotulos_sin_icono_y_comillas_angulares() {
    let documento = "Pulsa `Enviar a… → Claude Code` y después «🤖 Botón inexistente».";
    assert_eq!(
        rotulos_de_interfaz_citados_exactos(documento),
        vec!["Enviar a…", "Claude Code", "🤖 Botón inexistente"]
    );
}

/// Los manuales conservan los conceptos esenciales aunque todos sus rótulos restantes existan.
#[test]
fn los_manuales_conservan_los_recorridos_criticos() {
    use crate::model::{EstadoRevision, TipoRelacion};
    use crate::textos::{Idioma, Texto};

    let idioma = Idioma::Espanol;
    let manual = include_str!("../documentacion/manual-de-uso.md");
    let funcionalidades = include_str!("../documentacion/funcionalidades.md");
    let control_ia = include_str!("../documentacion/integraciones/manual-de-control-ia.md");
    let servicios = include_str!("../documentacion/infraestructura/servicios.md");
    let dependencia = format!(
        "{} {}",
        TipoRelacion::Dependencia.simbolo(),
        TipoRelacion::Dependencia.nombre_para_interfaz(idioma)
    );
    let ruta_prompt = format!(
        "`{}` → `{}`",
        Texto::MenuInteligenciaArtificial.en(idioma),
        Texto::IaCopiarPromptMaestro.en(idioma)
    );
    let exigidos = [
        (
            "manual de uso/aprobación humana",
            manual,
            EstadoRevision::AprobadoPorHumano.nombre_para_interfaz(idioma),
        ),
        ("manual de uso/dependencia", manual, dependencia.as_str()),
        (
            "funcionalidades/dependencia",
            funcionalidades,
            dependencia.as_str(),
        ),
        (
            "control de IA/correcciones",
            control_ia,
            Texto::IaEnviarCorrecciones.en(idioma),
        ),
        (
            "control de IA/importación",
            control_ia,
            Texto::IaImportarDesdeIa.en(idioma),
        ),
        (
            "control de IA/sustitución",
            control_ia,
            Texto::ModalSustituirElMapaPor.en(idioma),
        ),
        (
            "control de IA/revisión",
            control_ia,
            EstadoRevision::RequiereCorreccion.nombre_para_interfaz(idioma),
        ),
        ("servicios/ruta del prompt", servicios, ruta_prompt.as_str()),
    ];
    let ausentes: Vec<String> = exigidos
        .into_iter()
        .filter(|(_, documento, rotulo)| !documento.contains(rotulo))
        .map(|(caso, _, rotulo)| format!("{caso}: {rotulo}"))
        .collect();

    assert!(
        ausentes.is_empty(),
        "los manuales vigentes han perdido estos recorridos críticos:\n{}",
        ausentes.join("\n")
    );
}

