/// Consentir una fuente nativa debe aceptar **la que se pulsó**, no otra cualquiera.
///
/// # Qué vigila, y por qué importa más que las demás
/// Reproduce el hueco que Claude encontró el 2026-09-13: la barrera anterior construía
/// `AccionProyectoIa::AceptarFuente` **a mano**, así que el cable entre el botón de una tarjeta
/// y el nombre que viaja en la acción no lo comprobaba nadie. Con una sola línea alterada
/// —`AceptarFuente("CLAUDE.md")` fijo— las 444 pruebas seguían en verde, y la persona podía
/// **leer un archivo y consentir otro**. Eso derrota el mecanismo de huellas completo.
///
/// # Cómo lo comprueba
/// Con **dos** fuentes nativas presentes, porque con una sola acertar es inevitable. Pulsa por
/// la interfaz real: primero la cabecera de la fuente —`Aceptar esta versión` **no existe** hasta
/// desplegarla, porque el `CollapsingHeader` nace plegado— y después el botón. Luego exige en
/// disco que la pulsada quedó consentida **y la otra intacta**, y repite con la segunda para que
/// ningún valor fijo pueda pasar.
#[test]
fn consentir_una_fuente_acepta_la_que_se_pulso_y_no_otra() {
    use crate::ui::proyecto_ia_modal::{
        aplicar_accion_para_prueba, cargar_editor_para_prueba, dibujar_contenido_para_prueba,
        AccionProyectoIa, PestanaProyectoIa,
    };

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("consentir-la-fuente-pulsada");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("identificar proyecto");

    // Dos fuentes con contenido distinto: si se aceptara la equivocada, la huella lo delata.
    std::fs::write(raiz.join("AGENTS.md"), "# Reglas de AGENTS\n").expect("crear AGENTS.md");
    std::fs::write(raiz.join("CLAUDE.md"), "# Reglas de CLAUDE\n").expect("crear CLAUDE.md");
    app.agentes.espacio_de_trabajo = raiz.clone();

    let contexto = crate::proyecto_trabajo::RepositorioProyecto::contexto_para_vista_previa(&raiz)
        .expect("contexto del proyecto");

    let incorporada = |nombre: &str| -> bool {
        crate::sesiones_agentes::detectar_fuentes_nativas(&contexto)
            .expect("revisar fuentes")
            .into_iter()
            .find(|f| f.nombre == nombre)
            .map(|f| f.incorporada)
            .unwrap_or(false)
    };

    // Se pulsa AGENTS.md **a propósito**: una mutación que fijara "CLAUDE.md" pasaría
    // desapercibida si la prueba pulsara justo esa.
    for (pulsada, la_otra) in [("AGENTS.md", "CLAUDE.md"), ("CLAUDE.md", "AGENTS.md")] {
        let mut editor = cargar_editor_para_prueba(&app).expect("cargar editor");
        editor.pestana = PestanaProyectoIa::Instrucciones;

        let mut accion_del_boton = AccionProyectoIa::Ninguna;
        let pulsados = crate::arnes_interfaz::hacer_clics_en_textos(
            &mut app,
            |app, ui| {
                let accion = dibujar_contenido_para_prueba(app, &mut editor, Idioma::Espanol, ui);
                if accion != AccionProyectoIa::Ninguna {
                    accion_del_boton = accion;
                }
            },
            &[pulsada, "Aceptar esta versión"],
        );
        assert_eq!(
            pulsados, 2,
            "no se pudo desplegar {pulsada} y pulsar su botón: se pulsaron {pulsados} de 2"
        );

        // Lo decisivo: el nombre que viaja en la acción es el de la tarjeta pulsada.
        assert_eq!(
            accion_del_boton,
            AccionProyectoIa::AceptarFuente(pulsada.to_string()),
            "el botón de {pulsada} debe pedir consentir {pulsada}, no otra fuente"
        );

        let ya_estaba = incorporada(la_otra);
        aplicar_accion_para_prueba(
            &mut app,
            &mut editor,
            accion_del_boton.clone(),
            Idioma::Espanol,
        );

        assert!(
            incorporada(pulsada),
            "{pulsada} debe quedar consentida tras pulsar su propio botón"
        );
        assert_eq!(
            incorporada(la_otra),
            ya_estaba,
            "consentir {pulsada} no debe alterar el consentimiento de {la_otra}"
        );
    }

    std::fs::remove_dir_all(raiz).expect("limpiar carpeta de prueba");
}

/// Comprueba que las plantillas personalizadas de usuario residen en Preferencias y
/// quedan estrictamente excluidas del Markdown exportado (_AI.md), donde solo deben figurar
/// las tres plantillas de serie (P3-B).
#[test]
fn las_plantillas_de_usuario_no_se_cuelan_en_el_markdown_exportado() {
    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("plantillas-usuario-markdown");
    std::fs::create_dir_all(raiz.join(".mmcelt")).expect("crear carpeta portable");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("iniciar proyecto");
    app.agentes.espacio_de_trabajo = raiz.clone();

    // Guardar una plantilla personalizada en las preferencias del usuario
    let nombre_secreto = "Plantilla Personalizada del Usuario";
    let contenido_secreto =
        "Encargo ultra confidencial de prueba que jamás debe exportarse a _AI.md";
    app.presentacion_mut()
        .preferencias()
        .plantillas_usuario
        .push(crate::preferencias::PlantillaUsuario {
            nombre: nombre_secreto.to_owned(),
            contenido: contenido_secreto.to_owned(),
        });

    // Comprobar persistencia y serialización en Preferencias
    let datos = aislar_datos("plantillas_usuario_pref");
    app.presentacion_mut()
        .preferencias()
        .guardar_en(datos.carpeta())
        .expect("guardar preferencias con plantilla de usuario");
    let cargadas = crate::preferencias::Preferencias::cargar_de(datos.carpeta())
        .expect("cargar preferencias con plantilla de usuario");
    assert_eq!(cargadas.plantillas_usuario.len(), 1);
    assert_eq!(cargadas.plantillas_usuario[0].nombre, nombre_secreto);
    assert_eq!(cargadas.plantillas_usuario[0].contenido, contenido_secreto);

    // Exportar el markdown para IA en todos los idiomas y comprobar que NUNCA incluye la plantilla de usuario
    for idioma in Idioma::TODOS {
        let md = crate::ai_export::exportar_markdown_para_ia(&app.mapa.proyecto, idioma);
        assert!(
            !md.contains(nombre_secreto),
            "el markdown exportado en {idioma:?} contiene el nombre de la plantilla de usuario"
        );
        assert!(
            !md.contains(contenido_secreto),
            "el markdown exportado en {idioma:?} contiene el contenido de la plantilla de usuario"
        );
        // Debe contener exclusivamente las 3 de serie
        for de_serie in crate::ai_export::PlantillaEncargo::TODAS {
            assert!(
                md.contains(de_serie.encabezado_markdown(idioma)),
                "el markdown exportado en {idioma:?} debe contener la plantilla de serie {}",
                de_serie.encabezado_markdown(idioma)
            );
        }
    }

    std::fs::remove_dir_all(raiz).expect("limpiar carpeta temporal");
}

/// Comprueba que en la pestaña de plantillas se puede elegir una plantilla (de serie o de usuario)
/// mediante selector y aplicarla explícitamente al encargo con el botón «Aplicar», y guardar el
/// encargo actual como plantilla global de usuario (P3-B).
#[test]
fn guardar_y_aplicar_plantillas_de_usuario_en_pestana_plantillas() {
    use crate::ui::proyecto_ia_modal::{
        aplicar_accion_para_prueba, dibujar_contenido_para_prueba, AccionProyectoIa,
        EstadoEditorProyectoIa, PestanaProyectoIa,
    };

    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();
    let raiz = carpeta_temporal_contexto("pestana-plantillas-usuario");
    crate::proyecto_trabajo::RepositorioProyecto::abrir_o_inicializar(&raiz)
        .expect("iniciar proyecto");
    app.agentes.espacio_de_trabajo = raiz.clone();

    let mut editor = EstadoEditorProyectoIa {
        raiz_proyecto: std::fs::canonicalize(&raiz).expect("canonizar raíz"),
        pestana: PestanaProyectoIa::Plantillas,
        reglas: String::new(),
        encargo: "Encargo inicial que voy a guardar como plantilla".to_owned(),
        idioma_documento: Idioma::Espanol,
        fuentes: Vec::new(),
        indice_plantilla_seleccionada: 0,
        nombre_nueva_plantilla: "Mi Nueva Plantilla".to_owned(),
    };

    // 1. Comprobar que en todos los idiomas la pestaña Plantillas dibuja los controles exigidos por P3-B
    for idioma in Idioma::TODOS {
        let textos = crate::arnes_interfaz::textos_de(&mut app, |app, ui| {
            dibujar_contenido_para_prueba(app, &mut editor, idioma, ui);
        });
        assert!(
            textos
                .iter()
                .any(|t| t.contains(Texto::ProyectoIaGuardarComoPlantilla.en(idioma))),
            "Falta el botón guardar como plantilla en {idioma:?}: {textos:?}"
        );
        assert!(
            textos
                .iter()
                .any(|t| t.contains(Texto::ProyectoIaAplicarPlantilla.en(idioma))),
            "Falta el botón aplicar plantilla en {idioma:?}: {textos:?}"
        );
    }

    // 2. Guardar el encargo como plantilla de usuario
    let nombre = editor.nombre_nueva_plantilla.clone();
    let accion_guardar = AccionProyectoIa::GuardarComoPlantilla(nombre);
    let conservar =
        aplicar_accion_para_prueba(&mut app, &mut editor, accion_guardar, Idioma::Espanol);
    assert!(
        conservar,
        "guardar como plantilla debe conservar la ventana abierta"
    );

    let plantillas_usuario = &app.presentacion_mut().preferencias().plantillas_usuario;
    assert_eq!(
        plantillas_usuario.len(),
        1,
        "debe existir exactamente una plantilla de usuario guardada"
    );
    assert_eq!(plantillas_usuario[0].nombre, "Mi Nueva Plantilla");
    assert_eq!(
        plantillas_usuario[0].contenido,
        "Encargo inicial que voy a guardar como plantilla"
    );

    // 3. Modificar el encargo
    editor.encargo = "Texto borrador temporal".to_owned();

    // 4. Cambiar el índice seleccionado NO debe alterar el encargo hasta que se pulse «Aplicar»
    editor.indice_plantilla_seleccionada = 3; // Corresponde a la primera plantilla de usuario (después de las 3 de serie)
    assert_eq!(
        editor.encargo, "Texto borrador temporal",
        "cambiar el desplegable sin aplicar no debe modificar el encargo"
    );

    std::fs::remove_dir_all(raiz).expect("limpiar carpeta temporal");
}

/// Verifica que los títulos de las plantillas de serie destinados a la interfaz de usuario
/// son prosa limpia para personas (sin almohadillas `#` ni saltos de línea `\n`), mientras
/// que los encabezados del documento `_AI.md` conservan su formato Markdown de nivel 3 (`### `).
#[test]
fn los_titulos_de_plantilla_para_interfaz_son_prosa_limpia_sin_markdown_en_los_seis_idiomas() {
    for idioma in Idioma::TODOS {
        for plantilla in crate::ai_export::PlantillaEncargo::TODAS {
            let titulo_ui = plantilla.titulo_interfaz(idioma);
            assert!(
                !titulo_ui.starts_with('#'),
                "el título de interfaz de {plantilla:?} en {idioma:?} no debe empezar por almohadilla: «{titulo_ui}»"
            );
            assert!(
                !titulo_ui.contains('#'),
                "el título de interfaz de {plantilla:?} en {idioma:?} no debe contener almohadillas: «{titulo_ui}»"
            );
            assert!(
                !titulo_ui.contains('\n'),
                "el título de interfaz de {plantilla:?} en {idioma:?} no debe contener saltos de línea: «{titulo_ui}»"
            );
            assert!(
                titulo_ui.trim().len() >= 10,
                "el título de interfaz de {plantilla:?} en {idioma:?} debe tener longitud sustancial"
            );

            let encabezado_md = plantilla.encabezado_markdown(idioma);
            assert!(
                encabezado_md.starts_with("### "),
                "el encabezado Markdown de {plantilla:?} en {idioma:?} debe empezar por '### ': «{encabezado_md}»"
            );
            assert!(
                encabezado_md.ends_with('\n'),
                "el encabezado Markdown de {plantilla:?} en {idioma:?} debe terminar en salto de línea: «{encabezado_md}»"
            );
        }
    }
}

