/// Criterio 11-N (PH-0119-1): En modo solo lectura (mapa en raíz de volumen), no se escribe nada en disco:
/// guardar directo a raíz y autoguardado no tocan el archivo de mapa ni generan copias de recuperación.
#[test]
fn criterio_11_n_en_solo_lectura_no_se_escribe_nada_en_disco() {
    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    let temp_dir =
        std::env::temp_dir().join(format!("mmcelt_test_crit11_n_{}", uuid::Uuid::new_v4()));
    std::fs::create_dir_all(&temp_dir).expect("crear temp dir");
    let ruta_disco = temp_dir.join("mapa_raiz.mmcelt");
    let contenido_original = b"{\"title\": \"Original Inalterado\"}";
    std::fs::write(&ruta_disco, contenido_original).expect("escribir archivo");

    #[cfg(windows)]
    let ruta_mapa_raiz = std::path::PathBuf::from(r"O:\mapa_raiz.mmcelt");
    #[cfg(not(windows))]
    let ruta_mapa_raiz = std::path::PathBuf::from("/mapa_raiz.mmcelt");

    app.sustituir_el_mapa_abierto(
        crate::model::Proyecto::nuevo_vacio("Mapa Raiz"),
        Some(ruta_mapa_raiz),
        "Abierto",
    );

    assert!(app.es_solo_lectura_por_raiz());

    // 1. Guardar normal está bloqueado y devuelve false
    assert!(
        !app.solicitar_guardado(false),
        "guardar normal debe devolver false en solo lectura"
    );

    // 2. Autoguardado está desactivado en solo lectura y no genera recuperación en disco
    // Asignamos carpeta de datos para que el autoguardado tenga adonde escribir si no estuviera bloqueado
    app.persistencia.carpeta_datos = Some(temp_dir.clone());
    // Modificamos el mapa en memoria para que haya cambios reales pendientes de autoguardado
    app.mapa.proyecto.marcar_modificado();
    assert!(
        app.persistencia
            .autoguardado
            .ha_cambiado_desde_la_copia(&app.mapa.proyecto),
        "el mapa debe tener cambios pendientes respecto a la última copia"
    );
    // Forzamos que toque comprobar el autoguardado fijando intervalo en cero
    app.persistencia.autoguardado.intervalo = std::time::Duration::ZERO;
    assert!(
        app.persistencia.autoguardado.toca_comprobar(),
        "el autoguardado debe estar en momento de tocar"
    );

    app.procesar_autoguardado();
    let ruta_recuperacion = crate::autoguardado::ruta_recuperacion_en(&temp_dir);
    assert!(
        !ruta_recuperacion.exists(),
        "autoguardado no debe generar copias en disco en solo lectura"
    );

    // 3. El contenido del archivo original en disco permanece intacto
    let contenido_leido = std::fs::read(&ruta_disco).expect("leer archivo");
    assert_eq!(
        contenido_leido, contenido_original,
        "el archivo en disco no debe ser modificado"
    );

    std::fs::remove_dir_all(temp_dir).expect("limpiar temp");
}

/// Criterio 11-Ñ (PH-0119-1): Al trasladar el mapa a una carpeta válida se sale de solo lectura y
/// se recupera la capacidad de edición y guardado completo.
#[test]
fn criterio_11_enie_traslado_a_carpeta_recupera_edicion_y_guardado_plenos() {
    let (mut app, _ctx) = crate::arnes_interfaz::aplicacion_de_prueba();

    let temp_dir =
        std::env::temp_dir().join(format!("mmcelt_test_crit11_enie_{}", uuid::Uuid::new_v4()));
    let origen_dir = temp_dir.join("raiz_simulada");
    let destino_dir = temp_dir.join("mi_proyecto");
    std::fs::create_dir_all(&origen_dir).expect("crear origen dir");
    std::fs::create_dir_all(&destino_dir).expect("crear destino dir");

    let ruta_origen = origen_dir.join("mapa_enie.mmcelt");
    let proyecto_inicial = crate::model::Proyecto::nuevo_vacio("Mapa Enie");
    crate::storage::guardar_proyecto_en_archivo(&proyecto_inicial, &ruta_origen)
        .expect("guardar origen");

    app.sustituir_el_mapa_abierto(proyecto_inicial, Some(ruta_origen.clone()), "Abierto");

    // Simulamos que el archivo estaba en raíz asignando ruta en raíz
    #[cfg(windows)]
    let ruta_raiz_simulada = std::path::PathBuf::from(r"O:\mapa_enie.mmcelt");
    #[cfg(not(windows))]
    let ruta_raiz_simulada = std::path::PathBuf::from("/mapa_enie.mmcelt");

    app.persistencia.ruta_actual = Some(ruta_raiz_simulada);
    assert!(app.es_solo_lectura_por_raiz());

    // Trasladamos el archivo real a destino_dir
    let ruta_resultado =
        crate::traslado::ejecutar_traslado_de_mapa(&mut app, &ruta_origen, &destino_dir)
            .expect("el traslado a carpeta debe completarse");

    // Ya no estamos en solo lectura
    assert!(
        !app.es_solo_lectura_por_raiz(),
        "trasladado a carpeta de proyecto, el mapa ya no debe estar en solo lectura"
    );
    assert_eq!(app.persistencia.ruta_actual, Some(ruta_resultado.clone()));
    // C22-A: el espacio de trabajo se canoniza en el único punto donde se calcula.
    assert_eq!(
        app.agentes.espacio_de_trabajo,
        destino_dir.canonicalize().expect("canonizar destino")
    );

    // Ahora la edición de nodos sí funciona
    let nodos_antes = app.mapa().proyecto.nodes.len();
    app.anadir_hijo_al_seleccionado();
    assert_eq!(
        app.mapa().proyecto.nodes.len(),
        nodos_antes + 1,
        "trasladado a proyecto, debe poderse añadir nodos de nuevo"
    );

    // Y el guardado normal sí funciona
    assert!(
        app.solicitar_guardado(false),
        "trasladado a proyecto, el guardado normal debe funcionar"
    );

    std::fs::remove_dir_all(temp_dir).expect("limpiar temp");
}

/// Criterio 11-G (PH-0119-1): Intentar conectar un agente con la raíz de un volumen devuelve error
/// y no escribe la raíz como espacio de trabajo en la configuración del agente.
#[test]
fn criterio_11_g_conectar_con_raiz_de_volumen_devuelve_error_y_no_autoriza_el_disco() {
    #[cfg(windows)]
    let raiz_disco = std::path::PathBuf::from(r"O:\");
    #[cfg(not(windows))]
    let raiz_disco = std::path::PathBuf::from("/");

    let agente = agente_de_prueba(
        "crit11_g.json",
        crate::conectores::FormatoConfiguracion::Json,
    );

    let resultado = crate::conectores::conectar(&agente, &raiz_disco);
    assert!(
        resultado.is_err(),
        "conectar un agente con la raíz de un volumen debe ser rechazado con error"
    );
    match resultado.unwrap_err() {
        crate::error::AppError::CarpetaProyectoInvalida { ruta, .. } => {
            assert_eq!(ruta, raiz_disco);
        }
        otro => panic!("esperado CarpetaProyectoInvalida, obtenido: {otro:?}"),
    }

    assert!(
        !agente.ruta_configuracion.exists(),
        "no debe haberse creado ni modificado el archivo de configuración del agente"
    );
}

/// Comprueba que los 9 textos del diálogo de aviso temprano de mapa en raíz están traducidos
/// en los seis idiomas oficiales y son distintos entre sí.
#[test]
fn criterio_11_traducciones_de_deteccion_temprana_en_seis_idiomas_distintas_entre_si() {
    let textos_del_dialogo = [
        (
            "ModalMapaEnRaizTitulo",
            crate::textos::Texto::ModalMapaEnRaizTitulo,
        ),
        (
            "ModalMapaEnRaizExplicacion",
            crate::textos::Texto::ModalMapaEnRaizExplicacion,
        ),
        (
            "BotonMoverMapaACarpeta",
            crate::textos::Texto::BotonMoverMapaACarpeta,
        ),
        (
            "BotonCrearNuevoEnCarpeta",
            crate::textos::Texto::BotonCrearNuevoEnCarpeta,
        ),
        (
            "BotonMantenerEnRaizSinIa",
            crate::textos::Texto::BotonMantenerEnRaizSinIa,
        ),
        (
            "AvisoMapaMovidoConExito",
            crate::textos::Texto::AvisoMapaMovidoConExito,
        ),
        (
            "ErrorDestinoYaExiste",
            crate::textos::Texto::ErrorDestinoYaExiste,
        ),
        (
            "ErrorNoSePudoMoverMapa",
            crate::textos::Texto::ErrorNoSePudoMoverMapa,
        ),
        (
            "ModalSinCarpetaDeProyecto",
            crate::textos::Texto::ModalSinCarpetaDeProyecto,
        ),
    ];

    for (nombre, texto) in textos_del_dialogo {
        let mut vistos: std::collections::HashMap<&str, crate::textos::Idioma> =
            std::collections::HashMap::new();
        for &idioma in &crate::textos::Idioma::TODOS {
            let traduccion = texto.en(idioma);
            assert!(
                !traduccion.trim().is_empty(),
                "«{nombre}» no puede quedar vacío en {idioma:?}"
            );
            if let Some(anterior) = vistos.insert(traduccion, idioma) {
                panic!(
                    "«{nombre}» repite el mismo texto en {anterior:?} y en {idioma:?}: \
                     «{traduccion}». Un idioma sin traducir deja al usuario sin entender las opciones."
                );
            }
        }
        assert_eq!(
            vistos.len(),
            crate::textos::Idioma::TODOS.len(),
            "«{nombre}» debe tener una traducción distinta por cada idioma"
        );
    }
}

/// Criterio 12-A (PH-0119-3): Con un mapa abierto, el espacio de trabajo es siempre
/// la carpeta donde reside el mapa. Caso real reportado: mapa en una subcarpeta
/// (`PRUEBASMMCelt/prueba_mmcelt_01111/mapa.mmcelt`) con preferencia previa en la carpeta madre
/// (`PRUEBASMMCelt`). La propuesta debe ser la subcarpeta, nunca la carpeta madre.
#[test]
fn criterio_12_a_con_mapa_abierto_el_espacio_de_trabajo_es_la_carpeta_del_mapa() {
    let temp_dir = std::env::temp_dir().join(format!("mmcelt_crit12_a_{}", uuid::Uuid::new_v4()));
    let madre_pref = temp_dir.join("PRUEBASMMCelt");
    let subcarpeta_mapa = madre_pref.join("prueba_mmcelt_01111");
    std::fs::create_dir_all(&subcarpeta_mapa).expect("crear subcarpeta de prueba");

    let ruta_mapa = subcarpeta_mapa.join("mapa.mmcelt");
    let proyecto = crate::model::Proyecto::nuevo_vacio("Mapa 12-A");
    crate::storage::guardar_proyecto_en_archivo(&proyecto, &ruta_mapa).expect("guardar mapa");

    let propuesto = crate::conectores::espacio_trabajo_propuesto(
        madre_pref.to_str().unwrap(),
        Some(&ruta_mapa),
    );

    assert_eq!(
        propuesto, subcarpeta_mapa,
        "Criterio 12-A: con un mapa abierto, el espacio de trabajo debe ser la subcarpeta del mapa, no la carpeta madre de la preferencia previa"
    );

    std::fs::remove_dir_all(temp_dir).expect("limpiar temp");
}

/// Criterio 12-B (PH-0119-3): Si la carpeta del mapa no es utilizable (por ejemplo, reside en la raíz de un volumen),
/// no se busca ninguna carpeta alternativa ni se cae en la preferencia de un proyecto previo: nunca se adopta
/// la carpeta de un proyecto ajeno.
